    -- Route notes, solo tips, and other guidance prose.
    ["/reload if stuck"] = "/如果卡住则重新加载",
    ["1"] = "1",
    ["1. When he's threatening to roll left, strafe right (and vice versa). You get 8-10 seconds after he emotes. 2. Stand by the front (armor plate), pulling enemies to you and killing them near the armor plate. 3. Kill ^Hideous Amalgamation^ on the armor to pry up the armor plates. 4. Prying up an armor plate exposes a ^Burning Tendon^. Kill it to advance. Doing this 3x will end the fight."] = "1. 当他威胁要向左翻滚时，向右扫射（反之亦然）。当他表现出情绪后，你有 8 到 10 秒的时间。 2.站在最前面（装甲板），将敌人拉向你并杀死装甲板附近的敌人。 3.杀死装甲上的^Hideous Amalgamation^来撬起装甲板。 4. 撬起装甲板会暴露出^Burning Tendon^。杀掉它才能前进。执行此操作 3 次即可结束战斗。",
    ["2"] = "2",
    ["3"] = "3",
    ["Action Button in Beam"] = "光束中的操作按钮",
    ["After a brief dialog, kill ^Raszageth the Storm-Eater^!"] = "简短对话后，杀死 ^Raszageth the Storm-Eater^！",
    ["After activating the ^Titan Console^, kill several waves of adds from the previous room to unlock the door to the next room."] = "激活^Titan Console^后，杀死前一个房间的几波小怪，以解锁下一个房间的门。",
    ["After arriving at ^The Torment Chambers^, follow the path to ^Soulrender Dormazain^."] = "到达^The Torment Chambers^后，沿着路径前往^Soulrender Dormazain^。",
    ["After arriving back in Antorus, follow the path to the left to reach ^Portal Keeper Hasabel^."] = "回到安托鲁斯后，沿着左边的路径到达^Portal Keeper Hasabel^。",
    ["After arriving back in ^Halls of the Faithful^, follow the path all the way around to ^Artificer Xy'mox^. Kill the trash, and ^Prince Renathal^ will show up to open the gate."] = "返回 ^Halls of the Faithful^ 后，沿着路径一路前往 ^Artificer Xy'mox^。杀死小怪，^Prince Renathal^ 就会出现并打开大门。",
    ["After arriving back in ^The Grand Walk^, follow the path up to where you killed ^Shriekwing^. This time, take the path right/south to end up in ^Halls of the Faithful^."] = "返回 ^The Grand Walk^ 后，沿着路径前往杀死 ^Shriekwing^ 的地方。这次，沿着右/南路径到达 ^Halls of the Faithful^。",
    ["After arriving back in the ^Ring of Containment^, head straight ahead towards the map exit labeled ^The Oblivion Door^."] = "回到 ^Ring of Containment^ 后，径直朝标有 ^The Oblivion Door^ 的地图出口走去。",
    ["After arriving back on the ^Wyrmrest Summit^, talk to ^Kalecgos^ to advance."] = "返回 ^Wyrmrest Summit^ 后，与 ^Kalecgos^ 交谈以继续前进。",
    ["After arriving in ^Crown of Gorgoa^, follow the path North to ^Guardian of the First Ones^."] = "到达 ^Crown of Gorgoa^ 后，沿着路径向北到达 ^Guardian of the First Ones^。",
    ["After arriving in ^The Burning Throne^, proceed down the long path and kill ^Tarneth^ to open the door. Continue west to the map exit labeled ^The World Soul^."] = "到达^The Burning Throne^后，沿着长路前进并杀死^Tarneth^以打开门。继续向西到达标记为 ^The World Soul^ 的地图出口。",
    ["After arriving in ^The Burning Throne^, proceed down the path and kill ^Tarneth^ to open the door. Jump in the hole behind the next trash pack."] = "到达^The Burning Throne^后，沿着路径前进并杀死^Tarneth^以打开门。跳进下一个小怪堆后面的洞里。",
    ["After arriving in ^The Emerald Nightmare^, proceed forward to start the encounter with ^Dragons of Nightmare^."] = "到达^The Emerald Nightmare^后，继续前进，开始与^Dragons of Nightmare^的战斗。",
    ["After arriving in ^The Oblivion Door^, clear all trash to start the encounter with ^Zul, Reborn^."] = "到达^The Oblivion Door^后，清除所有小怪以开始与^Zul, Reborn^的战斗。",
    ["After arriving in ^The Twisting Nether^, work your way down the path, killing trash all the way until you reach ^Kil'jaeden^."] = "到达 ^The Twisting Nether^ 后，沿路向下前进，一路清理小怪，直到抵达 ^Kil'jaeden^。",
    ["After arriving in the room with ^Lady Inerva Darkvein^, kill all the trash to trigger some dialog, then kill the boss."] = "带着^Lady Inerva Darkvein^到达房间后，杀死所有小怪以触发一些对话，然后杀死首领。",
    ["After arriving on ^Wyrmrest Summit^, talk to ^Kalecgos^ to advance."] = "到达 ^Wyrmrest Summit^ 后，与 ^Kalecgos^ 交谈即可前进。",
    ["After back in the ^Ring of Containment^, head to the leftmost map exit labeled ^Archives of Eternity^."] = "回到 ^Ring of Containment^ 后，前往最左边的地图出口，标记为 ^Archives of Eternity^。",
    ["After clearing the final trash wave, follow the path up to engage ^The Spirit Kings^."] = "清除最后一波小怪后，沿着路径向上攻击^The Spirit Kings^。",
    ["After clicking the ^Hammer^, proceed down the stairs towards the west side of the room and the map exit labeled ^The Abyssal Throne^."] = "点击 ^Hammer^ 后，沿着楼梯朝房间西侧和标记为 ^The Abyssal Throne^ 的地图出口走去。",
    ["After clicking the ^Tears of Elune^, jump off the edge to die and respawn back in ^Chamber of the Moon^."] = "点击 ^Tears of Elune^ 后，跳下边缘死亡并在 ^Chamber of the Moon^ 中重生。",
    ["After clicking the ^Tidestone^, backtrack a bit and take a right towards the map exit labeled ^Terrace of the Moon^. You will pass a giant statue and begin climbing a long, winding staircase."] = "点击 ^Tidestone^ 后，原路返回并向右转至标记为 ^Terrace of the Moon^ 的地图出口。您将经过一座巨大的雕像，并开始攀登长长的蜿蜒楼梯。",
    ["After clicking the first orb, follow the path all the way north to kill ^Radiance of Azshara^. Clear all the trash to start the encounter."] = "点击第一个球后，沿着小路一路向北杀死^Radiance of Azshara^。清除所有小怪以开始战斗。",
    ["After clicking the lever, travel through the opened door to the northeast and follow it around to a big clearing. Take the southwestern door."] = "点击控制杆后，穿过打开的门向东北方向走，然后沿着它走到一大片空地。走西南门。",
    ["After clicking the orb, the path opens to fight ^Lady Ashvane^."] = "点击球体后，将打开与 ^Lady Ashvane^ 战斗的路径。",
    ["After coming out of the water, take the path south towards the map exit labeled ^Darkest Depths^."] = "从水中出来后，沿着向南的路径前往标记为 ^Darkest Depths^ 的地图出口。",
    ["After completing the ^Hellfire Assault^ encounter, you will find ^Iron Reaver^ spawned right in front of you."] = "完成 ^Hellfire Assault^ 战斗后，你会发现 ^Iron Reaver^ 就在你面前出现。",
    ["After completing the ^Norushen^ encounter, move ahead into the next room and clear all trash to start the fight with ^Sha of Pride^."] = "完成 ^Norushen^ 战斗后，前进到下一个房间并清除所有小怪，开始与 ^Sha of Pride^ 战斗。",
    ["After completing the ^Spoils of Pandaria^ encounter, follow the path ahead to reach ^Thok the Bloodthirsty^."] = "完成^Spoils of Pandaria^战斗后，沿着前面的路径到达^Thok the Bloodthirsty^。",
    ["After defeating ^Aggramar^, speak to ^Magni Bronzebeard^ and tell him you're ready."] = "击败 ^Aggramar^ 后，与 ^Magni Bronzebeard^ 交谈并告诉他你已经准备好了。",
    ["After defeating ^Aluriel^, take the path into the building to the northeast, and clear trash as you approach the map exit labeled ^Astromancer's Rise^."] = "击败 ^Aluriel^ 后，沿路径进入东北部的建筑物，并在接近标记为 ^Astromancer's Rise^ 的地图出口时清除小怪。",
    ["After defeating ^Alysrazor^, you will find ^Shannox^ patrolling around the main circular path of the instance. If he hasn't spawned yet, kill random trash until he emotes."] = "击败^Alysrazor^后，你会发现^Shannox^在实例的主圆形路径周围巡逻。如果他还没有出现，就随机杀死小怪，直到他表现出来。",
    ["After defeating ^Amber-Shaper Un'sok^, exit the room to the west and head straight for ^Grand Empress Shek'zeer^. Clear all the trash to spawn the boss."] = "击败^Amber-Shaper Un'sok^后，从西边退出房间，直奔^Grand Empress Shek'zeer^。清除所有小怪以出现 首领。",
    ["After defeating ^Anub'Rekhan^, backtrack out of his room and take a left. Stay to the left while following the path to ^Grand Widow Faerlina^."] = "击败 ^Anub'Rekhan^ 后，原路离开他的房间并左转。沿路保持靠左，前往 ^Grand Widow Faerlina^。",
    ["After defeating ^Argaloth^, head to the north wing to face ^Alizabal^."] = "击败^Argaloth^后，前往北翼面对^Alizabal^。",
    ["After defeating ^Artificer Xy'mox^, backtrack out of the room and follow the path to the stairs leading to ^Feast of Arrogance^."] = "击败^Artificer Xy'mox^后，原路退出房间，沿着路径到达通往^Feast of Arrogance^的楼梯。",
    ["After defeating ^Beth'tilac^, follow the path all the way to the southeastern corner of the map to reach ^Lord Rhyolith^. Kill trash on your path, to minimize the amount you have to kill later to spawn ^Shannox^."] = "击败^Beth'tilac^后，沿着小路一直走到地图的东南角即可到达^Lord Rhyolith^。杀死路径上的小怪，以最大程度地减少稍后出现 ^Shannox^ 所需杀死的小怪数量。",
    ["After defeating ^Brackenspore^, go back out the way you came and travel far west to reach a portal."] = "击败 ^Brackenspore^ 后，按原路返回，向西行驶很远到达传送门。",
    ["After defeating ^Champion of the Light^, continue down the path, clearing trash on the way to ^Grong^."] = "击败 ^Champion of the Light^ 后，继续沿着路径前进，清除前往 ^Grong^ 途中的小怪。",
    ["After defeating ^Chimaeron^, go back out to the main ring and follow the path to the ^Orb of Culmination^. Interact with it to begin the encounter with ^Nefarian^."] = "击败 ^Chimaeron^ 后，返回主环并沿着路径前往 ^Orb of Culmination^。与其交互以开始与 ^Nefarian^ 的战斗。",
    ["After defeating ^Cho'gall^, jump in the hole in the middle of the room."] = "击败^Cho'gall^后，跳进房间中间的洞里。",
    ["After defeating ^Conclave of Wind^, collect the loot chest on the north platform, then click on the nearby ^Slipstream^ to be flown to the main platform to face ^Al'Akir^."] = "击败^Conclave of Wind^后，在北平台收集战利品箱，然后点击附近的^Slipstream^飞到主平台面对^Al'Akir^。",
    ["After defeating ^Conclave of the Chosen^, exit the room to the east, and take the elevator up."] = "击败^Conclave of the Chosen^后，从东边退出房间，乘电梯上去。",
    ["After defeating ^Conclave^, exit the room to the east and ride the elevator up to the ^Walk of Kings^."] = "击败^Conclave^后，从东边退出房间并乘坐电梯到达^Walk of Kings^。",
    ["After defeating ^Council of Elders^, go through the door behind them. As you cross the bridge, there will be a cutscene and you will fall below."] = "击败^Council of Elders^后，穿过他们身后的门。当你过桥时，会有一个过场动画，你会掉到下面。",
    ["After defeating ^Dark Animus^, take the northern stairwell out of the room and follow the path to open a masked gate."] = "击败^Dark Animus^后，从北边的楼梯间走出房间，沿着路径打开一扇蒙面门。",
    ["After defeating ^Durumu^, follow the linear path through several sets of stairs and make your way to ^Primordius^."] = "击败 ^Durumu^ 后，沿着直线路径穿过几组楼梯，前往 ^Primordius^。",
    ["After defeating ^Echo of Neltharion^, walk into the room behind him and jump into the purple circle to reach ^Edge of Oblivion^."] = "击败^Echo of Neltharion^后，走进他身后的房间，跳入紫色圆圈到达^Edge of Oblivion^。",
    ["After defeating ^Elerethe^, backtrack to the portal and return to ^Core of the Nightmare^. You can jump off the ledge for a shortcut."] = "击败^Elerethe^后，原路返回传送门并返回^Core of the Nightmare^。你可以从壁架上跳下来走捷径。",
    ["After defeating ^Elisande^, approach the teleporter outside the room and choose ^Font of Night^ as your destination."] = "击败^Elisande^后，接近房间外的传送器并选择^Font of Night^作为目的地。",
    ["After defeating ^Faerlina^, head southeast and follow the path back north all the way to ^Maexxna^."] = "击败 ^Faerlina^ 后，向东南前进，再沿路一路向北前往 ^Maexxna^。",
    ["After defeating ^Fel Lord Zakuun^, climb out of this area the way you came, and go all the way east to reach ^Xhul'horac^. Kill trash to start the encounter."] = "击败^Fel Lord Zakuun^后，按来时的路爬出该区域，一路向东到达^Xhul'horac^。杀死小怪来开始战斗。",
    ["After defeating ^Felhounds of Sargeras^, backtrack towards the closest intersection and keep to the left. Kill a trash pack to spawn a ^Lightforged Teleportation Pad^. Use it to cross the chasm, then proceed ahead to ride an elevator up."] = "击败 ^Felhounds of Sargeras^ 后，原路返回最近的十字路口并保持左侧行驶。杀死小怪群以出现 ^Lightforged Teleportation Pad^。用它穿过峡谷，然后继续乘坐电梯上去。",
    ["After defeating ^Flamebender Ka'graz^, head slightly east and then follow the path north to reach ^Kromog^."] = "击败^Flamebender Ka'graz^后，稍微向东走，然后沿着路径向北到达^Kromog^。",
    ["After defeating ^Garothi Worldbreaker^, continue straight ahead on the path to ^Felhounds of Sargeras^."] = "击败^Garothi Worldbreaker^后，继续沿着通往^Felhounds of Sargeras^的道路前进。",
    ["After defeating ^Garothi Worldbreaker^, cross the bridge and take a left to locate a teleporter. Select ^The Burning Throne^ to skip ahead to ^Aggramar^."] = "击败^Garothi Worldbreaker^后，过桥并向左转找到传送器。选择 ^The Burning Throne^ 以跳至 ^Aggramar^。",
    ["After defeating ^General Nazgrim^, take the elevator down in the northeastern section of the room."] = "击败^General Nazgrim^后，乘坐房间东北部的电梯下去。",
    ["After defeating ^Goroth^, proceed straight ahead past the group of NPCs and go up the stairs to find ^Demonic Inquisition^."] = "击败 ^Goroth^ 后，继续直行，经过一群 NPC 并上楼，找到 ^Demonic Inquisition^。",
    ["After defeating ^Gothik the Harvester^, take the south exit and follow the path around to reach ^The Four Horsemen^."] = "击败 ^Gothik the Harvester^ 后，从南出口离开并沿路前往 ^The Four Horsemen^。",
    ["After defeating ^Grobbulus^, exit south from the top of the room. Walk across a pipe as you follow the path around to find ^Gluth^."] = "击败 ^Grobbulus^ 后，从房间上层的南侧出口离开。沿路走过一根管道，前往 ^Gluth^。",
    ["After defeating ^Grong^, follow the winding path around to ^Jadefire Masters^. Kill the trash to start the encounter."] = "击败^Grong^后，沿着蜿蜒的小路前往^Jadefire Masters^。杀死小怪来开始战斗。",
    ["After defeating ^Hagara^, click the ^portal^ to return to ^Wyrmrest Summit^."] = "击败^Hagara^后，点击^portal^返回^Wyrmrest Summit^。",
    ["After defeating ^Halfus^, follow the path straight south to reach ^Theralion and Valiona^. Kill trash to begin the gauntlet on the way to the boss."] = "击败^Halfus^后，沿着小路一直向南到达^Theralion and Valiona^。杀死小怪，在通往 首领 的路上开始挑战。",
    ["After defeating ^Heigan^, exit to the east and follow the path around to ^Loatheb^."] = "击败 ^Heigan^ 后，从东侧出口离开并沿路前往 ^Loatheb^。",
    ["After defeating ^High Botanist Tel'arn^, backtrack towards the map exit labeled ^The Nighthold^."] = "击败 ^High Botanist Tel'arn^ 后，原路返回标记为 ^The Nighthold^ 的地图出口。",
    ["After defeating ^Il'gynoth^, interact with the nearby ^Re-origination Anchor^ to be flown back to the top."] = "击败^Il'gynoth^后，与附近的^Re-origination Anchor^互动即可飞回顶部。",
    ["After defeating ^Immerseus^, take the tall western stairwell behind him."] = "击败^Immerseus^后，走他身后高高的西楼梯井。",
    ["After defeating ^Iron Maidens^, take the southern path and keep to the left until you reach ^Hans'gar and Franzok^. After a brief dialog, kill the trash to start the encounter."] = "击败^Iron Maidens^后，走南边的道路并保持向左行驶，直到到达^Hans'gar and Franzok^。简短的对话后，杀死小怪即可开始战斗。",
    ["After defeating ^Iron Qon^, proceed through the new door behind them and follow the linear path to the ^Twin Empyreans^."] = "击败^Iron Qon^后，穿过他们身后的新门，沿着线性路径到达^Twin Empyreans^。",
    ["After defeating ^Jadefire Masters^, go up the stairs behind them toward the map exit labeled ^The Heart of the Empire^. Open the door to continue."] = "击败 ^Jadefire Masters^ 后，上他们身后的楼梯，前往标记为 ^The Heart of the Empire^ 的地图出口。打开门继续。",
    ["After defeating ^Jadefire Masters^, proceed up the long staircase behind them to reach ^Grong, the Revenant^. Kill trash at the top of the stairs to start the encounter."] = "击败^Jadefire Masters^后，沿着他们身后的长楼梯前进到达^Grong, the Revenant^。杀死楼梯顶部的小怪即可开始战斗。",
    ["After defeating ^Kazzara^, click the vent behind ^Neltharion^ and you will be able to jump down and skip ahead to the ^Echo of Neltharion^ encounter."] = "击败^Kazzara^后，点击^Neltharion^后面的通风口，你将能够跳下来并向前跳到^Echo of Neltharion^战斗。",
    ["After defeating ^King Rastakhan^, take the western exit from the room and make your way towards the map exit labeled ^Port of Zandalar^. Interact with the ^7th Legion Gryphon^ to be flown to the next area."] = "击败 ^King Rastakhan^ 后，从房间的西出口前往标记为 ^Port of Zandalar^ 的地图出口。与 ^7th Legion Gryphon^ 互动以飞往下一个区域。",
    ["After defeating ^King Rastakhan^, take the western exit from the room and make your way towards the map exit labeled ^Port of Zandalar^. Interact with the ^Riding Pterrordax^ to be flown to the next area."] = "击败 ^King Rastakhan^ 后，从房间的西面出口前往标记为 ^Port of Zandalar^ 的地图出口。与 ^Riding Pterrordax^ 互动以飞往下一个区域。",
    ["After defeating ^Krosus^, backtrack up to the main courtyard and click the portal to teleport to ^The Nightspire^. After landing, proceed ahead into the boss room."] = "击败^Krosus^后，原路返回主庭院，点击传送门传送至^The Nightspire^。落地后，继续前进，进入首领房间。",
    ["After defeating ^Lei Shi^, continue straight up the stairs to engage ^Sha of Fear^."] = "击败^Lei Shi^后，继续直接上楼梯与^Sha of Fear^交战。",
    ["After defeating ^MOTHER^, continue forward to the map exit labeled ^Ring of Containment^."] = "击败^MOTHER^后，继续前往标记为^Ring of Containment^的地图出口。",
    ["After defeating ^Magmorax^, swim across the lava to reach the southern exit labeled ^Neltharion's Sanctum^. Jump down into the hole."] = "击败 ^Magmorax^ 后，游过熔岩到达标有 ^Neltharion's Sanctum^ 的南部出口。跳进洞里。",
    ["After defeating ^Maloriak^, exit back to the main ring and head to the north exit. Kill trash, then hit the large bell at the back of the room to begin the encounter with ^Atramedes^."] = "击败^Maloriak^后，返回主环并前往北出口。杀死小怪，然后敲响房间后面的大铃，开始与 ^Atramedes^ 的战斗。",
    ["After defeating ^Megaera^, take the new exit on the east side of the room."] = "击败^Megaera^后，从房间东侧的新出口走。",
    ["After defeating ^Mekkatorque^, make your way down the long path south, and kill the trash at the end of the bridge. Interact with a ^Pterrordax^ to start the encounter with ^Stormwall Blockade^."] = "击败^Mekkatorque^后，沿着长长的小路向南走，杀死桥尽头的小怪。与 ^Pterrordax^ 交互以开始与 ^Stormwall Blockade^ 的战斗。",
    ["After defeating ^Morchok^, continue ahead into ^Wyrmrest Temple^. Interact with ^Valeera^, the dragon on the left."] = "击败^Morchok^后，继续前进进入^Wyrmrest Temple^。与左边的龙^Valeera^互动。",
    ["After defeating ^Mythrax^, follow the path north to engage the final boss, ^G'huun^."] = "击败 ^Mythrax^ 后，沿着北边的道路与最终 首领 ^G'huun^ 交战。",
    ["After defeating ^Noth^, exit to the east and follow the path around to ^Heigan the Unclean^."] = "击败 ^Noth^ 后，从东侧出口离开并沿路前往 ^Heigan the Unclean^。",
    ["After defeating ^Nythendra^, follow the path up and around towards the map exit labeled ^Core of the Nightmare^."] = "击败 ^Nythendra^ 后，沿着路径向上并绕过标记为 ^Core of the Nightmare^ 的地图出口。",
    ["After defeating ^Odyn^, talk to him and select the only dialog option available. You will be dropped into ^Helheim^."] = "击败 ^Odyn^ 后，与他交谈并选择唯一可用的对话选项。您将被放入 ^Helheim^。",
    ["After defeating ^Operator Thogar^, jump down the hole marked on the east side of the room."] = "击败^Operator Thogar^后，跳下房间东侧标记的洞。",
    ["After defeating ^Portal Keeper Hasabel^, leave the boss room and stay to the right to find the map exit labeled ^Elunaria^. Click the portal."] = "击败^Portal Keeper Hasabel^后，离开首领房间并留在右侧找到标记为^Elunaria^的地图出口。点击传送门。",
    ["After defeating ^Protectors of the Endless^, there will be a brief delay and then ^Tsulong^ will spawn at the same location."] = "击败 ^Protectors of the Endless^ 后，会有短暂的延迟，然后 ^Tsulong^ 将在同一位置出现。",
    ["After defeating ^Ra-den^, interact with the ^Re-origination Anchor^ right behind him to be flown back below."] = "击败^Ra-den^后，与他身后的^Re-origination Anchor^互动，使其飞回下方。",
    ["After defeating ^Radiance of Azshara^, leave the room the way you came and find 2 more ^Azsh'ari Channelers^ guarding an orb. Kill them and click ^Font of Power^."] = "击败 ^Radiance of Azshara^ 后，按来时的路离开房间，发现另外 2 个 ^Azsh'ari Channelers^ 守卫着一个球体。杀死他们并点击 ^Font of Power^。",
    ["After defeating ^Rashok^, make your way up the chain behind him, and follow the path around to ^The Vigilant Steward, Zskarn^."] = "击败 ^Rashok^ 后，沿着他身后的链条向上走，然后沿着周围的路径到达 ^The Vigilant Steward, Zskarn^。",
    ["After defeating ^Razuvious^, take the south exit and follow the path around to reach ^Gothik the Harvester^. Tag him to start the encounter."] = "击败 ^Razuvious^ 后，从南出口离开并沿路前往 ^Gothik the Harvester^。攻击他以开始战斗。",
    ["After defeating ^Sha of Pride^, watch some dialog then click the portal in the southwest corner of the room."] = "击败^Sha of Pride^后，观看一些对话，然后点击房间西南角的传送门。",
    ["After defeating ^Shad'har^, leave his room and continue down the spiral."] = "击败^Shad'har^后，离开他的房间并继续沿着螺旋向下走。",
    ["After defeating ^Shannox^, head north to reach ^Baleroc^."] = "击败^Shannox^后，向北前往^Baleroc^。",
    ["After defeating ^Siegecrafter Blackfuse^, jump back in the pipe towards the room entrance. Continue southwest back the way you came."] = "击败 ^Siegecrafter Blackfuse^ 后，跳回管道中进入房间入口。继续向西南方向返回。",
    ["After defeating ^Sisters of the Moon^, leave the boss room and take a left. Follow the winding path back to ^The Desolate Host^."] = "击败^Sisters of the Moon^后，离开首领房间并向左走。沿着蜿蜒的小路回到^The Desolate Host^。",
    ["After defeating ^Sivara^, continue past her towards the map exit labeled ^Halls of the Chosen^. Take the underwater tunnel to reach the next area."] = "击败 ^Sivara^ 后，继续经过她，前往标记为 ^Halls of the Chosen^ 的地图出口。沿着水下隧道到达下一个区域。",
    ["After defeating ^Skolex^, follow the ring path up and around to ^Artificer Xy'mox^."] = "击败 ^Skolex^ 后，沿着环形路径向上绕行至 ^Artificer Xy'mox^。",
    ["After defeating ^Skorpyron^, take the new southeast exit up the ramp and make your way towards ^Chronomatic Anomaly^. Kill trash on the way to open the door."] = "击败 ^Skorpyron^ 后，从新的东南出口走上坡道，前往 ^Chronomatic Anomaly^。在开门的路上杀掉小怪。",
    ["After defeating ^Socrethar the Eternal^, leave the room to the south. In the next room, click 4x ^Demon Portals^ then kill ^Lord Aram'el^ to open the door. Proceed along the path to ^Tyrant Velhari^."] = "击败^Socrethar the Eternal^后，离开南边的房间。在下一个房间，点击 4x ^Demon Portals^ 然后杀 ^Lord Aram'el^ 打开门。沿着路径前往 ^Tyrant Velhari^。",
    ["After defeating ^Star Augur Etraeus^, backtrack down the stairs to return to ^Astromancer's Rise^."] = "击败^Star Augur Etraeus^后，原路下楼梯返回^Astromancer's Rise^。",
    ["After defeating ^Stormwall Blockade^, walk onto the newly-arrived ship and speak with ^Captain Zadari^ to begin the ^Lady Jaina Proudmoore^ encounter."] = "击败^Stormwall Blockade^后，走上新抵达的船只并与^Captain Zadari^交谈以开始^Lady Jaina Proudmoore^战斗。",
    ["After defeating ^Sun King's Salvation^, go back the way you came and return down the stairs to ^Halls of the Faithful^."] = "击败^Sun King's Salvation^后，原路返回，下楼梯回到^Halls of the Faithful^。",
    ["After defeating ^Tectus^, follow the path northeast to reach ^Brackenspore^."] = "击败^Tectus^后，沿着东北方向到达^Brackenspore^。",
    ["After defeating ^Tectus^, leave his area and take a left to reach a portal."] = "击败 ^Tectus^ 后，离开他的区域并向左转到达传送门。",
    ["After defeating ^Thaddius^, click the ^Naxxramas Portal^."] = "击败 ^Thaddius^ 后，点击 ^Naxxramas Portal^。",
    ["After defeating ^The Blast Furnace^, go straight ahead back up the spiral ramp. When you reach the bridge area, take a right and go up another ramp towards the main lobby."] = "击败 ^The Blast Furnace^ 后，径直返回螺旋坡道。当您到达桥区时，右转并沿另一个坡道前往主大厅。",
    ["After defeating ^The Butcher^, take the western exit out of his area and follow the path north to ^Brackenspore^."] = "击败 ^The Butcher^ 后，从西边出口离开他的区域，然后沿着路向北到达 ^Brackenspore^。",
    ["After defeating ^The Coven of Shivarra^, take some stairs out of the area and make your way west towards the map exit labeled ^The World Soul^."] = "击败 ^The Coven of Shivarra^ 后，走一些楼梯离开该区域，并向西朝标记为 ^The World Soul^ 的地图出口走。",
    ["After defeating ^The Demonic Inquisition^, follow the path to ^Terrace of the Moon^."] = "击败^The Demonic Inquisition^后，沿着路径前往^Terrace of the Moon^。",
    ["After defeating ^The Fallen Protectors^, follow the path to the mineshaft. Kill ^Zeal^ to unlock the way."] = "击败^The Fallen Protectors^后，沿着路径前往矿井。杀死^Zeal^即可解锁道路。",
    ["After defeating ^The Forgotten Experiments^, jump down behind them (under a chain) and take the path across the room to the exit labeled ^Defiant Ramparts^."] = "击败 ^The Forgotten Experiments^ 后，跳到他们后面（在链条下），沿着路径穿过房间到达标有 ^Defiant Ramparts^ 的出口。",
    ["After defeating ^The Four Horsemen^, click the ^Naxxramas Portal^ to be teleported back to the entrance."] = "击败 ^The Four Horsemen^ 后，点击 ^Naxxramas Portal^ 传送回入口。",
    ["After defeating ^The Queen's Court^, head up some stairs towards the map exit labeled ^Precipice of Dreams^."] = "击败 ^The Queen's Court^ 后，上楼梯前往标记为 ^Precipice of Dreams^ 的地图出口。",
    ["After defeating ^The Restless Cabal^, there will be a cutscene where you will fall into a deep hole, landing in ^Tendril of Corruption^. Follow the path all the way back to reach ^Uu'nat^."] = "击败^The Restless Cabal^后，会有一个过场动画，你会掉进一个深洞，降落在^Tendril of Corruption^。沿着小路一路返回即可到达^Uu'nat^。",
    ["After defeating ^The Spirit Kings^, go downstairs to the previous room and take the new path by ^Lorewalker Cho^."] = "击败^The Spirit Kings^后，下楼到之前的房间，走^Lorewalker Cho^的新路径。",
    ["After defeating ^The Stone Guard^, continue ahead to several trash packs with glowing orbs floating near them. Physically walk into the adds to spawn the trash. Once they're down, you can engage ^Feng the Accursed^."] = "击败 ^The Stone Guard^ 后，继续前进，看到几个小怪群，周围漂浮着发光的球体。物理上走进小怪以产生小怪。一旦它们宕机，您就可以使用 ^Feng the Accursed^。",
    ["After defeating ^Thok^, backtrack all the way past ^Spoils of Pandaria^ to arrive back in ^Underhold Nexus^."] = "击败^Thok^后，一路原路返回^Spoils of Pandaria^，回到^Underhold Nexus^。",
    ["After defeating ^Tortos^, walk through him to reach the next area. To spawn ^Megaera^, you must destroy the (3) bells marked on the map, which are protected by ^Eternal Guardians^."] = "击败^Tortos^后，穿过他到达下一个区域。要出现 ^Megaera^，您必须摧毁地图上标记的 (3) 个钟，这些钟受到 ^Eternal Guardians^ 的保护。",
    ["After defeating ^Trilliax^, take the northwest exit out of the room and make your way up the spiral staircase."] = "击败^Trilliax^后，从西北出口离开房间，然后沿着螺旋楼梯向上走。",
    ["After defeating ^Tsulong^, keep moving straight ahead and kill the trash to spawn ^Lei Shi^."] = "击败^Tsulong^后，继续向前移动并杀死小怪以出现^Lei Shi^。",
    ["After defeating ^Twin Ogron^, proceed up the stairwell behind them to reach ^Ko'ragh^. Clear trash to start the encounter."] = "击败 ^Twin Ogron^ 后，沿着他们身后的楼梯井到达 ^Ko'ragh^。清除小怪以开始战斗。",
    ["After defeating ^Ultraxion^, wait for the cutscene, then board the ship and talk to ^Sky Captain Swayze^ to advance."] = "击败^Ultraxion^后，等待过场动画，然后登船并与^Sky Captain Swayze^对话即可前进。",
    ["After defeating ^Varimathras^, take the ascending stairwell out of the room towards ^Temple of Anguish^."] = "击败^Varimathras^后，从房间的上升楼梯井前往^Temple of Anguish^。",
    ["After defeating ^Warlord Zon'ozz^, return to ^Wyrmrest Temple^ by clicking the ^Portal^."] = "击败^Warlord Zon'ozz^后，点击^Portal^返回^Wyrmrest Temple^。",
    ["After defeating ^Wind Lord Mel'jarak^, take the southern stairwell and follow the linear path all the way to ^Amber-Shaper Un'sok^."] = "击败^Wind Lord Mel'jarak^后，走南边的楼梯井，沿着直线路径一直到达^Amber-Shaper Un'sok^。",
    ["After defeating ^Wrathion^, proceed through the long northern path to the map exit labeled ^Ny'alotha^. Take the elevator up, and continue through the door ahead."] = "击败 ^Wrathion^ 后，穿过漫长的北方道路到达标记为 ^Ny'alotha^ 的地图出口。乘电梯上去，从前面的门继续走。",
    ["After defeating ^Wrathion^, you can proceed up the long bridge straight to ^Carapace of N'Zoth^."] = "击败^Wrathion^后，您可以沿着长桥直行至^Carapace of N'Zoth^。",
    ["After defeating ^Yor'sahj^, return to ^Wyrmrest Temple^ by clicking the ^Portal^."] = "击败^Yor'sahj^后，点击^Portal^返回^Wyrmrest Temple^。",
    ["After defeating ^Zskarn^, drop down into the hole behind ^Neltharion^. Leap down again (across some lava), and make your way to the boss platform. Clear the trash to spawn ^Magmorax^."] = "击败^Zskarn^后，掉入^Neltharion^后面的洞里。再次跳下（穿过一些熔岩），并前往首领平台。清除小怪以出现 ^Magmorax^。",
    ["After defeating the ^Ascendant Council^, continue down the southern path until you reach ^Cho'gall^."] = "击败 ^Ascendant Council^ 后，继续沿着南边的道路前进，直到到达 ^Cho'gall^。",
    ["After defeating the ^Assault of the Zaqali^, enter the nearby room labeled ^Molten Crucible^."] = "击败^Assault of the Zaqali^后，进入附近标有^Molten Crucible^的房间。",
    ["After defeating the ^Champion of the Light^, follow the linear path to the right and work your way towards the next boss, ^Jadefire Masters^. Kill the final trash pack before running up the stairs."] = "击败 ^Champion of the Light^ 后，沿着右侧的线性路径朝下一个 首领 ^Jadefire Masters^ 前进。在跑上楼梯之前杀死最后一个小怪群。",
    ["After defeating the ^Dragons of Nightmare^, go back the way you came and return to ^Core of the Nightmare^."] = "击败^Dragons of Nightmare^后，原路返回^Core of the Nightmare^。",
    ["After defeating the ^Felhounds of Sargeras^, click the ^Lightforged Teleportation Pad^ in their boss room to be teleported further up the path. After landing, proceed ahead to ride the elevator up."] = "击败 ^Felhounds of Sargeras^ 后，点击其 首领 房间中的 ^Lightforged Teleportation Pad^ 即可传送到更远的路径。落地后，继续乘坐电梯上行。",
    ["After defeating the ^Hellfire High Council^, take the southwestern exit out of the room and follow the long linear path to ^Kilrogg Deadeye^."] = "击败^Hellfire High Council^后，从西南出口离开房间，沿着长长的线性路径到达^Kilrogg Deadeye^。",
    ["After defeating the ^Omnotron Defense System^, go back downstairs and proceed straight ahead to reach ^Magmaw^."] = "击败^Omnotron Defense System^后，回到楼下，继续向前到达^Magmaw^。",
    ["After defeating the ^Paragons of the Klaxxi^, take the new exit on the south side of the room. As you approach ^Garrosh^, pull the hallway trash with you and most of the dialog will be skipped!"] = "击败^Paragons of the Klaxxi^后，从房间南侧的新出口走。当您接近 ^Garrosh^ 时，随身携带走廊小怪，大部分对话将被跳过！",
    ["After defeating the ^Spine of Deathwing^, talk to ^Thrall^ (twice) to begin the final battle with ^Madness of Deathwing^."] = "击败 ^Spine of Deathwing^ 后，与 ^Thrall^ 交谈（两次），开始与 ^Madness of Deathwing^ 的最终战斗。",
    ["After finishing the adds, proceed forward and defeat ^MOTHER^."] = "完成添加后，继续前进并击败^MOTHER^。",
    ["After getting off the elevator in ^Walk of Kings^, follow the linear path around to ^The Heart of the Empire^."] = "在^Walk of Kings^下电梯后，沿着直线路径前往^The Heart of the Empire^。",
    ["After getting off the elevator, follow the path around to the map exit labeled ^The Heart of the Empire^."] = "下了电梯后，沿着周围的路径前往标有^The Heart of the Empire^的地图出口。",
    ["After jumping in the hole, engage ^The Fallen Protectors^."] = "跳入洞中后，接合^The Fallen Protectors^。",
    ["After jumping in the hole, follow the path straight ahead to find ^Harjatan^."] = "跳进洞里后，沿着小路一直向前就能找到^Harjatan^。",
    ["After jumping in the hole, you will be in ^Chamber of Anguish^. Proceed to the next room to find ^Varimathras^."] = "跳入洞后，您将进入^Chamber of Anguish^。前往下一个房间找到 ^Varimathras^。",
    ["After killing ^Alizabal^, visit the final wing on the west to defeat ^Occu'thar^."] = "杀死^Alizabal^后，访问西边的最后一个翼楼以击败^Occu'thar^。",
    ["After killing ^Antoran High Command^, kill yourself by jumping down the elevator hole to save time getting to the next boss."] = "杀死^Antoran High Command^后，跳下电梯洞自杀，以节省到达下一个首领的时间。",
    ["After killing ^Atramedes^, go back out to the main ring and head to the western ring to fight ^Chimaeron^."] = "杀死^Atramedes^后，返回主环并前往西环与^Chimaeron^战斗。",
    ["After killing ^Baleroc^, interact with the ^Magma Orb^ behind him to open the bridge. Cross the bridge and kill the trash to engage ^Majordomo Staghelm^."] = "杀死^Baleroc^后，与他身后的^Magma Orb^互动以打开桥梁。过桥并杀死小怪来与^Majordomo Staghelm^交战。",
    ["After killing ^Beastlord Darmac^, leave the room and take a right. Follow the path north to reach ^Operator Thogar^. To open the gate and start the fight, kill trash on both platforms, then kill the gunners on the train that pulls up."] = "杀死^Beastlord Darmac^后，离开房间并右转。沿着小路向北到达^Operator Thogar^。要打开大门并开始战斗，请杀死两个站台上的小怪，然后杀死停下来的火车上的枪手。",
    ["After killing ^Behemoth^, swim back out the way you came to the map exit labeled ^Halls of the Chosen^."] = "杀死^Behemoth^后，沿着你来到标记为^Halls of the Chosen^的地图出口的路游回去。",
    ["After killing ^Blade Lord Ta'yak^, take the long stairwell exit on the west side of the room."] = "杀死^Blade Lord Ta'yak^后，从房间西侧的长楼梯间出口走。",
    ["After killing ^Broodkeeper Diurna^, click any nearby dragon to fly to the ^Vault of the Incarnates^."] = "杀死^Broodkeeper Diurna^后，点击附近的任何一条龙飞向^Vault of the Incarnates^。",
    ["After killing ^Carapace^, you will find yourself standing in front of ^N'Zoth^. Attack the boss to start the encounter."] = "杀死^Carapace^后，你会发现自己站在^N'Zoth^前面。攻击 首领 以开始战斗。",
    ["After killing ^Cenarius^, jump into the portal behind him to reach the ^Rift of Aln^."] = "杀死^Cenarius^后，跳入他身后的传送门到达^Rift of Aln^。",
    ["After killing ^Chronomatic Anomaly^, proceed up the stairwell at the northwest side of the room, and clear slimes in the boss room to engage ^Trilliax^."] = "杀死 ^Chronomatic Anomaly^ 后，沿着房间西北侧的楼梯井前进，清除 首领 房间中的史莱姆，与 ^Trilliax^ 交战。",
    ["After killing ^Council of Blood^, take the south stairwell out of the room and return to the ^Halls of the Faithful^."] = "杀死^Council of Blood^后，从南楼梯间离开房间并返回^Halls of the Faithful^。",
    ["After killing ^Council of Dreams^, follow the path behind them to reach ^Nymue, Weaver of the Cycle^."] = "杀死^Council of Dreams^后，沿着他们身后的路径到达^Nymue, Weaver of the Cycle^。",
    ["After killing ^Dathea, Ascended^, take one of the nearby ^Downward Draft^ to return below to ^The Primal Bulwark^."] = "杀死^Dathea, Ascended^后，拿附近的^Downward Draft^之一返回下面的^The Primal Bulwark^。",
    ["After killing ^Dausegne^, continue up the path toward ^The Endless Foundry^."] = "杀死 ^Dausegne^ 后，继续沿着通往 ^The Endless Foundry^ 的路径前进。",
    ["After killing ^Drest'agath^, leave the room and continue down the spiral toward the map exit ^Chamber of Rebirth^."] = "杀死^Drest'agath^后，离开房间并继续沿着螺旋走向地图出口^Chamber of Rebirth^。",
    ["After killing ^Elegon^, follow the path out of the room and head south to arrive at the next boss room. To start the fight with ^Will of the Emperor^, click the pipes below (^Heroic^) or click the console (^Normal/LFR^)."] = "杀死^Elegon^后，沿着房间外的小路向南走，到达下一个首领房间。要与 ^Will of the Emperor^ 开始战斗，请点击下面的管道 (^Heroic^) 或点击控制台 (^Normal/LFR^)。",
    ["After killing ^Eranog^, click the ^Clutchwarren Runestone^ next to each staircase. After that, take the staircase towards ^The Clutchwarren^."] = "杀死^Eranog^后，点击每个楼梯旁边的^Clutchwarren Runestone^。之后，走楼梯前往 ^The Clutchwarren^。",
    ["After killing ^Eranog^, take the left map exit labeled ^The Elemental Conclave^."] = "杀死^Eranog^后，从左侧地图出口标记为^The Elemental Conclave^。",
    ["After killing ^Eranog^, there are 3 paths available. Take the path on the right labeled ^The Vault Approach^."] = "杀死^Eranog^后，有3条路径可用。走右侧标记为 ^The Vault Approach^ 的路径。",
    ["After killing ^Eranog^, you will find two clickable runes beside the stairs leading to ^Broodkeeper Diurna^. Click the runes to open the access."] = "杀死^Eranog^后，你会在通往^Broodkeeper Diurna^的楼梯旁边发现两个可点击的符文。点击符文以打开访问权限。",
    ["After killing ^Fallen Avatar^, continue straight ahead across the slime to the map exit labeled ^The Twisting Nether^. Walk into the green swirly portal."] = "杀死 ^Fallen Avatar^ 后，继续向前穿过史莱姆到达标记为 ^The Twisting Nether^ 的地图出口。走进绿色的漩涡传送门。",
    ["After killing ^Fatescribe Roh-Kalo^, go back out the way you came and follow the path to ^Kel'Thuzad^."] = "杀死 ^Fatescribe Roh-Kalo^ 后，按原路返回，沿着路径前往 ^Kel'Thuzad^。",
    ["After killing ^Feng^, continue on to the next area."] = "杀死^Feng^后，继续前往下一个区域。",
    ["After killing ^Fetid Devourer^, go back the way you came to arrive back in the ^Ring of Containment^."] = "杀死^Fetid Devourer^后，按原路返回^Ring of Containment^。",
    ["After killing ^Galakras^, follow the long path to the west until you arrive at ^Iron Juggernaut^."] = "杀死^Galakras^后，沿着漫长的道路向西行进，直到到达^Iron Juggernaut^。",
    ["After killing ^Gara'jal^, follow the linear path to ^Lorewalker Cho^. Speak to him to trigger a series of trash encounters."] = "杀死 ^Gara'jal^ 后，沿着线性路径到达 ^Lorewalker Cho^。与他交谈会引发一系列小怪战斗。",
    ["After killing ^Garalon^, walk up the stairs behind you to find ^Wind Lord Mel'jarak^."] = "杀死^Garalon^后，走上你身后的楼梯找到^Wind Lord Mel'jarak^。",
    ["After killing ^Garothi Worldbreaker^, you can take the teleporter to whichever skip you have unlocked:\n  - The Exhaust: ^Imonar the Soulhunter^\n  - The Burning Throne: ^Aggramar^\n\nNote: RetroRuns only has the route built for Aggramar at this time."] = "击杀 ^Garothi Worldbreaker^ 后，你可以通过传送器前往已解锁的任一捷径：\n  - 排气口：^Imonar the Soulhunter^\n  - 燃烧王座：^Aggramar^\n\n注意：RetroRuns 目前只提供通往阿格拉玛的路线。",
    ["After killing ^Gluth^, follow the path straight ahead to reach ^Thaddius^."] = "击杀 ^Gluth^ 后，沿路直行前往 ^Thaddius^。",
    ["After killing ^Gnarlroot^ and ^Igira^, you can channel the seed to open the bridge to ^Smolderon^."] = "杀死 ^Gnarlroot^ 和 ^Igira^ 后，您可以引导种子以打开通往 ^Smolderon^ 的桥。",
    ["After killing ^Gnarlroot^, continue forward and clear the trash pack to start the encounter with ^Igira the Cruel^."] = "杀死^Gnarlroot^后，继续前进并清除小怪群，开始与^Igira the Cruel^的战斗。",
    ["After killing ^Gorefiend^, click the nearby portal."] = "杀死^Gorefiend^后，点击附近的传送门。",
    ["After killing ^Goroth^, go down the staircase behind ^Image of Aegwynn^."] = "杀死^Goroth^后，从^Image of Aegwynn^后面的楼梯下去。",
    ["After killing ^Goroth^, take the western exit labeled ^The Abyssal Throne^."] = "杀死^Goroth^后，从标有^The Abyssal Throne^的西出口走。",
    ["After killing ^Goroth^, the door behind ^Image of Aegwynn^ opens, allowing you to skip to ^Maiden of Vigilance^."] = "杀死^Goroth^后，^Image of Aegwynn^后面的门打开，让你跳到^Maiden of Vigilance^。",
    ["After killing ^Grong^, continue up the stairwell behind him towards the map exit labeled ^Halls of Opulence^. Jump in the hole when you reach the end of the path."] = "杀死 ^Grong^ 后，继续沿着他身后的楼梯井朝标记为 ^Halls of Opulence^ 的地图出口走去。当你到达路径的尽头时，跳进洞里。",
    ["After killing ^Gruul^, backtrack to the bridge and go east. Follow the spiral down, then at the bottom go straight ahead to locate ^The Blast Furnace^."] = "杀死^Gruul^后，原路返回桥并向东走。沿着螺旋向下，然后在底部直行找到^The Blast Furnace^。",
    ["After killing ^Guardian of the First Ones^, go back the way you came and follow the path to ^Fatescribe Roh-Kalo^. For a shortcut, you can jump off the ledge to respawn halfway there."] = "杀死^Guardian of the First Ones^后，按原路返回，沿着路径前往^Fatescribe Roh-Kalo^。为了走捷径，你可以跳下壁架，在半路重生。",
    ["After killing ^Guarm^, continue down the path to meet ^Helya^. Kill the trash to start the encounter."] = "杀死^Guarm^后，继续沿着路径遇见^Helya^。杀死小怪来开始战斗。",
    ["After killing ^Halondrus^, continue down the path behind him to reach his loot chest. Activate the nearby teleporter and select ^Genesis Cradle Alpha^."] = "杀死^Halondrus^后，继续沿着他身后的路径到达他的战利品箱。激活附近的传送器并选择 ^Genesis Cradle Alpha^。",
    ["After killing ^Hans'gar and Franzok^, take the southern exit out of the room. Follow the path across the next room to reach ^Flamebender Ka'graz^."] = "杀死^Hans'gar and Franzok^后，从南出口离开房间。沿着路径穿过下一个房间到达^Flamebender Ka'graz^。",
    ["After killing ^Harjatan^, jump over the ledge to his left and land in the water. Follow the path through the tunnel and continue straight ahead to find ^Mistress Sassz'ine^."] = "杀死^Harjatan^后，跳过他左边的壁架并落入水中。沿着隧道的小路继续直行即可找到^Mistress Sassz'ine^。",
    ["After killing ^Horridon^, go through the north exit and follow the path all the way to ^Council of Elders^. Kill trash to unlock doors along the way."] = "杀掉^Horridon^后，从北口出来，沿着小路一直走到^Council of Elders^。消灭小怪以打开沿途的门。",
    ["After killing ^Hungering Destroyer^, take the stairs going up to ^The Purloined Stores^."] = "杀死^Hungering Destroyer^后，走楼梯前往^The Purloined Stores^。",
    ["After killing ^Huntsman Altimor^, follow the path to a small room at the back, and jump into the sewer that the NPCs are standing next to. Make your way down the path to find ^Hungering Destroyer^."] = "击杀 ^Huntsman Altimor^ 后，沿路前往后方的小房间，跳进 NPC 旁边的下水道。沿路向下前往 ^Hungering Destroyer^。",
    ["After killing ^Igira the Cruel^, go up the stairs behind him and channel the ^Formation Seed^ to form the bridge."] = "杀死 ^Igira the Cruel^ 后，上他身后的楼梯并引导 ^Formation Seed^ 形成桥梁。",
    ["After killing ^Igira^, take the left exit to ^The Scorched Hall^."] = "杀死^Igira^后，从左侧出口前往^The Scorched Hall^。",
    ["After killing ^Il'gynoth^, return back the way you came, through the portal to ^Core of the Nightmare^."] = "杀死 ^Il'gynoth^ 后，按原路返回，通过传送门到达 ^Core of the Nightmare^。",
    ["After killing ^Imonar^, make your way down the long path to find the next boss, ^Kin'garoth^."] = "杀死^Imonar^后，沿着漫长的道路寻找下一个首领，^Kin'garoth^。",
    ["After killing ^Iron Juggernaut^, head into the ^Gates of Orgrimmar^."] = "杀死^Iron Juggernaut^后，进入^Gates of Orgrimmar^。",
    ["After killing ^Iron Reaver^, continue up the stairs behind him to the next area."] = "杀死^Iron Reaver^后，继续上他身后的楼梯到下一个区域。",
    ["After killing ^Ji-Kun^, click a feather followed by your Extra Action Button to fly to the southwest exit of the room."] = "杀死^Ji-Kun^后，点击一根羽毛，然后点击你的额外操作按钮，飞到房间的西南出口。",
    ["After killing ^Jin'rokh^, take the long path south and cross two bridges before arriving in the next area. Avoid blue circles; they will throw you off the edge."] = "杀死^Jin'rokh^后，沿着长路向南走，穿过两座桥，然后到达下一个区域。避免蓝色圆圈；他们会把你扔到悬崖边。",
    ["After killing ^Kargath^, exit the room to the northwest and follow the path around to ^The Butcher^."] = "杀死^Kargath^后，从西北方向退出房间，沿着周围的路径到达^The Butcher^。",
    ["After killing ^Kazzara^, take the left path towards the exit labeled ^Onyx Laboratory^."] = "杀死 ^Kazzara^ 后，沿左侧路径前往标记为 ^Onyx Laboratory^ 的出口。",
    ["After killing ^Kel'Thuzad^, take the purple portal that appeared right behind him."] = "杀死^Kel'Thuzad^后，采取出现在他身后的紫色传送门。",
    ["After killing ^Kilrogg Deadeye^, exit behind him to the east and follow the path out of this area."] = "杀死^Kilrogg Deadeye^后，从他身后向东退出并沿着路径离开该区域。",
    ["After killing ^Kin'garoth^, click the ^Lightforged Beacon^ behind you to be teleported to the next area. Select ^The Burning Throne^ from the dialog options."] = "击杀^Kin'garoth^后，点击身后的^Lightforged Beacon^即可传送到下一个区域。从对话框选项中选择 ^The Burning Throne^。",
    ["After killing ^Ko'ragh^, take the northwest stairwell out of the room."] = "杀死^Ko'ragh^后，从西北楼梯间走出房间。",
    ["After killing ^Kor'kron Dark Shaman^, follow the northeastern path towards ^The Drag^. Clear trash and enter the ^Cleft of Shadows^."] = "杀死^Kor'kron Dark Shaman^后，沿着东北方向前往^The Drag^。清除小怪并输入 ^Cleft of Shadows^。",
    ["After killing ^Kormrok^, exit the room the way you entered."] = "杀死^Kormrok^后，按照你进入的方式退出房间。",
    ["After killing ^Kromog^, exit the room to the east and follow the path to the elevator."] = "杀死^Kromog^后，从东边退出房间，沿着路径前往电梯。",
    ["After killing ^Kurog Grimtotem^, follow the path back to ^The Vault Approach^."] = "杀死 ^Kurog Grimtotem^ 后，按照路径返回 ^The Vault Approach^。",
    ["After killing ^Lady Ashvane^, jump through the hole in the middle of her boss room to land in ^The Traverse^."] = "杀死^Lady Ashvane^后，从她的首领房间中间的洞跳到降落在^The Traverse^。",
    ["After killing ^Lady Inerva Darkvein^, follow the path to take the exit ^General Draven^ is standing in. He will lead you back to the main entrance of the raid in ^The Grand Walk^."] = "杀死^Lady Inerva Darkvein^后，沿着路径走到^General Draven^所在的出口。他会带你回到^The Grand Walk^的副本正门。",
    ["After killing ^Larodar^, interact with the ^Seed of Life^ to unlock a portal at the back of the room. Walk through the portal to arrive back at the ^Wellspring Atrium^."] = "杀死 ^Larodar^ 后，与 ^Seed of Life^ 交互以解锁房间后面的传送门。穿过传送门回到^Wellspring Atrium^。",
    ["After killing ^Lei Shen^, click the ^Displacement Pad^ in the middle of the room to be teleported back to ^Primordius^' room."] = "杀死^Lei Shen^后，点击房间中间的^Displacement Pad^即可传送回^Primordius^'房间。",
    ["After killing ^Loatheb^, click on the ^Naxxramas Portal^ to be teleported back to the entrance."] = "击杀 ^Loatheb^ 后，点击 ^Naxxramas Portal^ 传送回入口。",
    ["After killing ^Lord Rhyolith^, make your way north to reach ^Alysrazor^. Tag ^Majordomo^ to start the encounter."] = "杀死^Lord Rhyolith^后，向北到达^Alysrazor^。标记 ^Majordomo^ 以开始战斗。",
    ["After killing ^Lords of Dread^, you will find a teleporter behind them. Use it to take a shortcut back to the beginning of the room, and follow the path to ^Rygelon^."] = "杀死^Lords of Dread^后，你会发现他们身后有一个传送器。使用它可以走捷径回到房间的开头，然后沿着路径前往^Rygelon^。",
    ["After killing ^Maexxna^, click the ^Naxxramas Portal^ to return to the entrance."] = "击杀 ^Maexxna^ 后，点击 ^Naxxramas Portal^ 返回入口。",
    ["After killing ^Magmaw^, go back down the stairs to the main lobby. Take a left and ride the elevator down."] = "杀死^Magmaw^后，下楼梯回到主大厅。向左转，乘电梯下去。",
    ["After killing ^Maiden of Vigilance^, click the nearby ^Teleportation Pad^ to be taken to ^Chamber of the Avatar^. Note: the pad will likely be under the boss corpse until she despawns, but you can still click it."] = "杀死^Maiden of Vigilance^后，点击附近的^Teleportation Pad^即可前往^Chamber of the Avatar^。注意：垫子可能会位于 首领 尸体下方，直到她消失，但您仍然可以点击它。",
    ["After killing ^Majordomo Staghelm^, proceed straight ahead all the way to ^Ragnaros^."] = "杀掉^Majordomo Staghelm^后，一直往前走到^Ragnaros^。",
    ["After killing ^Malkorok^, take the northwestern exit from the platform and follow it around to kill the scorpion and click ^Release Lever^."] = "杀死^Malkorok^后，从平台的西北出口走，沿着它绕过去杀死蝎子，然后点击^Release Lever^。",
    ["After killing ^Mannoroth^, click the nearby portal."] = "杀死^Mannoroth^后，点击附近的传送门。",
    ["After killing ^Maut^, take the long path all the way to the right to reach ^The Prophet Skitra^. Jump off the ledge and die for a shortcut."] = "杀死^Maut^后，沿着长路一直向右到达^The Prophet Skitra^。从壁架上跳下来，为捷径而死。",
    ["After killing ^Nymue^, walk up the stairs behind her to interact with the ^Seed of Life^. This opens a portal at the back of the room. Walk through the portal to return back to ^Wellspring Atrium^."] = "杀死^Nymue^后，走上她身后的楼梯与^Seed of Life^互动。这会在房间后面打开一个传送门。穿过传送门返回^Wellspring Atrium^。",
    ["After killing ^Opulence^, exit the room to the north, up some stairs to the map exit labeled ^Loa's Sanctum^."] = "杀死 ^Opulence^ 后，从北面退出房间，爬上一些楼梯到达标有 ^Loa's Sanctum^ 的地图出口。",
    ["After killing ^Opulence^, follow the path straight ahead and make your way to the map exit labeled ^Loa's Sanctum^."] = "杀死^Opulence^后，沿着路径一直向前，到达标记为^Loa's Sanctum^的地图出口。",
    ["After killing ^Oregorger^, leave his area the way you came and follow the path all the way north to find ^Gruul^."] = "杀死 ^Oregorger^ 后，按照来时的路线离开他的区域，沿着小路一直向北找到 ^Gruul^。",
    ["After killing ^Orgozoa^, travel to the far west to reach the map exit labeled ^The Queen's Court^. You will be swimming for a good portion of this journey."] = "杀死 ^Orgozoa^ 后，向最西边移动，到达标记为 ^The Queen's Court^ 的地图出口。这段旅程的大部分时间您都将在水中游泳。",
    ["After killing ^Painsmith Raznal^, walk out the new exit to the West and walk through the portal."] = "杀死^Painsmith Raznal^后，走出新的出口向西，穿过传送门。",
    ["After killing ^Patchwerk^, follow the path and take a right to reach ^Grobbulus^."] = "击杀 ^Patchwerk^ 后，沿路前进并右转前往 ^Grobbulus^。",
    ["After killing ^Portal Keeper Hasabel^, return to the portal marked on the map as ^Light's Breach^."] = "杀死^Portal Keeper Hasabel^后，返回地图上标记为^Light's Breach^的传送门。",
    ["After killing ^Primordius^, take the western stairwell out of the room and follow it to ^Dark Animus^. Kill the ritualists to start the fight."] = "杀死^Primordius^后，将西边的楼梯井带出房间，然后沿着它到达^Dark Animus^。杀死仪式者开始战斗。",
    ["After killing ^Remnant of Ner'zhul^, follow the path to loop back around to ^Painsmith Raznal^."] = "杀死 ^Remnant of Ner'zhul^ 后，按照路径循环回到 ^Painsmith Raznal^。",
    ["After killing ^Rygelon^, follow the path straight behind him all the way to ^The Jailer^."] = "杀死^Rygelon^后，沿着他身后的路一直走到^The Jailer^。",
    ["After killing ^Sapphiron^, take the west exit and follow the path around to ^Kel'Thuzad^. Walk into the middle circle to begin the encounter."] = "击杀 ^Sapphiron^ 后，从西侧出口离开并沿路前往 ^Kel'Thuzad^。走入中央圆环以开始战斗。",
    ["After killing ^Sennarth^, click the ^Gust of Wind^ behind him to return to the bottom of the room. If you killed him on the ground floor, proceed up the ramp to find his corpse and collect his loot!"] = "杀死^Sennarth^后，点击他身后的^Gust of Wind^返回房间底部。如果您在一楼杀死了他，请爬上坡道找到他的尸体并收集他的战利品！",
    ["After killing ^Shadow-Lord Iskar^, exit the room to the east. At the first intersection, go south to the next area."] = "杀死^Shadow-Lord Iskar^后，从东边退出房间。在第一个路口，向南前往下一个区域。",
    ["After killing ^Shriekwing^, follow the north path out of the room and go down the stairs. Kill the trash, and ^General Draven^ will come open the gate. Kill a few trash mobs then engage ^Huntsman Altimor^."] = "杀死^Shriekwing^后，沿着北边的小路走出房间，下楼梯。杀死小怪，^General Draven^ 就会打开大门。杀死一些小怪小怪，然后与 ^Huntsman Altimor^ 交战。",
    ["After killing ^Shriekwing^, speak to ^General Draven^ near the north exit to skip to ^Sludgefist^. He will spawn behind you in the normal location."] = "杀死^Shriekwing^后，与北出口附近的^General Draven^交谈以跳至^Sludgefist^。他会在你身后的正常位置重生。",
    ["After killing ^Shriekwing^, there will be a lengthy dialog. After that, you can fight ^Sludgefist^ in the same room."] = "杀死^Shriekwing^后，会出现一个冗长的对话框。之后，你可以在同一个房间里与^Sludgefist^战斗。",
    ["After killing ^Skitra^, backtrack a bit and go north to the map exit labeled ^Ny'alotha^. Ride an elevator up, and kill the trash to open the path to the next area."] = "杀死^Skitra^后，原路返回，向北前往标记为^Ny'alotha^的地图出口。乘坐电梯上去，杀死小怪以打开通往下一个区域的道路。",
    ["After killing ^Sludgefist^, travel up the stairs behind him and walk through the mirror teleporter to land in ^Nightcloak Sanctum^."] = "杀死^Sludgefist^后，爬上他身后的楼梯，穿过镜子传送器降落在^Nightcloak Sanctum^。",
    ["After killing ^Smolderon^, talk to the dragon to be flown to ^Tindral Sageswift, Seer of the Flame^."] = "杀死 ^Smolderon^ 后，与龙交谈即可飞向 ^Tindral Sageswift, Seer of the Flame^。",
    ["After killing ^Soulrender Dormazain^, follow the path to ^Remnant of Ner'zhul^. Kill the trash to engage the boss."] = "杀死^Soulrender Dormazain^后，按照路径到达^Remnant of Ner'zhul^。杀死小怪来对付首领。",
    ["After killing ^Stone Legion Generals^, simply walk into the room where ^Sire Denathrius^ is waiting for you."] = "杀死^Stone Legion Generals^后，只需走进^Sire Denathrius^正在等你的房间。",
    ["After killing ^Taloc^, the floor will start to descend. Once you reach the bottom, go straight ahead and click the ^Titan Console^."] = "杀死^Taloc^后，地板将开始下降。到达底部后，直接向前并点击 ^Titan Console^。",
    ["After killing ^Tarragrue^, wait for dialog to complete, then walk through the portal marked as a map exit ^Shadowsteel Foundry^."] = "杀死 ^Tarragrue^ 后，等待对话框完成，然后穿过标记为地图出口 ^Shadowsteel Foundry^ 的传送门。",
    ["After killing ^The Amalgamation Chamber^, follow the path north to reach some stairs leading to the ^Molten Crucible^."] = "杀死^The Amalgamation Chamber^后，沿着小路向北到达通往^Molten Crucible^的楼梯。",
    ["After killing ^The Butcher^, follow the path to the west to reach ^Tectus^. Kill the (3) rock golems to spawn the boss."] = "杀死^The Butcher^后，沿着小路向西到达^Tectus^。杀死 (3) 个岩石傀儡来出现 首领。",
    ["After killing ^The Eye of the Jailer^, follow the path all the way north to find ^The Nine^."] = "杀死^The Eye of the Jailer^后，沿着小路一路向北找到^The Nine^。",
    ["After killing ^The Hivemind^, continue past them to the next room, and take the elevator up to the ^Terrace of Desolation^."] = "杀死^The Hivemind^后，继续经过他们到下一个房间，然后乘电梯到^Terrace of Desolation^。",
    ["After killing ^The Nine^, take the elevator to the left. You will arrive at ^The Torment Chambers^."] = "杀死^The Nine^后，乘电梯到左边。您将到达^The Torment Chambers^。",
    ["After killing ^The Primal Council^, follow the path towards the exit labeled ^Galewind Crag^. Kill ^Thondrozus^, and click on ^Upward Draft^ to be carried up to ^Galewind Crag^. Approach the Downward Draft."] = "杀死 ^The Primal Council^ 后，沿着标记为 ^Galewind Crag^ 的出口前进。杀掉^Thondrozus^，然后点击^Upward Draft^就会被带到^Galewind Crag^。接近向下吃水。",
    ["After killing ^The Tarragrue^, speak to the ^Ebon Blade Acolyte^ NPC located inside the boss room. He will conjure a portal that will send you straight to ^Kel'Thuzad^."] = "击杀 ^The Tarragrue^ 后，与首领房间内的 ^Ebon Blade Acolyte^ NPC 交谈。他会召唤一个传送门，将你直接送到 ^Kel'Thuzad^。",
    ["After killing ^Theralion and Valiona^, head south and exit this area."] = "杀死^Theralion and Valiona^后，向南走并退出该区域。",
    ["After killing ^Tichondrius^, backtrack the way you came to return to the main courtyard."] = "杀死^Tichondrius^后，原路返回主庭院。",
    ["After killing ^Tindral^, mount up and fly into the fire-colored portal in the sky (marked with a |TInterface\\TargetingFrame\\UI-RaidTargetingIcon_1:0|t). This will teleport you to ^Heart of Amirdrassil^."] = "击杀 ^Tindral^ 后，骑上坐骑并飞入天空中火焰色的传送门（标有 |TInterface\\TargetingFrame\\UI-RaidTargetingIcon_1:0|t）。它会将你传送到 ^Heart of Amirdrassil^。",
    ["After killing ^Tyrant Velhari^, leave the room to the west and proceed up the path to the north."] = "杀死^Tyrant Velhari^后，离开西边的房间，沿着小路向北走。",
    ["After killing ^Ursoc^, go back the way you came and go back through the portal to ^Core of the Nightmare^."] = "杀死^Ursoc^后，按原路返回，通过传送门返回^Core of the Nightmare^。",
    ["After killing ^Vectis^, go back the way you came to arrive back in the ^Ring of Containment^."] = "杀死^Vectis^后，按原路返回^Ring of Containment^。",
    ["After killing ^Vexiona^, interact with the ^Re-origination Anchor^ behind the boss to be teleported. After you land, continue ahead."] = "击杀^Vexiona^后，与首领身后的^Re-origination Anchor^互动即可传送。落地后继续前行。",
    ["After killing ^Vigilant Guardian^, proceed up the bridge and speak to ^Highlord Bolvar Fordragon^ and then take the portal to ^Domination's Grasp^."] = "杀死^Vigilant Guardian^后，继续走上桥并与^Highlord Bolvar Fordragon^交谈，然后通过传送门到达^Domination's Grasp^。",
    ["After killing ^Vigilant Guardian^, proceed up the bridge and speak to ^Highlord Bolvar Fordragon^ near the teleporter to skip ahead to ^Anduin Wrynn^."] = "杀死 ^Vigilant Guardian^ 后，继续上桥并与传送器附近的 ^Highlord Bolvar Fordragon^ 交谈以跳至 ^Anduin Wrynn^。",
    ["After killing ^Volcoross^, continue down the path behind him. Clear trash to start the encounter with ^Larodar, Keeper of the Flame^."] = "杀死^Volcoross^后，继续沿着他身后的路走。清除小怪以开始与 ^Larodar, Keeper of the Flame^ 的战斗。",
    ["After killing ^Warmaster Blackhorn^, talk to ^Sky Captain Swayze^ to begin the encounter with ^Spine of Deathwing^."] = "杀死^Warmaster Blackhorn^后，与^Sky Captain Swayze^交谈以开始与^Spine of Deathwing^的战斗。",
    ["After killing ^Wrathion^, take the path all the way to the left. Clear the room to spawn ^Maut^, and kill him."] = "杀死^Wrathion^后，沿着路径一直向左走。清理房间以出现^Maut^，并杀死他。",
    ["After killing ^Xanesh^, leave the room to the east and towards the map exit for ^Twilight Landing^. Ride the elevator up."] = "杀死^Xanesh^后，离开房间向东，走向^Twilight Landing^的地图出口。乘电梯上去。",
    ["After killing ^Xhul'horac^, head west out of the room the same way you came in."] = "杀死^Xhul'horac^后，按照进来时的路线向西走出房间。",
    ["After killing ^Xhul'horac^, take the portal that appears right next to you."] = "杀死 ^Xhul'horac^ 后，进入出现在你旁边的传送门。",
    ["After killing ^Za'qul^, watch a brief dialog while waiting on a portal to spawn behind the boss. Take the portal, marked on the map as an exit labeled ^The Last Prison^."] = "杀死 ^Za'qul^ 后，在等待 首领 后面出现传送门时观看简短的对话。进入地图上标记为 ^The Last Prison^ 的出口的传送门。",
    ["After killing ^Zek'voz^, go back the way you came to arrive back in the ^Ring of Containment^."] = "杀死^Zek'voz^后，按原路返回^Ring of Containment^。",
    ["After killing ^Zor'lok^, take the northwest stairwell and follow the path into the next room to find ^Blade Lord Ta'yak^. Kill trash in all 4 corners to begin the fight."] = "杀死^Zor'lok^后，走西北楼梯间，沿着小路进入下一个房间找到^Blade Lord Ta'yak^。杀死所有 4 个角落的小怪即可开始战斗。",
    ["After killing ^Zul^, activate the ^Titan Console^ on the south end of the platform. Then jump into ^The Festering Core^ to fight ^Mythrax the Unraveler^."] = "杀死^Zul^后，激活平台南端的^Titan Console^。然后跳入^The Festering Core^与^Mythrax the Unraveler^战斗。",
    ["After killing both ^Skolex^ and ^Artificer Xy'mox^, follow the path south to ^Halondrus^."] = "杀死 ^Skolex^ 和 ^Artificer Xy'mox^ 后，沿着路径向南到达 ^Halondrus^。",
    ["After killing the ^Twin Empyreans^, take the southeastern exit from the room."] = "杀死^Twin Empyreans^后，从房间的东南出口走。",
    ["After landing below, follow the path to reach ^Scalecommander Sarkareth^."] = "在下方着陆后，沿着路径到达^Scalecommander Sarkareth^。",
    ["After landing down below, take the downhill path and kill trash as you walk through the ^Helheim^ portal at the bottom."] = "在下面着陆后，走下坡路并在穿过底部的 ^Helheim^ 传送门时杀死小怪。",
    ["After landing from ^Gust of Wind^, follow the path back out to ^The Primal Convergence^."] = "从 ^Gust of Wind^ 着陆后，沿着路径返回 ^The Primal Convergence^。",
    ["After landing in ^Domination's Grasp^, proceed up the ramp. After some dialog, you can engage ^Anduin Wrynn^."] = "在 ^Domination's Grasp^ 着陆后，继续走上坡道。经过一番对话后，您可以使用 ^Anduin Wrynn^。",
    ["After landing in ^Rift of Aln^, start killing trash. They will continue coming in waves until finally, you will meet ^Xavius^."] = "登陆^Rift of Aln^后，开始清理小怪。他们将继续一波又一波地涌来，直到最后，您会遇到^Xavius^。",
    ["After landing in ^The Exhaust^, move forward to start the encounter with ^Imonar the Soulhunter^."] = "降落在^The Exhaust^后，继续前进，开始与^Imonar the Soulhunter^的战斗。",
    ["After landing in ^The Traverse^, make your way to the bottom of the room by walking over a sequence of teleporting panels on the floor."] = "降落在 ^The Traverse^ 后，走过地板上的一系列传送面板，到达房间底部。",
    ["After landing in the ^Genesis Cradle^, follow the path to ^Dausegne^."] = "登陆 ^Genesis Cradle^ 后，沿着路径前往 ^Dausegne^。",
    ["After landing in the next area, go west to reach ^Shadow-Lord Iskar^."] = "降落在下一个区域后，向西到达^Shadow-Lord Iskar^。",
    ["After landing on the ship, make your way to the top of the ship and talk to ^Tandred Proudmoore^ to proceed."] = "登陆船上后，前往船顶并与 ^Tandred Proudmoore^ 交谈以继续。",
    ["After landing up top, follow the path around to the map exit labeled ^The Hive^."] = "到达顶部后，沿着周围的路径前往标记为 ^The Hive^ 的地图出口。",
    ["After landing, clear trash in the water, then move up the short ramp and clear the remaining trash to engage ^Iron Maidens^."] = "着陆后，清除水中的小怪，然后沿着短坡道移动并清除剩余的小怪以与^Iron Maidens^交战。",
    ["After landing, continue ahead to find ^Durumu the Forgotten^. Clear all trash in the room to spawn the boss."] = "着陆后，继续前进即可找到^Durumu the Forgotten^。清除房间中的所有小怪以出现 首领。",
    ["After landing, follow the path ahead to reach ^Sinestra^."] = "着陆后，沿着前面的路径到达^Sinestra^。",
    ["After landing, follow the path down to the map exit labeled ^Maw of Gor'ma^."] = "着陆后，沿着路径向下到达标记为 ^Maw of Gor'ma^ 的地图出口。",
    ["After landing, follow the path to kill |cffF259C7(1)|r ^Volcanius^, then |cffF259C7(2)|r ^Eranog^."] = "落地后，按照路径杀死|cffF259C7(1)|r ^Volcanius^，然后|cffF259C7(2)|r ^Eranog^。",
    ["After landing, follow the path to the final map exit labeled ^N'Zoth^. Kill adds on the bridge to spawn a portal at the end."] = "落地后，沿路前往标有 ^N'Zoth^ 的最后一个地图出口。清理桥上的小怪，在桥尽头召出传送门。",
    ["After landing, kill ^Warlord Zon'ozz^ right in front of you."] = "着陆后，杀死你面前的^Warlord Zon'ozz^。",
    ["After landing, kill ^Yor'sahj^ in the middle of the room."] = "落地后，在房间中央杀死^Yor'sahj^。",
    ["After landing, move forward and click the ^Lightforged Beacon^ to be teleported to ^The Exhaust^."] = "落地后，向前移动，点击^Lightforged Beacon^即可传送至^The Exhaust^。",
    ["After landing, proceed down the steps to clear trash and begin the fight with ^High Tinker Mekkatorque^."] = "着陆后，继续走下台阶清除小怪，并与^High Tinker Mekkatorque^开始战斗。",
    ["After opening the door, proceed ahead to witness a lengthy dialog before engaging ^Garrosh Hellscream^."] = "打开门后，在与 ^Garrosh Hellscream^ 交战之前，继续见证一段冗长的对话。",
    ["After reaching the bottom of the elevator, take a right and follow the path to reach ^Maloriak^."] = "到达电梯底部后，右转并沿着路径到达^Maloriak^。",
    ["After reaching the bottom of the stairs, proceed forward to trigger a lengthy dialog, then engage ^Ra-den^."] = "到达楼梯底部后，继续前进以触发冗长的对话，然后接合^Ra-den^。",
    ["After reaching the top of the elevator, follow the path back to find ^Ra-den the Despoiled^."] = "到达电梯顶部后，沿着小路返回即可找到^Ra-den the Despoiled^。",
    ["After reaching the top of the elevator, make your way down the path and clear the trash to engage ^Vexiona^."] = "到达电梯顶部后，沿着路径走下去并清除小怪以与 ^Vexiona^ 交战。",
    ["After reaching the top of the stairs and opening a door, you will encounter ^The Coven of Shivarra^."] = "到达楼梯顶部并打开门后，您将遇到^The Coven of Shivarra^。",
    ["After respawning in ^Chamber of the Moon^, proceed towards the group of NPCs and enter the descending stairwell behind them."] = "在 ^Chamber of the Moon^ 重生后，前往那群 NPC，并进入他们身后的下行楼梯间。",
    ["After returning to ^Wyrmrest Temple^, click ^Nethestrasz^, the dragon in front of you. Once you reach the top, click the portal to ^Travel to the Eye of Eternity^."] = "返回^Wyrmrest Temple^后，点击前面的龙^Nethestrasz^。到达顶部后，点击通往 ^Travel to the Eye of Eternity^ 的传送门。",
    ["After returning to ^Wyrmrest Temple^, click ^Nethestrasz^, the dragon in front of you. Once you reach the top, wait on a lengthy dialog and click the portal to ^Travel to the Eye of Eternity^."] = "返回^Wyrmrest Temple^后，点击前面的龙^Nethestrasz^。到达顶部后，等待一个冗长的对话框，然后点击通往 ^Travel to the Eye of Eternity^ 的传送门。",
    ["After returning to ^Wyrmrest Temple^, click on ^Eiendormi^, the dragon on the right."] = "返回^Wyrmrest Temple^后，点击右侧的龙^Eiendormi^。",
    ["After returning to the ^Halls of the Chosen^, follow the path all the way north to kill ^Radiance of Azshara^. Clear all the trash to start the encounter."] = "返回^Halls of the Chosen^后，沿着小路一路向北杀死^Radiance of Azshara^。清除所有小怪以开始战斗。",
    ["After returning to the ^Halls of the Chosen^, walk straight ahead to kill a couple ^Azsh'ari Channelers^ and click the ^Font of Power^."] = "返回^Halls of the Chosen^后，直走杀死一对^Azsh'ari Channelers^，然后点击^Font of Power^。",
    ["After returning to the central hub, approach the middle of the room and interact with the ^Nightmare Iris^ to reach ^Moonglade^."] = "返回中心枢纽后，接近房间中央并与^Nightmare Iris^互动以到达^Moonglade^。",
    ["After returning to the central hub, continue clockwise through the next portal to reach ^Mulgore^."] = "返回中心枢纽后，继续顺时针穿过下一个传送门到达^Mulgore^。",
    ["After returning to the central hub, talk to ^Malfurion^ then interact with the ^Nightmare Iris^ to continue."] = "返回中心枢纽后，与 ^Malfurion^ 交谈，然后与 ^Nightmare Iris^ 交互以继续。",
    ["After returning to the entrance, take the southeast path towards ^The Plague Quarter^."] = "返回入口后，沿东南路径前往 ^The Plague Quarter^。",
    ["After returning to the main courtyard, follow the path all the way to the far southeast of the map to reach ^Krosus^."] = "返回主庭院后，沿着小路一直走到地图最东南方，即可到达^Krosus^。",
    ["After some dialog, kill the trash wave that spawns, and ^Kargath Bladefist^ will enter the ring."] = "经过一番对话后，杀死产生的小怪波，^Kargath Bladefist^ 将进入环。",
    ["After spawning, cross the chasm using the ^Lightforged Teleport Pod^. Stay to the left when you reach the intersection, and follow the path to interact with a ^Portal^."] = "出现后，使用 ^Lightforged Teleport Pod^ 跨越鸿沟。到达十字路口时靠左行驶，然后沿着路径与 ^Portal^ 互动。",
    ["After surfacing from the water, follow the path around to reach ^The Queen's Court^."] = "从水面浮出水面后，沿着周围的小路到达^The Queen's Court^。",
    ["After switching to Alliance, follow the path up the stairs and around to the map exit labeled ^Halls of Opulence^. Jump in the hole at the end of the path."] = "切换到联盟后，沿着楼梯向上并绕过标记为 ^Halls of Opulence^ 的地图出口。跳进路尽头的洞里。",
    ["After taking the portal into ^The Last Prison^, you will watch some lengthy dialog then click the ^Titan Console^ in front of you to engage ^Queen Azshara^."] = "将传送门进入 ^The Last Prison^ 后，您将看到一些冗长的对话框，然后点击您前面的 ^Titan Console^ 以参与 ^Queen Azshara^。",
    ["After taking the portal, follow the long, linear path towards the next map exit labeled ^Elarian Sanctuary^."] = "进入传送门后，沿着长长的线性路径前往下一个标记为 ^Elarian Sanctuary^ 的地图出口。",
    ["After taking the portal, follow the path around to find ^Twin Ogron^. Clear trash to start the encounter."] = "进入传送门后，沿着周围的路径找到^Twin Ogron^。清除小怪以开始战斗。",
    ["After taking the portal, follow the path around to reach ^Kel'Thuzad^."] = "进入传送门后，沿着周围的路径到达^Kel'Thuzad^。",
    ["After taking the portal, move ahead to clear trash to open the door and reach the final boss, ^Imperator Mar'gok^."] = "进入传送门后，继续清理小怪以打开门并到达最终 首领 ^Imperator Mar'gok^。",
    ["After taking the portal, you will arrive in ^Destructor's Rise^. On ^Mythic^, do NOT kill the ^Fel Iron Summoners^. Just tag them, and let ^Mannoroth^ kill them or you could bug the encounter. On other difficulties, kill the ^Fel Iron Summoners^ to begin the fight."] = "进入传送门后，您将到达^Destructor's Rise^。在 ^Mythic^ 上，请勿杀死 ^Fel Iron Summoners^。只需标记它们，然后让 ^Mannoroth^ 杀死它们，否则您可能会在战斗中遇到麻烦。在其他困难上，杀死 ^Fel Iron Summoners^ 即可开始战斗。",
    ["After taking the teleport, follow the path to reach ^Portal Keeper Hasabel^."] = "进行传送后，沿着路径到达^Portal Keeper Hasabel^。",
    ["After taking the teleport, make your way for the right-most exit labeled ^Verdant Terrace^."] = "进行传送后，前往最右侧标有 ^Verdant Terrace^ 的出口。",
    ["After taking the teleport, you will land right in front of ^Archimonde^. Kill him!"] = "进行传送后，您将降落在 ^Archimonde^ 的正前方。杀了他！",
    ["After taking the teleporter to ^Nightcloak Sanctum^, follow the path around to the ^Stone Legion Generals^. Clear trash to start the encounter."] = "乘坐传送器到达 ^Nightcloak Sanctum^ 后，沿着路径前往 ^Stone Legion Generals^。清除小怪以开始战斗。",
    ["After teleporting back to ^The Grand Walk^, follow the path up to where you killed ^Shriekwing^ (again). After some dialog, ^Sludgefist^ will jump down to fight."] = "传送回 ^The Grand Walk^ 后，沿着路径前往你杀死 ^Shriekwing^ 的地方（再次）。一番对话后，^Sludgefist^会跳下来战斗。",
    ["After teleporting to ^Sapphiron's Lair^, proceed ahead to engage ^Sapphiron^."] = "传送到 ^Sapphiron's Lair^ 后，继续直行并与 ^Sapphiron^ 交战。",
    ["After teleporting, click the ^Orb of Naxxramas^ right next to you."] = "传送后，点击身旁的 ^Orb of Naxxramas^。",
    ["After teleporting, follow the path to ^Eye of the Jailer^ and clear all trash on his platform. To reach the far side, walk to the pile of chains and use the extra action button"] = "传送后，沿着路径前往 ^Eye of the Jailer^ 并清除其平台上的所有小怪。要到达远端，请走到链条堆处并使用额外的操作按钮",
    ["After teleporting, proceed ahead to witness a lengthy dialog before engaging ^Garrosh Hellscream^."] = "传送后，在与 ^Garrosh Hellscream^ 交战之前，继续见证一段冗长的对话。",
    ["After teleporting, proceed forward and click on one of the ^Lightforged Warframes^ to be flown to the next area."] = "传送后，继续前进并点击其中一个^Lightforged Warframes^即可飞到下一个区域。",
    ["After teleporting, take the northwest exit toward ^The Construct Quarter^."] = "传送后，从西北出口前往 ^The Construct Quarter^。",
    ["After teleporting, take the southwest path towards ^The Military Quarter^."] = "传送后，沿西南路径前往 ^The Military Quarter^。",
    ["After teleporting, take the spiral stairwell down in the middle of the room."] = "传送后，沿着房间中间的螺旋楼梯走下去。",
    ["After the first trash pack of scorpions, there will be a door opened to the right at the end of the hallway. Inside the room, you will find a teleporter that will allow you to teleport to:\n  - Palace Entrance (^Spellblade Aluriel^)\n  - Palace Courtyard (^Krosus^)\n  - Nightspire (^Elisande^)\n\nNote: RetroRuns only has the route built for Elisande at this time."] = "清理第一组蝎子小怪后，走廊尽头右侧会打开一扇门。房间内有一个传送器，可将你送往：\n  - 宫殿入口（^Spellblade Aluriel^）\n  - 宫殿庭院（^Krosus^）\n  - 暗夜之塔（^Elisande^）\n\n注意：RetroRuns 目前只提供通往艾利桑德的路线。",
    ["After the teleport, you should be standing across from ^Fyrakk^. Approach him to start the encounter."] = "传送后，您应该站在 ^Fyrakk^ 对面。接近他开始战斗。",
    ["After walking through the door, follow the path to ^Paragons of the Klaxxi^. Clear trash and click ^Mantid Amber^ in the middle of the room to start the encounter."] = "穿过门后，沿着路径前往^Paragons of the Klaxxi^。清除小怪并点击房间中间的 ^Mantid Amber^ 开始战斗。",
    ["After walking through the portal into ^Grizzly Hills^, follow the path around to find ^Ursoc^."] = "穿过传送门进入^Grizzly Hills^后，沿着周围的路径找到^Ursoc^。",
    ["After walking through the portal, continue on the path and walk through the second portal to ^The Emerald Nightmare^."] = "穿过传送门后，继续沿着路径走，穿过第二个传送门到达^The Emerald Nightmare^。",
    ["After you land, enter the room and clear the trash to spawn ^Echo of Neltharion^."] = "着陆后，进入房间并清除小怪以出现 ^Echo of Neltharion^。",
    ["After you reach the next area, go downstairs and kill trash to begin the fight against ^High Tinker Mekkatorque^."] = "到达下一个区域后，下楼杀死小怪，开始与^High Tinker Mekkatorque^的战斗。",
    ["After zoning in, click ^Blackrock Artifact^ on either side of the bridge, and it will open the gate leading across the bridge. Go forward and follow the route across the bridge."] = "进入副本后，点击桥两侧的^Blackrock Artifact^，它将打开通往桥的大门。向前走，沿着过桥的路线走。",
    ["After zoning in, click the ^Scroll of Past Deeds^ on the wall to skip ahead to ^Garrosh^. It's on the wall next to ^Lorewalker Cho^."] = "进入副本后，点击墙上的 ^Scroll of Past Deeds^ 以跳至 ^Garrosh^。它位于 ^Lorewalker Cho^ 旁边的墙上。",
    ["After zoning in, click the portal on the right for ^Destructor's Rise^ to be teleported to ^Mannoroth^."] = "进入副本后，点击右侧传送门将^Destructor's Rise^传送至^Mannoroth^。",
    ["After zoning in, click the portal to ^Wyrmrest Summit^ right in front of you."] = "进入副本后，点击您面前的 ^Wyrmrest Summit^ 的传送门。",
    ["After zoning in, continue ahead to find ^Durumu the Forgotten^. Clear all trash in the room to spawn the boss."] = "进入副本后，继续前进找到^Durumu the Forgotten^。清除房间中的所有小怪以出现 首领。",
    ["After zoning in, continue following the linear path to reach the map exit labeled ^The Nighthold^."] = "进入副本后，继续沿着线性路径到达标记为 ^The Nighthold^ 的地图出口。",
    ["After zoning in, continue up the stairwell towards the map exit labeled ^Halls of Opulence^. Jump in the hole when you reach the end of the path."] = "进入副本后，继续沿楼梯间前往标有 ^Halls of Opulence^ 的地图出口。当你到达路径的尽头时，跳进洞里。",
    ["After zoning in, enter the room on the left and enter the portal at the map exit labeled ^Elunaria^."] = "进入副本后，进入左侧的房间，进入标有^Elunaria^的地图出口处的传送门。",
    ["After zoning in, follow the linear path to ^Halfus Wyrmbreaker^."] = "进入副本后，沿着线性路径到达 ^Halfus Wyrmbreaker^。",
    ["After zoning in, follow the linear path to ^Lorewalker Cho^. Speak to him to trigger a series of trash encounters."] = "进入副本后，沿着线性路径到达 ^Lorewalker Cho^。与他交谈会引发一系列小怪战斗。",
    ["After zoning in, follow the linear path to find the first boss, ^Garothi Worldbreaker^."] = "进入副本后，沿着线性路径找到第一个首领，^Garothi Worldbreaker^。",
    ["After zoning in, follow the linear path to reach ^Imperial Vizier Zor'lok^. Clear all trash in his room to start the fight."] = "进入副本后，沿着线性路径到达^Imperial Vizier Zor'lok^。清理他房间里的所有小怪，开始战斗。",
    ["After zoning in, follow the main path to ^Vigilant Guardian^."] = "进入副本后，沿着主路径前往 ^Vigilant Guardian^。",
    ["After zoning in, follow the path ahead to reach ^Za'qul^."] = "进入副本后，沿着前面的路到达^Za'qul^。",
    ["After zoning in, follow the path around a few turns and up some stairs, killing trash on your way to ^Malkorok^."] = "进入副本后，沿着小路转几个弯，爬上一些楼梯，在前往 ^Malkorok^ 的路上消灭小怪。",
    ["After zoning in, follow the path around to ^Hellfire High Council^."] = "进入副本后，沿着路径前往 ^Hellfire High Council^。",
    ["After zoning in, follow the path around to find ^Ursoc^."] = "进入副本后，沿着周围的路径找到^Ursoc^。",
    ["After zoning in, follow the path straight ahead to engage ^Sivara^."] = "进入副本后，沿着路径一直向前行驶以接合^Sivara^。",
    ["After zoning in, follow the path straight ahead to find and kill ^The Restless Cabal^."] = "进入副本后，沿着路径一直向前寻找并杀死^The Restless Cabal^。",
    ["After zoning in, follow the path to ^Gnarlroot^. Clear the trash around him to start the encounter."] = "进入副本后，沿着路径前往 ^Gnarlroot^。清理他周围的小怪以开始战斗。",
    ["After zoning in, follow the path to ^Maw of Gor'ma^."] = "进入副本后，沿着路径前往 ^Maw of Gor'ma^。",
    ["After zoning in, follow the path to the right and make your way down a spiral ramp."] = "进入副本后，沿着右侧的路径走下螺旋坡道。",
    ["After zoning in, follow the path to the right, and make your way towards the map exit labeled ^Defiant Ramparts^."] = "进入副本后，沿着右侧的路径行驶，前往标有 ^Defiant Ramparts^ 的地图出口。",
    ["After zoning in, go downstairs and kill trash to begin the fight against ^High Tinker Mekkatorque^."] = "进入副本后，下楼杀死小怪，开始对抗^High Tinker Mekkatorque^。",
    ["After zoning in, go left to find ^Fel Lord Zakuun^."] = "进入副本后，向左走即可找到^Fel Lord Zakuun^。",
    ["After zoning in, go straight ahead and clear all trash to spawn ^Kazzara^."] = "进入副本后，继续前进并清除所有小怪以出现 ^Kazzara^。",
    ["After zoning in, go straight ahead to engage ^Sire Denathrius^."] = "进入副本后，直接前往^Sire Denathrius^。",
    ["After zoning in, go to the West platform to start the fight with ^Conclave of the Wind^."] = "进入副本后前往西平台与^Conclave of the Wind^开始战斗。",
    ["After zoning in, go up the stairs to the right to reach the ^Omnotron Defense System^."] = "划分区域后，沿右侧楼梯到达^Omnotron Defense System^。",
    ["After zoning in, go west to reach ^Shadow-Lord Iskar^."] = "进入副本后，向西到达^Shadow-Lord Iskar^。",
    ["After zoning in, head down the stairs and move straight ahead to engage ^Immerseus^."] = "划分区域后，下楼并向前直行以与^Immerseus^交战。",
    ["After zoning in, head for the map exit labeled ^The Scorched Hall^."] = "进入副本后，前往标有 ^The Scorched Hall^ 的地图出口。",
    ["After zoning in, head for the map exit labeled ^Verdant Terrace^."] = "进入副本后，前往标有 ^Verdant Terrace^ 的地图出口。",
    ["After zoning in, head straight ahead and follow the route across the bridge."] = "进入副本后，一直向前，沿着路线过桥。",
    ["After zoning in, head through the door and proceed to the exit marked on the map."] = "进入副本后，穿过门，前往地图上标记的出口。",
    ["After zoning in, head to the right wing to engage ^Argaloth^."] = "划分区域后，前往右翼与^Argaloth^交战。",
    ["After zoning in, interact with the dragon to be flown to ^Tindral Sageswift, Seer of the Flame^."] = "进入副本后，与龙互动，飞向^Tindral Sageswift, Seer of the Flame^。",
    ["After zoning in, jump in the purple portal in front of you."] = "进入副本后，跳进你面前的紫色传送门。",
    ["After zoning in, jump into ^The Festering Core^ to fight ^Mythrax the Unraveler^."] = "进入副本后，跳入 ^The Festering Core^ 与 ^Mythrax the Unraveler^ 战斗。",
    ["After zoning in, make your way down the long path to find ^Kin'garoth^."] = "划分区域后，沿着漫长的道路寻找^Kin'garoth^。",
    ["After zoning in, make your way down the path in front of you. When you can, hang a left and work your way around to ^Beth'tilac^."] = "进入副本后，沿着前面的路走。如果可以，请向左转并绕行至 ^Beth'tilac^。",
    ["After zoning in, make your way to the other end of the room. Open the door to find ^Jin'rokh the Breaker^."] = "进入副本后，前往房间的另一端。打开门找到^Jin'rokh the Breaker^。",
    ["After zoning in, make your way up the path and stay to the right and find the map exit labeled ^The Ritual Chamber^."] = "划分区域后，沿着路径向上走，靠右行驶，找到标有 ^The Ritual Chamber^ 的地图出口。",
    ["After zoning in, move ahead and follow the north path out of ^Shriekwing^'s room and go down the stairs. Kill the trash, and ^General Draven^ will come open the gate. Kill a few trash mobs then engage ^Huntsman Altimor^."] = "进入副本后，继续前进，沿着北边的小路走出^Shriekwing^的房间，下楼梯。杀死小怪，^General Draven^ 就会打开大门。杀死一些小怪小怪，然后与^Huntsman Altimor^交战。",
    ["After zoning in, move ahead and kill the trash to begin the encounter with ^Protectors of the Endless^."] = "划分区域后，继续前进并杀死小怪，开始与 ^Protectors of the Endless^ 的战斗。",
    ["After zoning in, move ahead to clear trash to open the door and reach the final boss, ^Imperator Mar'gok^."] = "划分区域后，继续清理小怪以打开门并到达最终 首领 ^Imperator Mar'gok^。",
    ["After zoning in, move ahead to find ^The Stone Guard^."] = "进入副本后，继续寻找 ^The Stone Guard^。",
    ["After zoning in, move forward and take your first left to reach ^Skorpyron^."] = "划分区域后，向前行驶并在第一个路口左转即可到达 ^Skorpyron^。",
    ["After zoning in, move up the stairwell and follow the path to open a masked gate."] = "进入副本后，沿着楼梯井向上移动，沿着小路打开一扇遮蔽的大门。",
    ["After zoning in, proceed across the bridge. On the beach, your goal is to destroy (7) ^Kor'kron Cannons^. Click the ^Spike Mines^ next to each cannon to destroy them."] = "进入副本后，继续过桥。在海滩上，您的目标是摧毁 (7) ^Kor'kron Cannons^。点击每门大炮旁边的 ^Spike Mines^ 来摧毁它们。",
    ["After zoning in, proceed ahead into ^Shriekwing^'s room and take the southern map exit labeled ^Halls of the Faithful^."] = "划分区域后，继续前进进入 ^Shriekwing^ 的房间，并从标记为 ^Halls of the Faithful^ 的南面出口离开。",
    ["After zoning in, proceed ahead to ^Maiden of Vigilance^."] = "进入副本后，继续前往 ^Maiden of Vigilance^。",
    ["After zoning in, proceed ahead to engage ^Aggramar^."] = "进入副本后，继续参与 ^Aggramar^。",
    ["After zoning in, proceed ahead to the ^Captain's Quarters^ entrance on the map. Inside the ^Captain's Quarters^, take your first right to go up a short stairwell."] = "进入副本后，继续前往地图上的 ^Captain's Quarters^ 入口。在 ^Captain's Quarters^ 内，在第一个路口右转，走上一个短楼梯间。",
    ["After zoning in, proceed down the first hallway and clear the scorpion trash to open a door on your right. Click the ^Suramar Portal^ and teleport to the ^Nightspire^."] = "进入副本后，沿着第一个走廊前进，清除蝎子小怪，打开右边的门。点击 ^Suramar Portal^ 并传送到 ^Nightspire^。",
    ["After zoning in, proceed forward and clear the slimes to begin the encounter with ^Nythendra^."] = "划分区域后，继续前进并清除史莱姆，开始与 ^Nythendra^ 的战斗。",
    ["After zoning in, proceed forward out of ^The Coliseum^."] = "进入副本后，继续走出 ^The Coliseum^。",
    ["After zoning in, proceed straight ahead to ^Champion of the Light^."] = "进入副本后，直行至^Champion of the Light^。",
    ["After zoning in, proceed straight ahead to ^Lady Ashvane^."] = "进入副本后，直行至^Lady Ashvane^。",
    ["After zoning in, proceed straight ahead to engage ^Goroth^."] = "进入副本后，继续直行前往^Goroth^。",
    ["After zoning in, proceed straight ahead to engage ^Magmorax^. Kill trash to start the encounter."] = "进入副本后，继续向前行驶以接合^Magmorax^。杀死小怪来开始战斗。",
    ["After zoning in, proceed straight ahead to engage ^Morchok^."] = "进入副本后，继续直行前往^Morchok^。",
    ["After zoning in, proceed straight ahead to engage ^Tortos^."] = "进入副本后，继续直行前往^Tortos^。",
    ["After zoning in, proceed straight ahead to the first boss room. Kill trash to start the encounter with ^Champion of the Light^."] = "进入副本后，径直前往第一个首领房间。杀死小怪以开始与 ^Champion of the Light^ 的战斗。",
    ["After zoning in, read the ^Scroll of Past Deeds^ beside ^Lorewalker Cho^ to skip straight to ^Garrosh Hellscream^.\nThe scroll unlocks for your whole account once any character has defeated Garrosh."] = "进入副本后，阅读 ^Lorewalker Cho^ 旁边的 ^Scroll of Past Deeds^ 直接跳到 ^Garrosh Hellscream^。\n一旦任何角色击败加尔鲁什，卷轴就会为您的整个帐户解锁。",
    ["After zoning in, run up the stairs straight ahead to engage ^The Demonic Inquisition^."] = "划分区域后，径直跑上楼梯与^The Demonic Inquisition^交战。",
    ["After zoning in, start killing trash. They will continue coming in waves until finally, you will meet ^Xavius^."] = "进入副本后，开始消灭小怪。他们将继续一波又一波地涌来，直到最后，您会遇到^Xavius^。",
    ["After zoning in, take a left and head towards ^The Black Forge^. Take the elevator down."] = "划分区域后，左转并朝 ^The Black Forge^ 方向行驶。乘电梯下去。",
    ["After zoning in, take a right and head for the map exit labeled ^Gallery of Failures^."] = "进入副本后，右转前往标有 ^Gallery of Failures^ 的地图出口。",
    ["After zoning in, take the escalator all the way up to engage ^Odyn^."] = "进入副本后，乘自动扶梯一路向上即可到达^Odyn^。",
    ["After zoning in, take the middle path labeled ^The Clutchwarren^."] = "进入副本后，走标记为 ^The Clutchwarren^ 的中间路径。",
    ["After zoning in, take the northeast path to ^The Arachnid Quarter^."] = "进入副本后，沿东北路径前往 ^The Arachnid Quarter^。",
    ["After zoning in, take the northeastern path towards the ^Iron Assembly^."] = "划分区域后，沿东北方向前往 ^Iron Assembly^。",
    ["After zoning in, talk to ^Gharg^ and tell him you're ready. He will send you up an elevator into ^The Coliseum^."] = "划分区域后，与 ^Gharg^ 交谈并告诉他你已经准备好了。他将送您乘电梯前往^The Coliseum^。",
    ["After zoning in, talk to ^Wrathion^ to trigger a cutscene, then kill some adds to start the fight with ^Carapace of N'Zoth^."] = "进入副本后，与 ^Wrathion^ 交谈以触发过场动画，然后杀死一些小怪以开始与 ^Carapace of N'Zoth^ 的战斗。",
    ["After zoning in, talk with ^Ensign Roberts^ to skip straight to ^Lady Jaina Proudmoore^."] = "进入副本后，与 ^Ensign Roberts^ 交谈，直接跳至 ^Lady Jaina Proudmoore^。",
    ["After zoning in, talk with ^Otoye^ to skip straight to ^Lady Jaina Proudmoore^."] = "进入副本后，与 ^Otoye^ 交谈，直接跳至 ^Lady Jaina Proudmoore^。",
    ["After zoning in, wait for the dialog to complete on the boat. You will be transported shortly."] = "进入副本后，等待船上对话完成。您很快就会被转移。",
    ["After zoning in, wait for the dialog to complete. You will be transported shortly."] = "进入副本后，等待对话框完成。您很快就会被转移。",
    ["After zoning in, walk straight ahead and kill the Tendrils to start the encounter with ^Taloc^."] = "进入副本后，径直向前走并杀死卷须，开始与 ^Taloc^ 的战斗。",
    ["After zoning in, walk up the ramp in front of you to find ^Wind Lord Mel'jarak^."] = "划分区域后，走上前面的坡道即可找到 ^Wind Lord Mel'jarak^。",
    ["After zoning in, you will find portals to your left/right depending on which skips you've unlocked.\n* Upper Citadel -> ^Shadow-Lord Iskar^\n* Destructor's Rise -> ^Mannoroth^\n\nNote: RetroRuns only has the route built for Mannoroth at this time."] = "进入副本后，左右两侧会根据你已解锁的捷径出现传送门。\n* 上层堡垒 -> ^Shadow-Lord Iskar^\n* 毁灭者高地 -> ^Mannoroth^\n\n注意：RetroRuns 目前只提供通往玛诺洛斯的路线。",
    ["After zoning into ^Crown of Gorgoa^, follow the path North to ^Guardian of the First Ones^."] = "划入 ^Crown of Gorgoa^ 后，沿着路径向北前往 ^Guardian of the First Ones^。",
    ["After zoning into ^Domination's Grasp^, proceed up the ramp. After some dialog, you can engage ^Anduin Wrynn^."] = "划入 ^Domination's Grasp^ 后，继续沿坡道行驶。经过一番对话后，您可以使用 ^Anduin Wrynn^。",
    ["After zoning into ^Genesis Cradle^, follow the path to ^Dausegne^."] = "分区到 ^Genesis Cradle^ 后，沿着路径前往 ^Dausegne^。",
    ["After zoning into ^The Grand Design^, move straight ahead to ^The Jailer^'s platform and end this."] = "划入^The Grand Design^后，直接前往^The Jailer^平台并结束。",
    ["After zoning into ^The Primal Bulwark^, there are 3 paths available. Take the path on the right labeled ^The Vault Approach^."] = "分区到 ^The Primal Bulwark^ 后，有 3 条可用路径。走右侧标记为 ^The Vault Approach^ 的路径。",
    ["After zoning into ^The Torment Chambers^, follow the path to ^Soulrender Dormazain^."] = "分区到 ^The Torment Chambers^ 后，沿着路径前往 ^Soulrender Dormazain^。",
