    ["Ahead to Sinestra"] = "前往西奈斯特拉",
    ["Ahead to Sivara"] = "前往西瓦拉",
    ["Ahead to Stone Guard"] = "前往石守卫",
    ["Ahead to Taloc"] = "前往塔洛克",
    ["Ahead to Tel'arn"] = "前往特尔安",
    ["Ahead to Terros"] = "前往特罗斯",
    ["Ahead to The Jailer"] = "前往狱卒",
    ["Ahead to Thok"] = "前往托克",
    ["Ahead to Tortos"] = "前往托尔托斯",
    ["Ahead to Varimathras"] = "前往瓦里玛萨斯",
    ["Ahead to first boss"] = "走向第一个首领",
    ["Ahead to green Portal"] = "迈向绿色传送门",
    ["Approach Tindral"] = "接近廷德尔",
    ["Approach ^Tindral^ to trigger the encounter."] = "接近 ^Tindral^ 来触发战斗。",
    ["Approach the boss, and kill the trash to engage ^Rashok^."] = "接近首领，杀死小怪来与^Rashok^交战。",
    ["Approach the bridge and take a left. Follow the path to ^Oregorger^. Clear trash to spawn the boss."] = "接近桥并向左转。沿着路径前往 ^Oregorger^。清除小怪以出现 首领。",
    ["As you cross the bridge, dodge fire so you don't get thrown over the edge. At the end of the bridge, you will find ^Smolderon^."] = "当你过桥时，躲避火力，这样你就不会被扔到桥边。在桥的尽头，您会发现 ^Smolderon^。",
    ["At the bottom of the stairs, talk to Grand Artificer Romuul for several teleport options."] = "在楼梯底部，与大技师罗缪尔交谈以获取几种传送选项。",
    ["At the top of the stairs, clear the elite trash on the platform to spawn ^Garalon^."] = "在楼梯顶部，清除平台上的精英小怪以出现^Garalon^。",
    ["At the top of the stairs, walk through a door and click on the ^Displacement Pad^. After landing, engage ^Lei Shen^."] = "在楼梯顶部，穿过一扇门，然后点击 ^Displacement Pad^。着陆后，接合^Lei Shen^。",
    ["Avoid Sticky Webbing on the ground. The boss will attempt to pull you off the edge with Gossamer Burst. Easiest way to avoid this is to step on a Sticky Webbing before he finishes the cast. When he ascends, follow him up and finish the kill."] = "避免在地面上粘粘带。 首领 会尝试用薄纱爆裂将你从边缘拉出来。避免这种情况的最简单方法是在他完成石膏固定之前踩上粘性织带。当他上升时，跟随他并完成击杀。",
    ["Avoid blue circles"] = "避免蓝色圆圈",
    ["Back down stairs"] = "回到楼梯下",
    ["Back in ^Hellfire Antechamber^, follow the path to reach ^Gorefiend^. Kill the trash to start the encounter."] = "返回^Hellfire Antechamber^，沿着路径到达^Gorefiend^。杀死小怪来开始战斗。",
    ["Back in ^The Primal Convergence^, follow the newly-opened path to ^Kurog Grimtotem^."] = "返回^The Primal Convergence^，沿着新打开的路径到达^Kurog Grimtotem^。",
    ["Back in ^Underhold Nexus^, go straight ahead to another door marked on the map."] = "回到^Underhold Nexus^，直走到地图上标记的另一扇门。",
    ["Back in the ^Ring of Containment^, head north to the map exit labeled ^Plague Vault^."] = "回到 ^Ring of Containment^，向北前往标记为 ^Plague Vault^ 的地图出口。",
    ["Back in the ^Underhold Nexus^, take the southern (final) door marked on the map."] = "回到^Underhold Nexus^，走地图上标记的南门（最后一个）。",
    ["Back in the main lobby, take the northeast exit towards ^Iron Assembly^."] = "回到主大厅，从东北出口朝 ^Iron Assembly^ 方向行驶。",
    ["Back on Antorus, proceed forward and click on one of the ^Lightforged Warframes^ to be flown to the next area."] = "返回安托鲁斯后，继续前进并点击一台 ^Lightforged Warframes^，飞往下一个区域。",
    ["Back on the main level of ^Astromancer's Rise^, take the northeast exit from the building towards the map exit labeled ^Shal'dorei Terrace^."] = "回到 ^Astromancer's Rise^ 的主层，从建筑物的东北出口朝标记为 ^Shal'dorei Terrace^ 的地图出口走。",
    ["Back through pipe"] = "通过管道返回",
    ["Back to Core hub"] = "返回核心中心",
    ["Back to Nighthold"] = "返回暗夜要塞",
    ["Back to Underhold Nexus"] = "返回地堡枢纽",
    ["Back to courtyard"] = "回到庭院",
    ["Backtrack"] = "回溯",
    ["Backtrack then left to Faerlina"] = "原路返回，左转前往法琳娜",
    ["Backtrack to Halls of Chosen"] = "原路返回天选者大厅",
    ["Backtrack to Halls of the Faithful"] = "原路返回忠实大厅",
    ["Backtrack to Ring of Containment"] = "返回收容环",
    ["Backtrack to The Primal Convergence"] = "回溯到原始聚合",
    ["Backtrack to The Vault Approach"] = "原路返回宝库通道",
    ["Backtrack towards Feast of Arrogance"] = "返回傲慢盛宴",
    ["Backtrack towards Kel'Thuzad"] = "原路返回克尔苏加德",
    ["Beacon to Burning Throne"] = "燃烧王座的灯塔",
    ["Beacon to The Exhaust"] = "排气管灯塔",
    ["Bell"] = "贝尔",
    ["Bosses must die around the same time. When you get polymorphed, run over green circles then press the button on your action bar to return to normal."] = "首领 必须大约在同一时间死亡。当你变形时，跑过绿色圆圈，然后按操作栏上的按钮恢复正常。",
    ["Bridge to Smolderon"] = "通往斯莫德隆的桥梁",
    ["Bridge to Teleporter"] = "传送桥",
    ["Bring boss health to 0 and it will trigger a new phase. Run to the boss, and an extra action button will appear. Use this button to enter the phylactery. Inside, kill the 1 enemy and you will appear back outside to kill the boss one more time."] = "将 首领 生命值降至 0 后会触发新阶段。跑到首领那里，会出现一个额外的动作按钮。使用此按钮进入命匣。在里面杀死 1 个敌人，你就会出现在外面再次杀死 首领。",
    ["Bring them down slowly. If any of them die before the final phase, the fight can bug/reset. Once all 4 are active, cleave them down."] = "慢慢地把它们拉下来。如果他们中的任何一个在最后阶段之前死亡，战斗就会出现错误/重置。一旦所有 4 个都处于活动状态，请将它们劈开。",
    ["Channel Formation Seed"] = "通道形成种子",
    ["Channel Seed to Create Bridge"] = "引导种子建立桥梁",
    ["Choose any dialog options to start the fight; doesn't matter. To beat this encounter, visit all 4 rooms one at a time (by chain or by lever, depending on order). Inside each room, click boxes and defeat enemies to fill the meter, then pull the room's lever. After you pull the 4th lever, the fight is over. You must beat the timer!"] = "选择任意对话选项开始战斗；没关系。为了击败这次战斗，请一次访问所有 4 个房间（通过链条或杠杆，取决于顺序）。在每个房间内，点击箱子并击败敌人以填满仪表，然后拉动房间的控制杆。拉动第四个控制杆后，战斗结束。你必须打败计时器！",
    ["Clear Eye's Platform"] = "清眼平台",
    ["Clear Eye's platform"] = "清理眼睛所在的平台",
    ["Clear Trash to Portal"] = "清除传送门小怪",
    ["Clear elites for Garalon"] = "加拉隆清除精英",
    ["Click 2x Runes"] = "点击 2x 符文",
    ["Click Artifact"] = "点击神器",
    ["Click Artifact by Bridge"] = "点击桥边的神器",
    ["Click Clutchwarren Runestones"] = "点击离合器沃伦符石",
    ["Click Console"] = "点击控制台",
    ["Click Displacement Pad"] = "点击位移垫",
    ["Click Displacement Pad (1)"] = "点击位移垫 (1)",
    ["Click Displacement Pad (2)"] = "点击位移垫 (2)",
    ["Click Downward Draft to Dathea"] = "点击下行气流前往达瑟雅",
