    ["Click Feather"] = "点击羽化",
    ["Click Focusing Iris"] = "点击聚焦之虹",
    ["Click Font of Power #1"] = "点击第 1 个力量之泉",
    ["Click Font of Power #2"] = "点击第 2 个力量之泉",
