    ["Click Scroll"] = "点击滚动",
    ["Click Scroll by Cho"] = "点击周卓旁的卷轴",
    ["Click Seed then Portal"] = "点击“种子”，然后点击“传送门”",
    ["Click Spoils"] = "点击战利品",
    ["Click Tears"] = "点击眼泪",
    ["Click Tears of Elune"] = "点击艾露恩之泪",
    ["Click Teleportation Pad"] = "点击传送垫",
    ["Click Teleporter"] = "点击传送器",
    ["Click Tidestone"] = "点击潮汐石",
    ["Click Titan Console"] = "点击泰坦控制台",
    ["Click Titan Console then Jump In"] = "点击泰坦控制台然后跳入",
    ["Click Valeera"] = "点击瓦莉拉",
    ["Click portal"] = "点击传送门",
    ["Click the ^Downward Draft^ to be flown to the platform and engage ^Dathea, Ascended^."] = "点击 ^Downward Draft^ 前往平台并参与 ^Dathea, Ascended^。",
    ["Click the ^Hammer of Khaz'goroth^ in the middle of this room after killing ^Demonic Inquisition^."] = "杀死^Demonic Inquisition^后，点击该房间中间的^Hammer of Khaz'goroth^。",
    ["Click the ^Tears of Elune^ in the middle of the room after killing ^The Desolate Host^."] = "杀死^The Desolate Host^后，点击房间中间的^Tears of Elune^。",
    ["Click the ^Tidestone of Golganneth^ after killing ^Mistress Sassz'ine^."] = "杀死^Mistress Sassz'ine^后点击^Tidestone of Golganneth^。",
    ["Click the portal to ^Wellspring Atrium^ to be teleported to the entrance."] = "点击 ^Wellspring Atrium^ 的传送门即可传送到入口。",
    ["Continue ahead into the main courtyard to find ^Spellblade Aluriel^."] = "继续前进进入主庭院，找到^Spellblade Aluriel^。",
    ["Continue ahead to clear the trash and engage ^King Rastakhan^."] = "继续清理小怪并参与 ^King Rastakhan^。",
    ["Continue backtracking through this room."] = "继续原路穿过这个房间。",
    ["Continue down spiral"] = "继续螺旋式下降",
    ["Continue down the path and clear the trash to spawn ^The Amalgamation Chamber^."] = "继续沿着路径前进并清除小怪以出现 ^The Amalgamation Chamber^。",
    ["Continue down the stairs, following the path until you reach ^Sisters of the Moon^."] = "继续走下楼梯，沿着小路直到到达 ^Sisters of the Moon^。",
    ["Continue following the linear path into the next room."] = "继续沿着直线路径进入下一个房间。",
    ["Continue following the path ahead to reach ^Sennarth^."] = "继续沿着前面的路到达^Sennarth^。",
    ["Continue following the path ahead to reach ^Terros^."] = "继续沿着前面的路到达^Terros^。",
    ["Continue following the path to arrive back at the ^The Primal Bulwark^."] = "继续沿着路径返回^The Primal Bulwark^。",
    ["Continue following the path to engage ^Fetid Devourer^."] = "继续按照路径参与 ^Fetid Devourer^。",
    ["Continue following the path to reach ^Vectis^."] = "继续沿着路径到达 ^Vectis^。",
    ["Continue following the path to reach ^Zek'voz, Herald of N'Zoth^. Clear trash to start the encounter."] = "继续沿着路径到达 ^Zek'voz, Herald of N'Zoth^。清除小怪以开始战斗。",
    ["Continue forward to ^The Jailer^'s platform and end this."] = "继续前进到^The Jailer^的平台并结束这一切。",
    ["Continue straight ahead to engage ^Conclave of the Chosen^."] = "继续直行接合^Conclave of the Chosen^。",
    ["Continue to Blackhand"] = "继续黑手",
    ["Continue up and around the stairwell until you reach ^Tichondrius^."] = "继续沿着楼梯间向上走，直到到达 ^Tichondrius^。",
    ["Continue working your way towards the central hub. When you get there, take the first path on the left and take the portal to ^Grizzly Hills^."] = "继续朝中央枢纽前进。当你到达那里时，走左边的第一条路，然后通过传送门到达^Grizzly Hills^。",
    ["Cross Bridge Ahead"] = "前方过桥",
    ["Cross Lava to Neltharion's Sanctum"] = "穿越熔岩前往奈萨里奥的圣殿",
    ["Cross the bridge behind ^Anduin^ to the teleporter. Select ^Proceed^."] = "穿过 ^Anduin^ 后面的桥到达传送器。选择^Proceed^。",
    ["Cross the room and take the southern exit."] = "穿过房间并从南出口走。",
    ["Cross to Maiden"] = "穿越到少女",
    ["Destroy Bells"] = "摧毁钟声",
    ["Destroy Cannons"] = "摧毁大炮",
    ["Dialog then Anduin"] = "对话然后安度因",
    ["Dialog then Portal"] = "对话然后传送门",
    ["Dialog then Raszageth"] = "对话然后拉萨格斯",
    ["Dialog then Shriekwing"] = "对话然后尖叫之翼",
    ["Dialog then Sludgefist"] = "先是对话，然后是泥拳",
    ["Dialog then Sylvanas"] = "对话然后希尔瓦娜斯",
    ["Dialog then Titan Console"] = "对话框然后是泰坦控制台",
    ["Door"] = "门",
    ["Down spiral to Shad'har"] = "螺旋下降到沙德哈",
    ["Down stairwell"] = "下楼梯间",
    ["Down to Cenarius"] = "下到塞纳留斯",
    ["Down to Cho"] = "下到曹",
    ["Down to Sisters"] = "下到姐妹们",
    ["Downstairs across to Magmaw"] = "下楼前往熔喉",
    ["Dragons"] = "龙",
    ["Dragons then Khadgar"] = "先是龙，然后是卡德加",
    ["Draven Starts Sludgefist"] = "德莱文开始泥拳",
    ["During dance phase, run to the spotlight. Walk in the direction of the other NPCs a few times. Jump to clear debuff stacks."] = "舞蹈阶段跑到聚光灯下。跟着其他 NPC 的方向移动几次。跳跃以清除减益层数。",
    ["East Exit"] = "东口",
    ["East then Elevator"] = "东，然后电梯",
    ["East then South"] = "先东后南",
    ["East to Elevator"] = "东至电梯",
    ["East to Heigan"] = "向东前往希尔盖",
    ["East to Loatheb"] = "向东前往洛欧塞布",
    ["East to Xhul'horac"] = "东至祖霍拉克",
    ["Eiendormi on Right"] = "右边的艾恩多米",
    ["Elevator"] = "电梯",
    ["Elevator to Blackhand"] = "电梯到黑手",
    ["Elevator to Terrace"] = "电梯至露台",
    ["Elunaria Portal"] = "艾露纳里亚传送门",
    ["Emerald Nightmare Portal"] = "翡翠梦魇传送门",
    ["Enter Cleft of Shadows"] = "进入阴影裂缝",
    ["Enter Gates of Org"] = "进入组织之门",
    ["Enter Molten Crucible"] = "进入熔炉",
    ["Enter the next room and kill ^Drest'agath^."] = "进入下一个房间并杀死^Drest'agath^。",
    ["Enter the room to engage with ^The Hivemind^."] = "进入房间与 ^The Hivemind^ 互动。",
    ["Enter the water and click the ^Oxygen-Rich Membrane^ for swim speed and water breathing. You must kill the last trash pack in the tunnel to spawn ^Blackwater Behemoth^."] = "进入水中并点击 ^Oxygen-Rich Membrane^ 查看游泳速度和水中呼吸。您必须杀死隧道中的最后一个小怪群才能出现 ^Blackwater Behemoth^。",
    ["Exit Portal Nearby"] = "附近的出口入口",
    ["Exit portal nearby."] = "出口传送门就在附近。",
    ["Exit via Stairwell"] = "通过楼梯间退出",
    ["Fall then path to Uu'nat"] = "坠落，然后通往乌纳特",
    ["Find the teleporter behind ^Lihuvim^ and select ^Domination's Grasp^."] = "找到 ^Lihuvim^ 后面的传送器并选择 ^Domination's Grasp^。",
    ["First left to Skorpyron"] = "第一个路口左转前往斯考匹隆",
    ["Fly Here"] = "飞到这里",
    ["Fly into Sky Portal"] = "飞入天空之门",
    ["Follow Path Ahead"] = "遵循前进的道路",
    ["Follow path"] = "遵循路径",
    ["Follow the foundry floor to ^Prototype Pantheon^."] = "沿着铸造车间前往^Prototype Pantheon^。",
    ["Follow the map from the entrance to ^The Tarragrue^."] = "从入口按照地图前往 ^The Tarragrue^。",
    ["Follow the mineshaft into the next room. After a lengthy dialog, speak to ^Norushen^ to start the encounter."] = "沿着矿井进入下一个房间。经过漫长的对话后，与 ^Norushen^ 交谈以开始战斗。",
    ["Follow the path all the way back to find ^Il'gynoth, Corruption Reborn^."] = "沿着路径一路返回即可找到^Il'gynoth, Corruption Reborn^。",
    ["Follow the path all the way back to meet the ^Council of Dreams^. Click each of the illusions to start the fight."] = "沿着小路一路返回即可见到^Council of Dreams^。点击每个幻象即可开始战斗。",
    ["Follow the path and kill ^Braekkas^ to open the wall. Continue on to find ^The Primal Council^."] = "沿着路径杀死^Braekkas^来打开墙壁。继续找到^The Primal Council^。",
    ["Follow the path around to ^Hellfire High Council^."] = "沿着路径前往 ^Hellfire High Council^。",
    ["Follow the path back out to the main courtyard, and make your way to the ^Captain's Quarters^ entrance on the southwest corner of the map. Inside the ^Captain's Quarters^, take your first right to go up a short stairwell."] = "沿着小路返回主庭院，然后前往地图西南角的 ^Captain's Quarters^ 入口。在 ^Captain's Quarters^ 内，在第一个路口右转，走上一个短楼梯间。",
    ["Follow the path down to ^Skolex^. Kill the trash to spawn the boss."] = "沿着路径向下到达 ^Skolex^。杀死小怪来出现 首领。",
    ["Follow the path through ^The Endless Foundry^, killing the trash on the way to ^Lihuvim^."] = "沿着 ^The Endless Foundry^ 的路径前进，消灭前往 ^Lihuvim^ 途中的小怪。",
    ["Follow the path through ^The Grand Design^, killing trash on the way to ^Lords of Dread^."] = "沿着 ^The Grand Design^ 的路径前进，在通往 ^Lords of Dread^ 的路上消灭小怪。",
    ["Follow the path to reach the ^Ascendant Council^."] = "沿着路径到达 ^Ascendant Council^。",
    ["Follow the path to the boss area, and clear the trash to spawn ^Volcoross^."] = "沿着路径前往 首领 区域，清除小怪以出现 ^Volcoross^。",
    ["Follow the path to the final map exit labeled ^N'Zoth^. Kill adds on the bridge to spawn a portal at the end."] = "沿路前往标有 ^N'Zoth^ 的最后一个地图出口。清理桥上的小怪，在桥尽头召出传送门。",
    ["Follow the path to the map exit labeled ^The Hive^."] = "沿着路径前往标记为 ^The Hive^ 的地图出口。",
    ["Follow the path up and to the left to reach ^Tectus^. Kill the (3) rock golems to spawn the boss."] = "沿着路径向上并向左行驶即可到达 ^Tectus^。杀死 (3) 个岩石傀儡来出现 首领。",
    ["Follow the path up the stairs and around to the map exit labeled ^Halls of Opulence^. Jump in the hole at the end of the path."] = "沿着楼梯向上并绕行至标有 ^Halls of Opulence^ 的地图出口。跳进路尽头的洞里。",
    ["Follow the path up to ^Broodkeeper Diurna^."] = "沿着路径一直走到 ^Broodkeeper Diurna^。",
    ["Follow the path. Once you reach the boss room, kill the final trash pack and talk to ^Lorewalker Cho^ to trigger the boss fight with ^Elegon^."] = "遵循路径。到达首领房间后，杀死最后一个小怪群并与 ^Lorewalker Cho^ 交谈以触发与 ^Elegon^ 的首领战斗。",
    ["For the knockback, position yourself between the boss and a tornado."] = "为了击退，请将自己置于 首领 和龙卷风之间。",
    ["Forward to Imonar"] = "转发至伊莫纳尔",
    ["From ^The Primal Convergence^, follow the path to the entrance labeled ^Iceskitter Hollow^."] = "从 ^The Primal Convergence^ 出发，沿着路径前往标有 ^Iceskitter Hollow^ 的入口。",
    ["From ^Wellspring Atrium^, take the final remaining exit labeled ^Throne of the Firelord^. Click on the ^Formation Seed^ to construct a bridge to the next area."] = "从 ^Wellspring Atrium^ 出发，走最后一个标记为 ^Throne of the Firelord^ 的出口。点击 ^Formation Seed^ 构建通往下一个区域的桥梁。",
    ["From the top of the elevator, proceed ahead up the ramp to find the ^Antoran High Command^."] = "从电梯顶部，沿着坡道继续前行，找到 ^Antoran High Command^。",
    ["Fyrakk additionally drops {item}, an omnitoken that exchanges for any tier slot. Not tracked here."] = "菲莱克还会掉落 {item}，这是一种可兑换任意套装部位的全能兑换物。本插件不追踪该物品。",
    ["Galewind Crag then Upward Draft"] = "狂风峭壁然后向上吃水",
    ["Gauntlet then Dragons"] = "手套然后龙",
    ["Go Here"] = "去这里",
    ["Grizzly Hills Portal"] = "灰熊丘陵传送门",
    ["Hans & Franz"] = "汉斯和弗朗兹",
    ["Head down the long hallway to the teleporter. Select ^Ephemeral Plains Alpha^."] = "沿着长长的走廊前往传送器。选择^Ephemeral Plains Alpha^。",
    ["Hole Behind Neltharion"] = "奈萨里奥后面的洞",
    ["Hole to East"] = "洞向东",
    ["If you end up in the maze phase, collect a green orb and use it to bring down the barrier. Movement abilities can be used to get through the maze if needed."] = "如果您最终进入迷宫阶段，请收集一个绿色球体并用它来拆除障碍物。如果需要，可以使用移动能力来穿过迷宫。",
    ["In ^Halls of the Faithful^, wind your way around to the room overlooking the dancers. Clear the trash, and the NPCs will enter the room and open both gates. Follow the path opened by ^Prince Renathal^, and make your way up the stairs to ^Pride's Prison^."] = "在 ^Halls of the Faithful^ 中，蜿蜒前往俯瞰舞者的房间。清理小怪，NPC 将进入房间并打开两扇门。沿着 ^Prince Renathal^ 打开的路径，爬上楼梯到达 ^Pride's Prison^。",
    ["In ^The Arachnid Quarter^, take your first left and follow the path to ^Anub'Rekhan^."] = "在 ^The Arachnid Quarter^ 中，第一个路口左转并沿路前往 ^Anub'Rekhan^。",
    ["In the ^Chamber of the Avatar^, move forward and kill trash to open the door, then watch some dialog before engaging with ^Fallen Avatar^."] = "在 ^Chamber of the Avatar^ 中，向前移动并杀死小怪以打开门，然后在与 ^Fallen Avatar^ 互动之前观看一些对话。",
    ["In the boss room, kill all of the trash and approach the boss to start the encounter with ^Kormrok^."] = "在首领房间里，杀死所有小怪并接近首领，开始与^Kormrok^的战斗。",
    ["In the next area, clear the trash before, on, and after the platform to force ^Gara'jal the Spiritbinder^ into combat."] = "在下一个区域，清除平台前、平台上和平台后的小怪，迫使^Gara'jal the Spiritbinder^进入战斗。",
    ["In the next area, follow the path around a few turns and up some stairs, killing trash on your way to ^Malkorok^."] = "在下一个区域，沿着小路转几个弯，爬上一些楼梯，在前往 ^Malkorok^ 的路上消灭小怪。",
    ["In the next area, follow the path to click a portal being channeled by ^Archmage Khadgar^."] = "在下一个区域中，按照路径点击由 ^Archmage Khadgar^ 引导的传送门。",
    ["In the next area, follow the path upstairs to the right and follow it around."] = "在下一个区域，沿着楼上的路向右走，然后沿着它走一圈。",
    ["In the next area, go east, then south down some stairs. When you reach the boss room, clear the trash to start the encounter with ^Socrethar the Eternal^."] = "在下一个区域，向东走，然后向南走一些楼梯。当你到达首领房间时，清除小怪即可开始与^Socrethar the Eternal^的战斗。",
    ["In the next area, kill several waves of trash. After killing ^Shanna Sparkfizz^, jump in the pipe to reach ^Siegecrafter Blackfuse^."] = "在下一个区域，杀死几波小怪。杀死^Shanna Sparkfizz^后，跳入管道到达^Siegecrafter Blackfuse^。",
    ["In the next area, move ahead into the cave to engage ^Tortos^."] = "在下一个区域，继续进入洞穴与 ^Tortos^ 交战。",
    ["In the next area, talk to ^Wrathion^ to trigger a cutscene, then kill some adds to start the fight with ^Carapace of N'Zoth^."] = "在下一个区域中，与^Wrathion^交谈以触发过场动画，然后杀死一些小怪以开始与^Carapace of N'Zoth^的战斗。",
    ["In the next area, you will pass through the spot where you killed ^Shadow-Lord Iskar^ previously. Continue following the path around, eventually reaching ^Fel Lord Zakuun^."] = "在下一个区域，你将经过你之前杀死^Shadow-Lord Iskar^的地方。继续沿着周围的路径前进，最终到达^Fel Lord Zakuun^。",
    ["Inside ^Defiant Ramparts^, follow the path to climb some stairs. Kill the last trash pack to spawn ^Assault of the Zaqali^."] = "在^Defiant Ramparts^内，沿着小路爬一些楼梯。杀死最后一个小怪群以出现 ^Assault of the Zaqali^。",
    ["Inside ^Iron Assembly^, follow the path around to ^Beastlord Darmac^."] = "在 ^Iron Assembly^ 内，沿着路径前往 ^Beastlord Darmac^。",
    ["Inside ^Orgrimmar^, move ahead into the boss tower to fight ^Kor'kron Dark Shaman^."] = "在 ^Orgrimmar^ 内，前进进入 首领 塔与 ^Kor'kron Dark Shaman^ 战斗。",
    ["Inside ^The Construct Quarter^, stick to the left and follow the path around to reach ^Patchwerk^."] = "进入 ^The Construct Quarter^ 后，保持靠左并沿路前往 ^Patchwerk^。",
    ["Inside ^The Heart of the Empire^, follow the path around to find some NPCs mourning over the corpse of ^King Rastakhan^. Talk to ^Otoye^ to be switched to Alliance temporarily."] = "在 ^The Heart of the Empire^ 内，沿着周围的路径寻找一些 NPC，他们正在为 ^King Rastakhan^ 的尸体哀悼。与^Otoye^交谈以暂时切换到联盟。",
    ["Inside ^The Military Quarter^, follow the path to reach some stairs. Go down and cross the room to reach ^Instructor Razuvious^."] = "进入 ^The Military Quarter^ 后，沿路前往楼梯。下楼并穿过房间即可抵达 ^Instructor Razuvious^。",
    ["Inside ^The Nightspire^, clear trash around the room to begin the encounter with ^Grand Magistrix Elisande^."] = "在 ^The Nightspire^ 内，清除房间周围的小怪，开始与 ^Grand Magistrix Elisande^ 相遇。",
    ["Inside ^The Plague Quarter^, follow the path south to reach ^Noth the Plaguebringer^."] = "进入 ^The Plague Quarter^ 后，沿路向南前往 ^Noth the Plaguebringer^。",
    ["Inside the ^Cleft of Shadows^, jump off to the left and head into another tunnel."] = "在 ^Cleft of Shadows^ 内，向左侧跳下并进入另一条隧道。",
    ["Inside the ^Halls of Opulence^, proceed straight ahead to the middle area to engage ^Opulence^."] = "在 ^Halls of Opulence^ 内，直行至中间区域与 ^Opulence^ 交战。",
    ["Inside the ^Precipice of Dreams^, follow the path all the way west to kill ^Za'qul, Harbinger of Ny'alotha^."] = "在^Precipice of Dreams^内，沿着小路一直向西杀死^Za'qul, Harbinger of Ny'alotha^。",
    ["Inside the ^Roost of Ji-Kun^, make your way up and around the long series of paths and stairwells until you reach the platform of ^Ji-Kun^. Avoid the snails; they will still 1-shot you."] = "在 ^Roost of Ji-Kun^ 内，沿着一长串的小路和楼梯间向上走，直到到达 ^Ji-Kun^ 的平台。避开蜗牛；他们仍然会向你开一枪。",
    ["Inside the boss room, head straight ahead to engage ^Opulence^."] = "在首领房间内，径直向前与^Opulence^交战。",
    ["Inside the next tunnel, follow the long path to reach ^General Nazgrim^."] = "在下一个隧道内，沿着长路到达^General Nazgrim^。",
    ["Interrupt/kill both trees to start the fight. When she casts Weaver's Burden on you, run it away from your primary position to drop it out of the way. During intermission(s), interrupt/kill adds."] = "打断/杀死两棵树来开始战斗。当她对你施放编织者的负担时，将其从你的主要位置跑开，将其扔到一边。在中场休息期间，中断/终止会增加。",
    ["Jaina then Portal"] = "吉安娜然后传送门",
    ["Jump between platforms, killing each of his limbs."] = "在平台之间跳跃，杀死他的四肢。",
    ["Jump down"] = "跳下来",
    ["Jump from West -> North -> East and kill them all within 60 seconds of eachother."] = "从西->北->东跳，并在 60 秒内将他们全部杀死。",
    ["Jump in Hole"] = "跳进洞里",
    ["Jump in Lava"] = "跳入熔岩",
    ["Jump in Lava (Heroic)"] = "跳入熔岩（英雄）",
    ["Jump in Purple Circle"] = "跳进紫色圆圈",
    ["Jump in Sewer"] = "跳入下水道",
    ["Jump in hole"] = "跳入洞中",
    ["Jump in purple Portal"] = "跳入紫色传送门",
    ["Jump in purple circle"] = "跳入紫色圆圈",
    ["Jump in the lava to die, and you will respawn at the raid entrance."] = "跳入熔岩中死去，然后你会在副本入口处重生。",
    ["Jump in the lava to die. You will respawn at the entrance. |cffffffff(Heroic Only)|r"] = "跳入熔岩而死。您将在入口处重生。 |cffffffff（仅限英雄）|r",
    ["Jump in to meet Mythrax"] = "跳下去前往密斯拉克斯",
    ["Jump in tunnel"] = "跳进隧道",
    ["Jump into Portal"] = "跳入传送门",
    ["Jump ledge to Sassz'ine"] = "跳下平台前往萨丝琳",
    ["Jump off Ledge"] = "跳下壁架",
    ["Jump off Platform"] = "跳下平台",
    ["Jump off and die"] = "跳下去死掉",
    ["Jump off the back of the platform to die and respawn at the entrance."] = "从平台后面跳下死亡并在入口处重生。",
    ["Jump off the ledge to your death, and you will respawn at the raid exit."] = "从壁架上跳下去死掉，然后你会在团队出口处重生。",
    ["Jump off to respawn"] = "跳下重生",
