    ["Kill Zon'ozz"] = "杀死佐诺兹",
    ["Kill ^Nythendra^, then talk to ^Malfurion Stormrage^ to skip to ^Cenarius^."] = "杀死^Nythendra^，然后与^Malfurion Stormrage^交谈以跳至^Cenarius^。",
    ["Kill the opening trash packs, and click the large artifact on either side of the bridge to open a path to skip straight to ^Blackhand^."] = "清理入口处的小怪，然后点击桥任一侧的大型神器，打开一条可直接跳到 ^Blackhand^ 的道路。",
    ["Kill the slimes to spawn ^The Forgotten Experiments^."] = "杀死史莱姆以出现 ^The Forgotten Experiments^。",
    ["Kill trash in the boss room to trigger some dialog and start the encounter with ^King Rastakhan^."] = "杀死首领房间中的小怪以触发一些对话并开始与 ^King Rastakhan^ 的战斗。",
    ["Kill trash waves until the south tower reaches 100%. Then climb the south tower, and shoot ^Galakras^ as many times as you can. Kill some more trash on the ground level until ^Galakras^ drops to the ground."] = "杀死小怪波直到南塔达到100%。然后爬上南塔，尽可能多地射击^Galakras^。在地面上杀死更多小怪，直到 ^Galakras^ 掉落到地面。",
    ["Kill waves of trash until the middle gate opens. Continue killing trash on both sides until they stop spawning, then pull ^Gothik^ down from the balcony to kill him."] = "清理一波波小怪，直到中间的大门打开。继续清理两侧的小怪，直到不再刷新，然后把 ^Gothik^ 从阳台上引下来并击杀他。",
    ["Kirin Tor Portal"] = "肯瑞托传送门",
    ["Leave instance group via LFG tool.\n\nNote: If you plan to visit the ^Waking Dream^ wing to kill ^N'Zoth^, you must have ^Ashjra'kamas, Shroud of Resolve^ in your inventory for the Queueing NPC to present the option."] = "通过队伍查找器离开副本队伍。\n\n注意：若要进入 ^Waking Dream^ 分区击杀 ^N'Zoth^，你的背包中必须有 ^Ashjra'kamas, Shroud of Resolve^，排队 NPC 才会提供该选项。",
