    ["Loop your way around the path and you will see ^Queen Azshara^ trapped. Clear the trash to engage ^Dark Inquisitor Xanesh^."] = "沿着小路绕一圈，您会看到 ^Queen Azshara^ 被困。清除小怪以参与^Dark Inquisitor Xanesh^。",
    ["Make your way down the spiral, following the path to reach ^Shad'har the Insatiable^."] = "沿着螺旋线向下走，沿着路径到达^Shad'har the Insatiable^。",
    ["Make your way up the path and stay to the right and find the map exit labeled ^The Ritual Chamber^."] = "沿着路径向上走，靠右行驶，找到标有 ^The Ritual Chamber^ 的地图出口。",
    ["Malfurion then Iris"] = "玛法里奥然后艾丽丝",
