    ["Nuke her. During intermission, kill tentacle(s) on the side platform(s)."] = "核弹她。中场休息时，杀死侧面平台上的触手。",
    ["Nuke her. If the fight extends into Phase 2, jump off the boat and make your way through the snow to find ^Jaina^ and finish her off."] = "核弹她。如果战斗延续到第二阶段，跳下船，穿过雪地找到 ^Jaina^ 并干掉她。",
    ["Oblivion stacks don't matter anymore, but avoid swirly/portal-looking areas on the ground. Stay away from the edge."] = "湮灭堆叠不再重要，但要避免地面上看起来像漩涡/传送门的区域。远离边缘。",
    ["On the beach, your goal is to destroy (7) ^Kor'kron Cannons^. Click the ^Spike Mines^ next to each cannon to destroy them."] = "在海滩上，您的目标是摧毁 (7) ^Kor'kron Cannons^。点击每门大炮旁边的 ^Spike Mines^ 来摧毁它们。",
    ["On the other side of the gate, proceed ahead to engage ^Iron Qon^."] = "在大门的另一侧，继续前进以接合 ^Iron Qon^。",
    ["Once in the ^Ring of Containment^, head to the leftmost map exit labeled ^Archives of Eternity^."] = "进入 ^Ring of Containment^ 后，前往最左侧标记为 ^Archives of Eternity^ 的地图出口。",
    ["Once inside ^Artifact Storage^, continue forward and click on the ^Secured Stockpile of Pandaren Spoils^ to begin the ^Spoils of Pandaria^ encounter."] = "进入 ^Artifact Storage^ 后，继续前进并点击 ^Secured Stockpile of Pandaren Spoils^ 开始战斗 ^Spoils of Pandaria^。",
    ["Once inside ^Loa's Sanctum^, follow the path straight ahead to engage ^Conclave of the Chosen^."] = "进入 ^Loa's Sanctum^ 后，沿着正前方的路径与 ^Conclave of the Chosen^ 交战。",
    ["Once inside ^Moonglade^, work your way down to ^Cenarius^ and kill him."] = "进入 ^Moonglade^ 后，一路走到 ^Cenarius^ 并杀死他。",
    ["Once inside ^Mulgore^, follow the path around, and clear the trash on your way to ^Elerethe Renferal^."] = "进入 ^Mulgore^ 后，沿着周围的小路走，并清除前往 ^Elerethe Renferal^ 途中的小怪。",
    ["Once the door opens, proceed through it and climb some stairs to reach ^Star Augur Etraeus^."] = "门打开后，穿过门并爬一些楼梯到达^Star Augur Etraeus^。",
    ["Once you arrive in ^Feast of Arrogance^, follow the path to find ^The Council of Blood^ at the far end of the room."] = "到达 ^Feast of Arrogance^ 后，沿着路径在房间的远端找到 ^The Council of Blood^。",
    ["Once you arrive in the ^Eye of Eternity^, click ^The Focusing Iris^ to start the encounter with ^Hagara the Stormbinder^."] = "到达 ^Eye of Eternity^ 后，点击 ^The Focusing Iris^ 开始与 ^Hagara the Stormbinder^ 的战斗。",
    ["Once you enter the ^Elarian Sanctuary^, approach the ^Essence of Eonar^ (blue floating orb), and interact with it to begin the encounter for ^Eonar the Life-Binder^."] = "一旦你进入^Elarian Sanctuary^，接近^Essence of Eonar^（蓝色浮动球体），并与其互动以开始^Eonar the Life-Binder^的战斗。",
    ["Once you land, take the middle (and final) path labeled ^The Clutchwarren^."] = "着陆后，走中间（也是最后）一条标有 ^The Clutchwarren^ 的路径。",
    ["Once you reach ^Helheim^, follow the path around to find ^Guarm^."] = "到达 ^Helheim^ 后，沿着周围的路径找到 ^Guarm^。",
    ["Once you reach ^Shal'dorei Terrace^, make your way over to ^High Botanist Tel'arn^ to begin the encounter."] = "到达 ^Shal'dorei Terrace^ 后，前往 ^High Botanist Tel'arn^ 开始战斗。",
    ["Once you reach the ^Ring of Containment^, take a right and head for the map exit labeled ^Gallery of Failures^."] = "到达 ^Ring of Containment^ 后，右转并前往标记为 ^Gallery of Failures^ 的地图出口。",
    ["Once you reach the bottom of the elevator, take the southern path to reach ^Hans'gar and Franzok^. After a brief dialog, kill the trash to start the encounter."] = "到达电梯底部后，沿南边小路到达^Hans'gar and Franzok^。简短的对话后，杀死小怪即可开始战斗。",
    ["Once you reach the top of the elevator, follow the path to the north to reach ^The Crucible^."] = "到达电梯顶部后，沿着小路向北到达^The Crucible^。",
    ["Once you're in mid-flight, talk to ^Sky Captain Swayze^ again to begin the encounter with ^Warmaster Blackhorn^."] = "飞行途中，再次与 ^Sky Captain Swayze^ 交谈以开始与 ^Warmaster Blackhorn^ 的战斗。",
    ["Open Masked Gate"] = "打开蒙面之门",
    ["Open the door in front of you to land in ^Horridon^'s room. After a brief dialog, kill the boss."] = "打开你面前的门，进入^Horridon^的房间。简短对话后，杀死首领。",
