    ["Proceed ahead to engage ^Aggramar^."] = "继续参与 ^Aggramar^。",
    ["Ragnaros defeated! Due to a Blizzard bug, it may take a moment for the game to register the kill. If your progress doesn't update after 10-15 seconds, /reload or re-log to force it."] = "已击败拉格纳罗斯！由于游戏错误，系统可能需要片刻才能记录击杀。如果 10-15 秒后进度仍未更新，请输入 /reload 或重新登录以强制刷新。",
