    ["Right to ramp"] = "坡道右侧",
    ["Run around the room killing elites/vehicles until the encounter with ^Hellfire Assault^ begins."] = "在房间里跑来跑去，杀死精英/车辆，直到遇到 ^Hellfire Assault^ 开始。",
    ["Run past the pond to find an exit portal among the trees."] = "跑过池塘，在树林中找到出口。",
    ["SW Exit to Kilrogg"] = "SW 出口至基尔罗格",
    ["Sarkareth additionally drops {item}, an omnitoken that exchanges for any tier slot. Not tracked here."] = "萨卡雷斯还会掉落 {item}，这是一种可兑换任意套装部位的全能兑换物。本插件不追踪该物品。",
    ["Sarkareth also drops {item}, which starts the quest chain that rewards Nasz'uro, the Unbound Legacy (Evoker only)."] = "萨卡雷斯还会掉落 {item}，它会开启一条任务线，最终奖励“纳兹乌罗，无拘传承”（仅限唤魔师）。",
