    ["Stairwell to Mirror Portal"] = "通往镜子传送门的楼梯间",
    ["Stand behind a pillar to line-of-sight his mind control (Relentless Domination)."] = "站在柱子后面以视线控制他的精神（无情的统治）。",
    ["Stand in Light, Click Button"] = "站在灯光下，点击按钮",
    ["Stand on boss and cleave everything down"] = "站在首领的立场上，劈开一切",
    ["Stay left, path to Patchwerk."] = "靠左走，前往帕奇维克",
    ["Stay near the center ring and kill adds as they come to you. It will take several minutes of killing trash waves until ^Kel'Thuzad^ engages."] = "留在中央圆环附近，击杀不断靠近的小怪。需要持续清理几分钟的小怪，直到 ^Kel'Thuzad^ 进入战斗。",
    ["Straight ahead"] = "直行",
