    ["Take Portal"] = "采取传送门",
    ["Take Purple Portal"] = "采取紫色传送门",
    ["Take one of the nearby Kirin Tor portals to be teleported to the raid entrance."] = "使用附近的肯瑞托传送门之一传送到团队入口。",
    ["Take portal"] = "进入传送门",
    ["Take the elevator up and continue forward to reach ^Blackhand^."] = "乘坐电梯上行，继续向前到达^Blackhand^。",
