    ["Talk to Odyn"] = "与奥丁交谈",
    ["Talk to Odyn to be teleported out of the instance."] = "与奥丁交谈以传送出实例。",
    ["Talk to Otoye"] = "与奥托耶交谈",
    ["Talk to Prince Renathal to teleport back to Sludgefist's platform, then run west to reach the exit."] = "与雷纳索尔王子交谈以传送回泥拳的平台，然后向西跑到达出口。",
    ["Talk to Renathal, Run West"] = "与雷纳索尔交谈，向西奔跑",
