    ["Talk to ^Sabellian^ to be ported to the entrance."] = "与 ^Sabellian^ 交谈以转移到入口。",
    ["Talk to ^Thrall^ to begin the fight with ^Ultraxion^."] = "与 ^Thrall^ 交谈，开始与 ^Ultraxion^ 战斗。",
    ["Talk to dragon"] = "与巨龙交谈",
