    ["Talk to the ^Essence of Eonar^ to be sent back to Antorus."] = "与 ^Essence of Eonar^ 交谈以将其发送回安托鲁斯。",
    ["Teleport then path to Rygelon"] = "传送后沿路前往莱葛隆",
    ["Teleport to Domination's Grasp"] = "传送至主宰之握",
    ["Teleport to Ephemeral Plains"] = "传送到短暂平原",
    ["Teleport to Font of Night"] = "传送到夜之泉",
    ["Teleport to Genesis Cradle"] = "传送到创世摇篮",
    ["Teleport to Nightspire"] = "传送到夜塔",
    ["Teleporter then Boss"] = "传送者然后是 首领",
    ["The goal is to collect (2) orbs from opposite sides of the room and deposit them into slots on each side of the boss. Next, the boss will become available to kill."] = "目标是从房间的相对两侧收集 (2) 个球体并将它们放入 首领 两侧的插槽中。接下来，首领将变得可供杀死。",
    ["The goal of the fight is to collect ^Felfire Munitions^ and run them to the ^Hellfire Cannons^. You collect munitions by killing ^Felfire-Imbued Siege Vehicles^ which will come in waves."] = "战斗的目标是收集 ^Felfire Munitions^ 并将它们运行到 ^Hellfire Cannons^。你可以通过杀死一波又一波的^Felfire-Imbued Siege Vehicles^来收集弹药。",
    ["The only mechanic that matters anymore is his knockback. Position yourself so it launches you to the left or right platform. Kill adds on both platforms and return to middle. For next knockback, let it knock you to the upper middle platform. Finish the boss there!"] = "唯一重要的机制是他的击退。调整好自己的位置，以便将您带到左侧或右侧的平台。杀死两个平台上的添加并返回到中间。对于下一次击退，让它把你击到中上平台。干掉那里的首领！",
    ["There is a large egg on each side of ^Sinestra^. Attack the boss/whelps until the barriers drop from these two large eggs. Kill the 2 large eggs, then kill the boss."] = "^Sinestra^ 的每一面都有一个大鸡蛋。攻击 首领/幼崽，直到这两个大蛋的障碍物掉落。杀掉2个大蛋，然后杀掉首领。",
    ["This time, take the far-left exit to reach ^The Elemental Conclave^."] = "这次，从最左边的出口到达^The Elemental Conclave^。",
    ["To avoid bugging the encounter, let each group of 3 fully land before killing any."] = "为了避免干扰战斗，请让每组 3 人完全着陆后再杀死任何人。",
