    ["Up to Xy'mox"] = "上楼前往赛·墨克斯",
    ["Upon landing back in ^Halls of the Faithful^, follow the path to the right and ^Prince Renathal^ will guide you to a mirror portal. Take this teleport for a shortcut back to the main entrance lobby in ^The Grand Walk^."] = "返回 ^Halls of the Faithful^ 后，沿着右侧的路径前进，^Prince Renathal^ 将引导您到达镜像传送门。通过此传送可以捷径返回 ^The Grand Walk^ 的主入口大厅。",
    ["Upon reaching ^Pride's Prison^, follow the path to engage ^Sun King's Salvation^."] = "到达 ^Pride's Prison^ 后，按照路径与 ^Sun King's Salvation^ 交战。",
    ["Upon zoning in, go up the stairs into the first room and watch some dialog. After that, engage ^Shriekwing^."] = "进入副本后，上楼梯进入第一个房间并观看一些对话。之后，参与^Shriekwing^。",
    ["Upon zoning in, talk to all 5 dragons. Then talk to ^Khadgar^ to begin the assault. Choose any dragon; doesn't matter."] = "划分区域后，与所有 5 条龙交谈。然后与 ^Khadgar^ 交谈以开始攻击。选择任何一条龙；没关系。",
    ["Upon zoning in, you will find ^Wrathion^ directly in front of you."] = "进入副本后，您会发现 ^Wrathion^ 就在您的前面。",
    ["Upstairs to Grong"] = "楼上到格隆",
    ["Upstairs to Ko'ragh"] = "去科拉格楼上",
    ["Upstairs to Mirror"] = "楼上的镜子",
    ["Upstairs to Precipice of Dreams"] = "通往梦想悬崖的楼上",
    ["Upstairs to Purloined Stores"] = "楼上被盗商店",
    ["Upstairs to The Clutchwarren"] = "上楼前往育巢区",
    ["Upstairs to the Right"] = "楼上右边",
    ["Use Teleporter"] = "使用传送器",
    ["Valeera on Left"] = "瓦莉拉（左）",
    ["Vent"] = "通风口",
    ["Vent Behind Neltharion then Jump"] = "奈萨里奥身后的通风口，然后跳下",
    ["Verdant Dreambreaker"] = "苍翠破梦者",
    ["View special note"] = "查看特殊说明",
    ["Wait for Tsulong"] = "等待祖龙",
    ["Wait for transport"] = "等待运输",
    ["Walk into (3) Floor Teleporters"] = "走进 (3) 层传送器",
    ["Walk into the ^beam of light^ and click the ^Extra Action Button^ to trigger a cutscene. After the cutscene, go up the stairs and jump off the ledge."] = "走进^beam of light^并点击^Extra Action Button^触发过场动画。过场动画结束后，上楼梯并从壁架上跳下来。",
    ["Walk over anima orbs to collect them, and bring them to ^Prince Renathal^ to free him."] = "走过心能球收集它们，并将它们带到 ^Prince Renathal^ 以释放他。",
    ["Warden Thul'tok then Portal"] = "典狱长苏托克和传送门",
    ["West Exit"] = "西口",
    ["West exit"] = "西侧出口",
    ["West stairwell"] = "西楼梯间",
    ["West then North"] = "先西后北",
    ["West to Abyssal Throne"] = "西至深渊王座",
    ["West to Chimaeron"] = "向西至奇梅隆",
    ["West to Conclave"] = "西至秘密会议",
    ["West to Iron Juggernaut"] = "向西到钢铁主宰",
    ["West to Iskar"] = "向西至伊斯卡",
    ["West to Occu'thar"] = "向西至奥库塔尔",
    ["West to Portal"] = "西至传送门",
    ["West to Shek'zeer"] = "向西至谢克泽尔",
    ["West to Tectus"] = "西至泰克图斯",
    ["West to The Queen's Court"] = "西至皇后法庭",
    ["West to World Soul"] = "西方世界灵魂",
    ["West to Za'qul"] = "向西至扎库尔",
    ["Western Stairwell"] = "西侧楼梯间",
    ["Western stairwell"] = "西楼梯间",
    ["When feathers spawn near the boss, grab one. Mount up and follow him."] = "当 首领 附近出现羽毛时，抓住一根。上马跟随他。",
    ["When the boss shields, you must kill the adds to break his shield. Use Neltharion's various abilities (Rushing Darkness, Calamitous Strike) to break walls and reach the adds. You can attack the shielded adds once you have Corruption cast on you."] = "当首领护盾时，你必须杀死小怪才能打破他的护盾。使用耐萨里奥的各种能力（冲锋黑暗、灾难打击）来打破墙壁并到达小怪。一旦你对你施放了腐蚀，你就可以攻击受到护盾的小怪。",
    ["When the ship stops, talk to ^Ensign Roberts^ to continue."] = "当船停止时，与 ^Ensign Roberts^ 交谈以继续。",
    ["When you arrive in ^The Primal Convergence^, take the first path on the left labeled ^Quarry of Infusion^."] = "当您到达 ^The Primal Convergence^ 时，走左侧第一条标记为 ^Quarry of Infusion^ 的路径。",
    ["When you reach ^Un'Goro Crater^, follow the linear path to the back and kill ^Il'gynoth^."] = "当你到达^Un'Goro Crater^时，沿着线性路径到后面并杀死^Il'gynoth^。",
    ["When you reach the bottom of the stairwell, cross the room and engage ^Maiden of Vigilance^."] = "当你到达楼梯井底部时，穿过房间并与 ^Maiden of Vigilance^ 交战。",
    ["When you reach the bottom, simply follow the path to ^Orgozoa^ and kill him."] = "当你到达底部时，只需沿着通往 ^Orgozoa^ 的路径并杀死他即可。",
    ["When you reach the central hub, take the map exit labeled ^Mulgore^."] = "当您到达中心枢纽时，请从标有 ^Mulgore^ 的地图出口离开。",
    ["When you reach the top of the staircase, you will go through a door and continue north to reach ^Sisters of the Moon^. For the next few areas, avoid the purple circular areas on the ground as they will stun you."] = "当您到达楼梯顶部时，您将穿过一扇门并继续向北到达^Sisters of the Moon^。对于接下来的几个区域，请避开地面上的紫色圆形区域，因为它们会让你晕眩。",
    ["When you reach the top of the stairwell, continue following the linear path to reach the map exit labeled ^The Nighthold^."] = "当您到达楼梯间顶部时，继续沿着线性路径到达标记为 ^The Nighthold^ 的地图出口。",
    ["When you're back in the central hub, take the final portal towards ^Un'Goro Crater^."] = "当您回到中心枢纽后，进入通往 ^Un'Goro Crater^ 的最终传送门。",
    ["Work your way through the next area, and kill ^Warden Thul'tok^ to spawn a portal. Walk through the portal."] = "穿过下一个区域，杀死 ^Warden Thul'tok^ 以出现一个传送门。穿过传送门。",
    ["Work your way up to ^Malfurion Stormrage^ and talk to him to open the ^Nightmare Iris^. Interact with it to skip ahead to ^Cenarius^."] = "一路走到 ^Malfurion Stormrage^ 并与他交谈以打开 ^Nightmare Iris^。与其交互以跳至 ^Cenarius^。",
    ["Work your way upstairs through ^The Vault Approach^ and you will enter ^The Clutchwarren^."] = "通过 ^The Vault Approach^ 上楼，您将进入 ^The Clutchwarren^。",
    ["Wrathion then Trash"] = "拉希奥然后是小怪",
    ["You arrive at ^Pinnacle of Domination^ right in front of ^Sylvanas Windrunner^. Walk towards the boss to trigger dialog and start the encounter."] = "您到达 ^Pinnacle of Domination^ 就在 ^Sylvanas Windrunner^ 前面。走向首领触发对话并开始战斗。",
    ["You can just attack through his shield at this point. But if you need help, kill Nightmare Ichors near the boss to bring down his shield. When he becomes vulnerable, go inside and finish him off."] = "此时你可以通过他的盾牌进行攻击。但如果你需要帮助，请杀死 首领 附近的梦魇脓液以摧毁他的护盾。当他变得脆弱时，进去解决他。",
    ["You have reached the final boss, ^Argus the Unmaker^. Kill him!"] = "您已到达最终首领，^Argus the Unmaker^。杀了他！",
    ["You have reached the final encounter. Kill ^Gul'dan^!"] = "你们已经到达了最后的相遇。杀死^Gul'dan^！",
    ["You have to destroy the blast doors on both sides of the furnace. Go to one side, and let engineers come to you. Kill them, pick up their bombs, and use them by the door until the door \"dies\". Repeat process on the other side. After both doors are down, take down the elemental."] = "你必须摧毁炉子两侧的防爆门。走到一侧，让工程师来找你。杀死他们，捡起他们的炸弹，然后在门边使用它们，直到门“死”为止。在另一侧重复该过程。两扇门都关闭后，消灭元素。",
    ["You will have to bring his health down to zero several times. In each intermission, you must kill an add called Organ of Corruption to continue the fight."] = "你将不得不多次将他的生命值降至零。在每次中场休息时，你必须杀死一个名为腐化器官的小怪才能继续战斗。",
    ["You will zone in right in front of ^Archimonde^. Kill him!"] = "您将位于 ^Archimonde^ 的正前方。杀了他！",
    ["^Immerseus^ alternates between phases several times. Phase1: Hit the boss. Phase2: Kill black blobs, heal blue ones if you can. The more killing/healing, the faster the fight."] = "^Immerseus^ 在各个阶段之间交替多次。第一阶段：击中首领。第二阶段：杀死黑色斑点，如果可以的话治愈蓝色斑点。击杀/治疗越多，战斗就越快。",
    ["^Mythic^-- Just nuke the boss. ^Heroic^/^Normal^: Kill trash to fill the energy bar. Eventually, (3) ^Unstable Core^ will drop. Pick them up and carry each of them towards the boss, and use the Extra Action Button to throw them. After doing this 3 times, the boss will spawn."] = "^Mythic^-- 用核武器攻击 首领。 ^Heroic^/^Normal^：杀死小怪以填充能量条。最终，(3) ^Unstable Core^ 将掉落。拿起它们并将它们带到首领那里，然后使用额外动作按钮将它们扔掉。这样做3次后，首领就会出现。",
    ["|cffF259C7(1)|r Click one of the Pterrordax to start the fight. |cffF259C7(2)|r Kill Brother/Sister. Killing too fast can bug the fight. |cffF259C7(3)|r Teleport to change boats and kill the other Brother/Sister. |cffF259C7(4)|r Teleport back to main platform and interrupt/kill the boss before he finishes casting Catastrophic Tides."] = "|cffF259C7(1)|r 点击其中一只翼手龙即可开始战斗。 |cffF259C7(2)|r 杀死兄弟/姐妹。击杀太快可能会扰乱战斗。 |cffF259C7(3)|r 传送换船并杀死其他兄弟/姐妹。 |cffF259C7(4)|r 在 首领 施放灾难之潮之前传送回主平台并打断/杀死他。",
    ["|cffF259C7(1)|r Hit the boss until he runs into the next room. |cffF259C7(2)|r In the next room, your goal is to kill the Synthesis Growths sticking to the walls on both sides of the room. Kill slimes on the floor to clear walking paths. Pickup glowing orbs along the way to keep sanity up. |cffF259C7(3)|r After the Synthesis Growths are all killed, follow the boss into the next room to finish the encounter."] = "|cffF259C7(1)|r 打 首领 直到他跑进下一个房间。 |cffF259C7(2)|r 在隔壁房间，您的目标是杀死粘在房间两侧墙壁上的合成生长物。杀死地板上的史莱姆以清理人行道。沿途拾取发光的球体以保持理智。 |cffF259C7(3)|r 合成生长体全部被杀死后，跟随首领进入下一个房间完成战斗。",
    ["|cffF259C7(1)|r Kill adds until a blue swirly portal (Mindgate) appears on the ground. Click it to be sent into the Mind of ^N'Zoth^. |cffF259C7(2)|r Note your location on the minimap, because your goal is to kill Psychus and return to your body as fast as possible and click it to return to the physical realm. |cffF259C7(3)|r Back outside, attack ^N'Zoth^. This phase may need to be repeated depending on speed. |cffF259C7(4)|r A waygate will spawn. Enter it to kill an add and return to ^N'Zoth^ and finish the fight."] = "|cffF259C7(1)|r 清理小怪，直到地面出现蓝色漩涡传送门（心灵之门）。点击它进入 ^N'Zoth^ 的心智。 |cffF259C7(2)|r 记住自己在小地图上的位置；你的目标是尽快击杀赛古斯并返回自己的身体，然后点击身体回到现实领域。 |cffF259C7(3)|r 返回外界后攻击 ^N'Zoth^。根据击杀速度，这个阶段可能需要重复。 |cffF259C7(4)|r 随后会出现一道传送门。进入其中击杀一名小怪，再返回 ^N'Zoth^ 完成战斗。",
    ["|cffF259C7(1)|r Watch for invasions on the minimap. Use Surge of Life to get around the map and defeat waves as they spawn. |cffF259C7(2)|r After clearing 2 waves, boss will emote that invaders are charging their weapons. This is your queue to walk over one of the teleports near the pull location to enter the ship. |cffF259C7(3)|r After entering the ship, kill the mob and then click all 4 crystals in each corner. Jump out of the ship and resume killing waves until the encounter completes."] = "|cffF259C7(1)|r 注意小地图上的入侵。使用生命涌动在地图上移动并击败产生的波次。 |cffF259C7(2)|r 清除2波后，首领会表现出入侵者正在为他们的武器充电。这是您要走过拉动位置附近的传送点之一以进入飞船的队列。 |cffF259C7(3)|r 进入船后，杀死小怪，然后点击每个角落的所有 4 个水晶。跳出船并继续击杀浪潮，直到战斗结束。",

    -- What's New window entries.
    ["**Boss progress now tracks correctly on non-English clients in Mists of Pandaria raids.** On a client running in a non-English language, killing a boss in Mogu'shan Vaults, Heart of Fear, Terrace of Endless Spring, Throne of Thunder, or Siege of Orgrimmar did not register the kill or advance the route: the boss progress list, travel note, and map line stayed on the first boss no matter how far you had cleared. The Encounter Journal lookup used to match kills was reading at a difficulty those raids do not offer. English clients were unaffected and remain unchanged."] = "**现在，在《熊猫人之谜》团队副本中，非英语客户端上的 首领 进度可以正确跟踪。** 在以非英语运行的客户端上，杀死魔古山宝库、恐惧之心、无尽春天平台、雷霆王座或奥格瑞玛之围中的 首领 不会记录击杀或推进路线：首领 进度列表、旅行笔记和地图线都会保留在第一个 首领 上，无论您清除了多远。用于匹配击杀的战斗日志查找的读取难度是这些团队副本所不具备的。英语客户未受影响且保持不变。",
    ["**Continued refinement of routes and travel notes across raids** -- smoother paths and clearer directions in a number of places."] = "**持续完善团队副本中的路线和游记**——许多地方的路径更加平滑，方向更加清晰。",
    ["**Localization fixes for Spanish clients.** Two Emerald Nightmare travel notes and twenty-one highlighted place names now render fully in Spanish, the Merithra and Vol'jin dialog triggers fire again, and the loot summary's chat rows (the \"From that kill\" heading, the \"New!\" tag, and the Mount, Pet, and Toy labels) are translated."] = "**西班牙文客户端的本地化修复。** 两条翡翠梦魇路线说明和二十一处高亮地点名称现在会完整显示为西班牙文；梅瑞瑟拉和沃金的对话触发器恢复正常；战利品摘要的聊天内容（“本次击杀所得”标题、“新！”标签以及坐骑、宠物和玩具标签）也已翻译。",
    ["**Localization support, starting with Spanish.** The groundwork is in place for RetroRuns to run in languages other than English: player-facing text now goes through a translation layer, and raid, wing, boss, and place names follow your game client's language. Spanish is the first language built on it, covering the interface and all route content on esES and esMX clients. More languages can now be added without further engine work. English clients are unchanged."] = "**本地化支持，首先推出西班牙文。** RetroRuns 现已具备使用英文以外语言运行的基础：所有面向玩家的文字都会经过本地化层，团队副本、分区、首领和地点名称也会跟随游戏客户端语言。西班牙文是首个支持的语言，覆盖 esES 和 esMX 客户端的界面及全部路线内容。今后可在无需继续改动引擎的情况下添加更多语言。英文客户端保持不变。",
    ["**Looking For Raid routing.** Queue into any LFR wing and RetroRuns lays out the path through that wing -- only the bosses you'll face, in the order you reach them, with the same walk-along directions, map lines, and waypoints as the full-raid routes. Wing progress and the per-difficulty pills track each wing on its own, so running a second wing of the same raid keeps its counts straight. This covers more than 80 wings across two dozen raids, spanning every expansion from Mists of Pandaria through Dragonflight. Expand any raid in the supported list to see its wings and per-wing progress at a glance."] = "**团队查找器路线。** 排队进入任意团队查找器分区后，RetroRuns 会按实际遇到的顺序显示该分区中的首领，并提供与完整团队副本路线相同的步行指引、地图路线和导航点。分区进度和各难度状态会分别追踪，因此运行同一团队副本的另一个分区时会保留各自的进度。该功能覆盖二十多个团队副本、近一百个团队查找器分区。",
    ["**Loot toasts now hold while you hover them.** Hovering a toast brings it back to full opacity and keeps it on screen for as long as the cursor stays on it, so there is time to read what dropped. Moving away resumes the fade from where it left off."] = "**鼠标悬停时，战利品提示框会保持显示。** 将鼠标移到提示框上会使其恢复为完全不透明，并在光标停留期间一直显示，让你有足够时间查看掉落内容。移开鼠标后，淡出会从之前暂停的位置继续。",
    ["**Loot toasts respond to clicks.** Right-click a toast to dismiss it. Ctrl-click to preview the item in the dressing room, whether it is an appearance, a mount, or a pet. Left-click opens the drop where it lives in your collection: appearances in the Appearances tab, mounts in the Mount Journal, pets in the Pet Journal, toys in the Toy Box. Opening a collection window is not possible during combat, so left-click waits until the fight is over; dismissing and previewing work at any time. The three gestures are listed in the toaster settings under Toaster Preview."] = "**战利品提示框现在支持点击操作。** 右键点击可将提示框关闭。按住 Ctrl 点击可在试衣间预览物品，无论它是外观、坐骑还是宠物。左键点击会在收藏中打开该掉落物所在的位置：外观位于“外观”标签页，坐骑位于坐骑收藏，宠物位于宠物手册，玩具位于玩具箱。战斗中无法打开收藏窗口，因此左键点击会等到战斗结束后再执行；关闭和预览则可随时使用。这三种操作也列在提示框设置的“提示框预览”部分。",
    ["**Minimized mode comes to life.** Collapse the main panel to enable minimized mode. The main panel is replaced with a much smaller bar that shows an abbreviated version of every step-by-step travel note, along with a quick snapshot of current boss progress. Supported on all raids, all routes; Full, Skip, and LFR."] = "**最小化模式正式启用。** 折叠主面板即可进入最小化模式。主面板会替换为更小的栏，显示每条分步路线说明的缩略版本，以及当前首领进度的简要概览。所有团队副本和路线均支持，包括完整、跳过和团队查找器路线。",
    ["**New travel icon, with a destination choice.** The travel icon beside each raid has a fresh look, and clicking it now lets you pick where to go: the raid entrance, or the Looking For Raid queue NPC."] = "**新增带目的地选择的旅行图标。** 每个团队副本旁的旅行图标采用了新外观；点击后可选择前往团队副本入口，或前往团队查找器排队 NPC。",
    ["**RetroRuns now speaks German, French, and Russian.** Full localization on deDE, frFR, and ruRU clients: the interface, every travel note and solo tip, boss and place names, achievement notes, sub-zone routing, dialog triggers, and the What's New window. Route tracking works the same as it does in English, including the steps that advance when you enter a specific part of a raid or when a boss speaks; quest, achievement, and place names carry Blizzard's official localized titles. English and Spanish clients are unchanged."] = "**RetroRuns 现已支持德语、法语和俄语。** deDE、frFR 和 ruRU 客户端现已完整本地化，包括界面、全部路线说明和单刷提示、首领与地点名称、成就说明、子区域路线、对话触发器以及“新增内容”窗口。路线追踪方式与英文客户端相同，包括进入团队副本特定区域或首领发言时自动推进的步骤；任务、成就和地点名称均采用暴雪官方本地化名称。英文和西班牙文客户端保持不变。",
    ["**Skip-availability stars no longer appear next to the raid name while you're on an active route.** They stay in the supported-raids list and the Skips window, where they help you choose a route; once you're running one, the choice is already made."] = "**当您处于活动路线上时，跳过可用性星星不再出现在团队名称旁边。**它们保留在支持的团队列表和“跳过”窗口中，在其中帮助您选择路线；一旦你运行了一个，你就已经做出了选择。",
    ["**The Dragon Soul routing hint before Ultraxion now appears.** The step telling you to talk to Thrall to begin the encounter could never display."] = "**巨龙之魂中奥卓克希昂之前的路线提示现已正常显示。** 提示你与萨尔交谈以开始战斗的步骤以前始终无法出现。",
    ["**The Skips window difficulty columns read Normal, Heroic, Mythic from left to right** -- the traditional progression order, with Mythic on the right."] = "**“跳过”窗口难度栏从左到右依次为“普通”、“英雄”、“神话”**——传统的进度顺序，右侧是“神话”。",
    ["**The loot summary no longer misses drops when loot arrives a moment after the loot window closes.** On higher-latency pulls the summary could appear empty; it now waits briefly for the last items."] = "**当战利品窗口关闭后不久到达时，战利品摘要不再错过掉落。** 在较高延迟的拉动中，摘要可能会显示为空；现在它会短暂等待最后的项目。",
    ["**The minimized bar shows the way out when a run is complete.** Finishing a raid in minimized mode used to leave the bar showing only the RetroRuns wordmark. It now reads \"Raid Complete!\" — or the skip and Raid Finder equivalents — with an abbreviated exit tip beneath it."] = "**路线完成后，最小化栏会显示离开方式。** 过去在最小化模式下完成团队副本时，栏中只会显示 RetroRuns 标志。现在它会显示“团队副本完成！”——跳过路线和团队查找器路线也会显示对应文字——并在下方提供简短的离开提示。",
    ["**The notification preview's Play button no longer runs into the notes beside it.** The button sizes to its own label and moves to its own line when the pair would reach the right-hand column."] = "**通知预览中的“播放”按钮不再与旁边的说明重叠。** 按钮会根据自身文字调整宽度；当按钮和说明即将伸入右侧栏时，按钮会移到单独一行。",
    ["**The panel now keeps one position across all characters.** The window's position has always been saved account-wide, but the game's own per-character frame memory was re-applying each character's last position over it, so every character ended up with the panel somewhere different. The saved position now wins everywhere: move it once and it stays there for the whole account."] = "**面板现在在所有角色上保持一个位置。** 窗口的位置始终在帐户范围内保存，但游戏自己的每个角色帧内存正在重新应用每个角色的最后一个位置，因此每个角色最终都会在不同的地方出现面板。保存的位置现在无处不在：移动一次，整个帐户都会保留在那里。",
    ["**The transmog window no longer shows a scrollbar when a boss's loot list fits.** A scrollbar, and a clipped travel button, appeared on bosses with a weapon-token footnote even when the list fit."] = "**当 首领 的战利品列表适合时，幻化窗口不再显示滚动条。** 即使列表适合，滚动条和剪辑的旅行按钮也会出现在带有武器标记脚注的 首领 上。",
    ["**The vendor travel button in the transmog window uses the correct plane icon and no longer sits under the scrollbar.**"] = "**幻化窗口中的商人旅行按钮现在使用正确的飞机图标，并且不再被滚动条遮挡。**",
    ["**Toaster settings page layout holds up in every language.** The header wraps inside the frame instead of running past it, and the explainer text, click-gesture legend, and loot-summary preview no longer overlap the sample toasts."] = "**提示框设置页面现在能适应所有语言。** 标题会在框架内自动换行，不再超出边界；说明文字、点击操作图例和战利品摘要预览也不再与示例提示框重叠。",
    ["Added"] = "新增",
    ["Changed"] = "改变了",
    ["Fixed"] = "修复",

