    ["Thorim"] = "托里姆",
    ["Freya"] = "弗蕾亚",
    ["Mimiron"] = "米米尔隆",
    ["General Vezax"] = "维扎克斯将军",
    ["Yogg-Saron"] = "尤格-萨隆",
    ["Algalon the Observer"] = "观察者奥尔加隆",
    -- Vault of Archavon: names from the game's own tables.
    ["Vault of Archavon"] = "阿尔卡冯的宝库",
    ["Archavon the Stone Watcher"] = "岩石看守者阿尔卡冯",
    ["Archavon"] = "阿尔卡冯",
    ["Emalon the Storm Watcher"] = "风暴看守者埃玛尔隆",
    ["Koralon the Flame Watcher"] = "火焰看守者科拉隆",
    ["Koralon"] = "科拉隆",
    ["Toravon the Ice Watcher"] = "寒冰看守者图拉旺",
    ["Toravon"] = "图拉旺",

    -- Translated interface, names and release notes
    ["**Brazilian Portuguese (ptBR), Traditional Chinese (zhTW), Korean (koKR), and Italian (itIT) localization.** The full interface, route notes, tips, achievements, and What's New now display in each of these languages on the matching client. With Spanish, German, French, Russian, and Simplified Chinese already supported, RetroRuns now speaks every language the game client offers."] = "**巴西葡萄牙语（ptBR）、繁体中文（zhTW）、韩语（koKR）和意大利语（itIT）本地化。** 对应语言的客户端现在可以用各自的语言显示完整界面、路线说明、提示、成就和“更新内容”。加上已支持的西班牙语、德语、法语、俄语和简体中文，RetroRuns 现已支持游戏客户端提供的所有语言。",
    ["**Boss kills could vanish from Boss Progress after a reload.** Kills of certain bosses -- Blood Prince Council, Oregorger, Kromog, the Northrend Beasts, and a few dozen more -- unchecked themselves on the next login, sending the route back to a boss already dead for the week. Those kills now stay counted."] = "**重新加载后，已击杀的首领可能从首领进度中消失。** 部分首领——鲜血王子议会、啃石者、克罗莫格、北裂境的野兽以及其他数十个——的击杀记录会在下次登录时取消勾选，使路线退回到本周早已击杀的首领。现在这些击杀会保留。",
    ["**Sample toasts on the settings pages could show boxes instead of text, or no title at all.** They now always use the game's standard typeface."] = "**设置页面上的示例通知可能显示方块而非文字，或完全没有标题。** 现在它们始终使用游戏的标准字体。",
    ["**Teleporter destinations in the Skips details read in English on translated clients.** They now show the game's own names for those places."] = "**跳过详情中的传送目的地在翻译客户端上显示为英文。** 现在会显示游戏中这些地点的本地名称。",
    ["**Item names in the transmog browser could flash in English before switching to your language.** They now render in your client's language right away."] = "**幻化浏览器中的物品名称可能先短暂显示英文，然后才切换为你的语言。** 现在会直接以你客户端的语言显示。",
    ["**\"Toaster\" stays in English in every language.** It is the feature's name, like RetroRuns itself."] = "**“Toaster”在所有语言中均保持英文。** 这是该功能的名称，与 RetroRuns 一样。",
    ["Blood Council"] = "鲜血议会",
    ["Faction Champions"] = "阵营冠军",
    ["Grong the Revenant"] = "还魂者格洛恩",
    ["Hagara the Stormbinder (lockout)"] = "哈格拉",
    ["Kromog, Legend of the Mountain"] = "克罗莫格，远山传奇",
    ["Oregorger the Devourer"] = "吞噬者奥尔高格",
    ["Queen Lana'thel"] = "兰娜瑟尔女王",
    ["Tectus, The Living Mountain"] = "泰克图斯，活体之山",
    ["The Defense of Eonar"] = "保卫艾欧娜尔",
    ["Valiona and Theralion"] = "瑟纳利昂与瓦里昂娜",
    ["(none)"] = "（无）",
    ["**Expansion names display in the client's language.** The expansion headers and dropdowns follow what the game's own journal shows, which localizes them on some clients."] = "**资料片名称会以客户端语言显示。** 资料片标题和下拉列表现在采用游戏冒险指南中的名称，因此会在支持的客户端上自动本地化。",
    ["**Left-clicking a loot toast for gear your class cannot wear now shows the appearance.** The appearances browser opened to an empty page because its view is filtered to classes that can equip the item; it now switches the class filter to one that can view the drop, and switches it back when you close the window."] = "**左键单击当前职业无法穿戴的装备掉落提示时，现在会显示对应外观。** 外观浏览器过去会打开空白页面，因为视图只显示能够装备该物品的职业。现在它会临时切换到可查看该掉落的职业，并在关闭窗口时恢复原筛选。",
    ["**Clicking a loot toast could open the appearances window on an unrelated page.** Every drop now opens to its own page, including shields, bows, guns, and wands your class cannot use -- the browser switches to a class that can see them and switches back when you close it. Appearances locked to the other faction say so and point at the preview instead of opening."] = "**左键单击掉落提示时，过去可能会打开无关页面的外观窗口。** 现在每件掉落都会打开自己的页面，包括当前职业无法使用的盾牌、弓、枪械和魔杖——外观窗口会切换到能看到它们的职业，关闭时再切换回来。限定为另一阵营的外观会予以说明并指向预览，而不会打开窗口。",
    ["**On non-English clients, the route-selection popup could show rows of empty squares with no raid name.** The popup could appear before its text was filled in, rendering its prompt in a font that lacks the client language's characters; it now stays hidden until fully populated and always uses a font that covers the client's language. If a font fails to load, which can happen with replaced game fonts, the addon falls back to the game's own font instead of leaving text unreadable."] = "**在非英文客户端上，路线选择弹窗可能显示一排空方块，却没有团队副本名称。** 弹窗有时会在文字填充完成前出现，并使用不包含客户端语言字符的字体。现在它会保持隐藏，直到内容全部填充完毕，并始终使用支持客户端语言的字体。若字体加载失败（替换游戏字体时可能发生），插件会改用游戏自带字体，而不会留下无法阅读的文字。",
    ["**On translated clients, the word above the SKIP button could overlap the \"Select Route\" prompt.** Hovering FULL or SKIP shows that button's word in your language above it, and on a longer word it ran into the prompt line. The dialog now leaves room for it."] = "**在已翻译客户端上，SKIP按钮上方的文字可能与“选择路线”提示重叠。** 将鼠标移到FULL或SKIP上时，按钮上方会显示该词的本地化版本；较长的翻译会挤入提示行。现在对话框会为其预留足够空间。",
    ["**Raids that share one lockout across two difficulties now recognize the week's progress from either side.** Entering the other difficulty of a lockout you had already progressed showed a fresh run and asked you to pick a route again; the addon now resumes your route, counts the kills you already have, and shows the run as complete when the lockout is finished."] = "**两个难度共享同一进度的团队副本，现在可以从任一难度识别本周进度。** 进入已推进进度的另一个难度时，插件过去会将其视为全新副本，并再次要求选择路线。现在会继续原有路线、计入已经击败的首领，并在该进度完成时将副本标记为完成。",
    ["**Simplified Chinese (zhCN) localization.** The full interface, route notes, tips, and What's New now display in Simplified Chinese on Chinese clients."] = "**简体中文（zhCN）本地化。** 中国客户端现在可以用简体中文显示完整界面、路线说明、提示和“更新内容”。",
    ["**The Achievements section now appears for every boss.** Bosses with no tracked achievements show the section with \"None\" rather than hiding it; the row opens the Achievements window."] = "**每个首领现在都会显示“成就”区域。** 没有追踪成就的首领会显示“无”，而不是隐藏该区域；点击这一行会打开成就窗口。",
    ["**The Achievements window no longer changes width when switching raids.** It keeps the widest size it has needed so far and only its bottom edge moves, matching the transmog popup's behavior."] = "**切换团队副本时，成就窗口不再改变宽度。** 它会保留曾经需要的最大宽度，只移动底部边缘，与幻化弹窗的行为一致。",
    ["**The divider above the routing legend crowded the lines above and below it.** With several expansions listed, the supported-raids list grew into the space reserved for the legend, leaving the divider and its gem overlapping the last raid row and the legend text."] = "**路线图例上方的分隔线与上下内容过于拥挤。** 当列出多个资料片时，受支持团队副本列表会延伸到为图例预留的空间，使分隔线及其宝石与最后一行团队副本和图例文字重叠。",
    ["**The Firelands Glory reward rendered as plain text until the item cache primed.** The reward now resolves through the mount's spell link like every other Glory, so it links immediately."] = "**火焰之地“荣耀”成就奖励在物品缓存完成前会显示为普通文字。** 现在该奖励会像其他“荣耀”成就一样通过坐骑法术链接解析，因此可以立即显示为链接。",
    ["**The selected On/Off choice under \"Hide Blizzard Boss Banner:\" showed no underline.** The row's wide label pushed its buttons to a fractional pixel position where the hairline could vanish; positions now round to whole pixels and the underline uses the same pixel-grid handling as the dividers."] = "**“隐藏暴雪首领横幅：”下方选中的开/关选项没有下划线。** 较宽的标签会把按钮推到非整数像素位置，使细线可能消失。现在位置会取整到完整像素，下划线也使用与分隔线相同的像素网格处理。",
    ["**The skip route's target boss showed in English on translated clients.** The route picker's SKIP button names the boss the shortcut skips ahead to, and that name was printed from the addon's own English text rather than the game's. It now shows the name your client uses, on every raid with a skip route."] = "**在已翻译客户端上，跳过路线的目标首领名称会显示为英文。** 路线选择器的SKIP按钮会显示捷径通往的首领，但名称来自插件自身的英文文本，而不是游戏客户端。现在所有带跳过路线的团队副本都会使用客户端中的本地化名称。",
    ["**The Sun King's Salvation tip in Castle Nathria was removed.**"] = "**已移除纳斯利亚堡“太阳之王的救赎”提示。**",
    ["**The Toaster settings click legend now reads \"Left-Click: Collections\"** (was \"Left-Click: Open in Collections\"), in all languages."] = "**Toaster设置中的点击说明现已改为“左键单击：藏品”**（原为“左键单击：在藏品中打开”），并同步到所有语言。",
    ["**The transmog browser opened on another character's class.** The class filter is saved for the whole account, so a choice made on one character followed you to the next. The browser now opens on the class you are playing until you pick a different one on that character."] = "**幻化浏览器曾以另一个角色的职业打开。** 职业筛选会在账号范围保存，因此一个角色上的选择会带到下一个角色。现在浏览器会默认使用当前角色的职业，直到你在该角色上主动选择其他职业。",
    ["**The transmog browser tracks the other faction's drops.** Faction-locked items were hidden entirely, but the game grants the opposite faction's appearance when its counterpart drops for you, so they are collectible. They appear in their own block at the bottom of each boss's list, tagged with the faction they belong to, and light up as you collect them. The needed counts still cover only what your character can loot."] = "**幻化浏览器现在会追踪另一阵营的掉落。** 阵营限定物品此前会被完全隐藏，但当对应物品掉落时，游戏也会解锁另一阵营的外观，因此这些物品同样可以收集。它们现在会显示在每个首领列表底部的独立区域，并标注所属阵营；收集后也会亮起。所需数量仍只统计当前角色能够拾取的物品。",
    ["**The Volcanius marker in Vault of the Incarnates is a plain point of interest.** It was a pulsing ring of the kind that turns gray and ticks itself off once you pass it, but that kill cannot be detected, so the ring never resolved."] = "**化身巨龙牢窟中的沃尔卡尼乌斯标记现在是普通兴趣点。** 它之前使用经过后变灰并自动完成的脉冲圆环，但该击杀无法被检测，因此圆环始终不会完成。",
    ["**The Wrath of the Lich King raids join RetroRuns.** All nine raids now have full routing and transmog tracking: Naxxramas, The Eye of Eternity, The Obsidian Sanctum, Onyxia's Lair, Vault of Archavon, Ulduar, Trial of the Crusader, Icecrown Citadel, and The Ruby Sanctum. Every raid carries step-by-step routing, boss progress, tier sets, special drops, achievements, and exit directions at every difficulty the raid offers. Icecrown Citadel is guided end to end across all twelve bosses for both factions, with the gunship and Deathbringer Saurfang approaches routed separately for Alliance and Horde. Valithria Dreamwalker is optional, and the guide follows players who run past her, picking up at Sindragosa; turn back for her and the route follows you back, and the run reads as complete once the Lich King falls either way. Ulduar offers guidance through each hard-mode available, along with hard-mode loot tracking in the transmog browser. Trial of the Crusader and Icecrown Citadel field a different encounter depending on your faction, and the boss list, route, and notes follow the one you actually fight."] = "**《巫妖王之怒》的团队副本已加入RetroRuns。** 9个团队副本现已全部支持完整路线引导和幻化追踪：纳克萨玛斯、永恒之眼、黑曜石圣殿、奥妮克希亚的巢穴、阿尔卡冯的宝库、奥杜尔、十字军的试炼、冰冠堡垒和红玉圣殿。每个团队副本都包含逐步路线、首领进度、套装、特殊掉落、成就以及所有可用难度的离场指引。冰冠堡垒为联盟和部落完整引导全部12个首领，并分别提供炮艇战和死亡使者萨鲁法尔的阵营路线。踏梦者瓦莉瑟瑞娅为可选首领：若直接绕过她，路线会从辛达苟萨继续；若返回完成她的战斗，路线也会随之返回。无论哪种方式，击败巫妖王后都会将本次副本标记为完成。奥杜尔提供所有可用困难模式的指引，并在幻化浏览器中追踪困难模式掉落。十字军的试炼和冰冠堡垒会根据阵营出现不同战斗，首领列表、路线和提示会显示你实际面对的版本。",
    ["**Two boss names were spelled differently than the game spells them.** Tomb of Sargeras travel notes read \"Kil'Jaeden\" (the game uses \"Kil'jaeden\") and a Sanctum of Domination note read \"the Tarragrue\" mid-sentence where the boss is \"The Tarragrue\"."] = "**两个首领名称的拼写与游戏不一致。** 萨格拉斯之墓的路线说明写成了“Kil'Jaeden”（游戏使用“Kil'jaeden”），而统御圣所的一条说明在句中写成“the Tarragrue”，但该首领名称应为“The Tarragrue”。",
    ["25 Player Heroic only"] = "仅限25人英雄难度",
    ["Activate Tram"] = "启动轨道车",
    ["Alliance"] = "联盟",
    ["Antechamber of Ulduar"] = "奥杜尔前厅",
    ["Baltharus the Warborn"] = "战争之子巴尔萨鲁斯",
    ["Barrett Ramsey"] = "巴雷特·拉姆齐",
    ["Browse locked to %s. Ctrl+Left Click for Preview"] = "浏览已锁定为%s。Ctrl+左键单击可预览",
    ["Browse locked to classes that can equip this. Ctrl+Left Click for Preview"] = "浏览已锁定为可装备此物品的职业。Ctrl+左键单击可预览",
    ["Celestial Planetarium Access"] = "天文台入口",
    ["Conservatory of Life"] = "生命温室",
    ["Gas Release Valve"] = "毒气释放阀",
    ["General Zarithrian"] = "扎里斯里安将军",
    ["Hard mode only"] = "仅限困难模式",
    ["High Overlord Saurfang"] = "高阶督军萨鲁法尔",
    ["Highlord Tirion Fordring"] = "大领主提里奥·弗丁",
    ["Horde"] = "部落",
    ["Lever"] = "控制杆",
    ["Lore Keeper of Norgannon"] = "诺甘农的知识守护者",
    ["Mimiron's Head"] = "米米尔隆的头部",
    ["Muradin Bronzebeard"] = "穆拉丁·铜须",
    ["One difficulty per week; 10 and 25 share it"] = "每周只能选择一种难度；10人和25人共享进度",
    ["Ooze Release Valve"] = "软泥释放阀",
    ["Sara"] = "萨拉",
    ["Saronite Animus"] = "萨隆邪铁畸体",
    ["Saronite Vapors"] = "萨隆邪铁蒸汽",
    ["Saviana Ragefire"] = "塞维娅娜·怒火",
    ["Scourge Transporter"] = "天灾传送器",
    ["Ulduar Teleporter"] = "奥杜尔传送器",
    ["Upper Spire"] = "上层尖塔",

    ["**The transmog browser could open filtered to another class.** A class chosen in the browser's dropdown, or reached by clicking a drop toast for gear your character cannot wear, was remembered permanently, so later visits kept showing that class, on that character and on every other one that shared its class. The choice now lasts only as long as the browser is open; opening it again shows the class you are playing."] = "**幻化浏览器可能会以其他职业的筛选状态打开。** 在浏览器下拉菜单中选择的职业，或通过点击当前角色无法穿戴的装备掉落提示进入的职业，会被永久记住，因此之后再次打开时仍然显示该职业，在该角色以及所有同职业的角色上都是如此。现在该选择仅在浏览器打开期间有效；再次打开时会显示你正在游玩的职业。",

    ["Akama"] = "阿卡玛",
    ["Barnes"] = "巴内斯",
    ["King Llane"] = "莱恩国王",
    ["Warchief Blackhand"] = "大酋长黑手",

    ["**Collected items are dimmed in the transmog browser.** An item you have finished with now shows its name in gray rather than white, so the rows still worth your time stand out. An item counts as finished when every difficulty it drops at is collected."] = "**已收集的物品会在幻化浏览器中变暗。** 已经完成收集的物品名称现在会由白色变为灰色，让仍值得关注的行更加醒目。当该物品在所有会掉落它的难度下都已收集时，就会被视为完成。",
    ["**Direct routes to a raid's final boss.** Some legacy raids allow the player to bypass the raid, and walk directly to the final boss. Examples include Kael'thas Sunstrider in The Eye and Lady Vashj in Serpentshrine Cavern. Unlike modern raid skips, these aren't tied to quest completion. Where one exists, the load window offers it alongside the full clear, and your choice is remembered for the week."] = "**直达团队副本最终首领的路线。** 一些旧团队副本允许玩家跳过大部分流程，直接前往最终首领。例如风暴要塞的凯尔萨斯·逐日者和毒蛇神殿的瓦丝琪女士。与现代团队副本的捷径不同，这些路线不需要完成任务。若某个团队副本存在这种路线，加载窗口会将它与完整清除路线一起提供，并在本周内记住你的选择。",
    ["**Global POIs.** Useful fixtures such as repair vendors, quartermasters, etc. can now show on the raid map at all times, not only while a particular boss is your next objective. Vendors in Black Temple and Karazhan added to start, but more to come with the tooling now built."] = "**全局兴趣点。** 修理商人、军需官等实用设施现在可以始终显示在团队副本地图上，而不再只在某个特定首领是下一目标时显示。首批加入的是黑暗神殿和卡拉赞的商人；相关工具已经完成，之后还会继续增加。",
    ["**Hard-mode and opposite-faction drops fold into their own sections.** In the transmog browser, hard-mode-only drops (Ulduar) and the other faction's appearances (Trial of the Crusader) no longer run inline with the boss's loot list. Each now sits in its own collapsible section -- \"Hard Mode\", and \"Horde Appearances\" or \"Alliance Appearances\" depending on your character -- below the main list, collapsed until you expand it."] = "**困难模式和对立阵营掉落会折叠到各自区域。** 在幻化浏览器中，仅限困难模式的掉落（奥杜尔）以及另一阵营的外观（十字军的试炼）不再直接混在首领掉落列表中。它们现在分别位于主列表下方的可折叠区域中 -- “困难模式”，以及根据你的角色显示的“部落外观”或“联盟外观” -- 默认折叠，直到你主动展开。",
    ["**Icecrown Citadel's route could stall at The Spire on translated clients.** The step's location check only matched the English area name, so German, Spanish, French, Russian, and Simplified Chinese clients never saw it advance. It now matches each client's own name."] = "**在翻译客户端中，冰冠堡垒的路线可能会卡在尖塔。** 该步骤的位置检查只匹配英文区域名，因此德语、西班牙语、法语、俄语和简体中文客户端都无法看到它继续推进。现在会匹配各客户端自己的区域名称。",
    ["**Loot-toast clicks could leave the Appearances window drawing the wrong models.** Clicking a toast for an item your class cannot wear switches the wardrobe to a class that can; the window then kept the previous class's models under the new list until it was closed and reopened. It now redraws correctly."] = "**点击掉落 Toaster 可能导致外观窗口显示错误的模型。** 点击当前职业无法穿戴的物品 Toaster 时，衣柜会切换到能够穿戴该物品的职业；但在关闭并重新打开窗口之前，新列表下方仍会保留上一个职业的模型。现在会正确重新绘制。",
    ["**Section labels are now cyan.** The green and yellow section headings (Traveling, Achievements, Boss Encounter, Special Loot, Transmog Needed, Boss Progress, Trash Drops) now use the branded cyan instead."] = "**区域标题现在改为青色。** 原本使用绿色和黄色的区域标题（前往路线、成就、首领战、特殊战利品、尚缺幻化、首领进度、小怪掉落）现在统一使用 RetroRuns 的品牌青色。",
    ["**The Burning Crusade raids join RetroRuns.** All eight raids now have full routing and transmog tracking: Karazhan, Gruul's Lair, Magtheridon's Lair, Serpentshrine Cavern, The Eye, The Battle for Mount Hyjal, Black Temple, and Sunwell Plateau. Every raid carries step-by-step routing, boss progress, tier tokens resolved to each class's pieces, battle pets, and exit directions. Everything is translated in all nine supported languages."] = "**《燃烧的远征》团队副本加入 RetroRuns。** 现在全部 8 个团队副本都拥有完整路线和幻化追踪：卡拉赞、格鲁尔的巢穴、玛瑟里顿的巢穴、毒蛇神殿、风暴要塞、海加尔山之战、黑暗神殿和太阳之井高地。每个团队副本都提供逐步路线、首领进度、可对应到各职业套装部件的套装兑换物、战斗宠物以及出口指引。全部内容均已翻译为 9 种受支持的语言。",
    ["**The Transmog Needed summary takes up less space.** The [click to browse] hint now sits next to the heading instead of at the end of the counts, and the current difficulty shows as shorthand -- \"25H\" rather than \"25 Player (Heroic)\"."] = "**“尚缺幻化”汇总占用的空间更少。** [点击浏览] 提示现在位于标题旁边，而不是放在计数末尾；当前难度也改用缩写显示 -- 以“25H”代替“25人（英雄）”。",
    ["**The transmog window could grow upward after being moved.** Once dragged, expanding a section or switching bosses resized it from the center instead of downward from a fixed top edge."] = "**幻化窗口在移动后可能会向上增长。** 窗口一旦被拖动，展开区域或切换首领时会从中心调整大小，而不是以固定的顶部边缘向下扩展。",
    ["**Trash drops in the transmog browser.** Appearances that come off a raid's trash rather than a boss now have their own section, shown below whichever raid is selected. The section collapses to a single \"Trash Drops (collected/total)\" heading you can expand when you want it. Each row is tagged with how the item binds (BoP vs. BoE), and a BoE piece sitting in your bags is flagged as such so you don't miss it. Summary collection counter displays yellow until every appearance is collected, and green at 100%."] = "**幻化浏览器新增小怪掉落。** 来自团队副本小怪而非首领的外观现在拥有独立区域，显示在当前选中的团队副本下方。该区域可折叠为一个“小怪掉落（已收集/总数）”标题，需要时可展开。每一行都会标明物品的绑定方式（BoP 或 BoE）；如果你的背包里已有一件 BoE 物品，也会特别标记，避免遗漏。汇总收藏计数在所有外观收集完成前显示为黄色，达到 100% 后变为绿色。",

    ["Ayamiss"] = "阿亚米斯",
    ["Destroy Egg"] = "摧毁龙蛋",
    ["Fankriss"] = "范克瑞斯",
    ["Orb of Domination"] = "统御宝珠",
    ["Razorgore"] = "拉佐格尔",
    ["Suppression Devices"] = "压制装置",
    ["Vaelastrasz"] = "瓦拉斯塔兹",

    ["**Assorted display fixes.** Loot lines up in proper columns, a boss's ordinary loot no longer sorts above its tier list, rows that looked identical are told apart, loot toasts respond to clicks during combat, and travel buttons say \"Zone out first\" rather than placing a waypoint that cannot be routed to."] = "**多项显示问题修复。** 战利品现在会正确按列对齐，首领的普通战利品不再排到T套装列表上方，看起来相同的行会被区分，战斗中也可以点击战利品提示；旅行按钮会显示“请先离开副本”，而不是放置一个无法规划路线的路径点。",
    ["**Each faction's tier piece and its twin share one row** in the raids where every piece has a counterpart, with your own faction first and a marker for each version, so you can tell which of the two you still need."] = "**每个阵营的T套装部位与其对应版本共用一行** 在每件物品都有另一阵营对应版本的团队副本中，会先显示你自己的阵营，并为两个版本分别显示标记，方便看出还缺哪一个。",
    ["**Loot rows could show the wrong name color**, most often in the Wrath raids, where a row whose markers said collected still rendered its name gray."] = "**战利品行可能显示错误的名称颜色**，这种情况在《巫妖王之怒》团队副本中最常见：即使行内标记显示已收集，名称仍会显示为灰色。",
    ["**Optional bosses can be skipped.** A boss the route can bypass is marked as optional on the panel and in the Boss Progress list, and its encounter row offers a Skip Boss button. Skipping asks for confirmation first, because routing stays down for the rest of that lockout, and then sends you on to the next boss. The run finishes with a reminder that you can still go back and kill anything you skipped."] = "**可选首领现在可以跳过。** 路线可以绕过的首领会在面板和首领进度列表中标记为可选，其首领战行也会提供“跳过首领”按钮。跳过前会先要求确认，因为本次副本锁定期间将不再提供路线指引；确认后会继续前往下一个首领。本次通关结束时会提示：你仍然可以回头击杀跳过的首领。",
    ["**Redemption hints point at the right place.** Trial of the Crusader names the pieces your Trophies actually buy, and Siege of Orgrimmar no longer sends Alliance players to the Horde vendor's spot."] = "**兑换提示现在会指向正确位置。** 十字军的试炼会正确显示你的奖杯实际可以购买哪些部位，奥格瑞玛之围也不再把联盟玩家引导到部落商人的位置。",
    ["**Route notes advance promptly after fights the game reports oddly**, instead of waiting until you walk somewhere."] = "**游戏以异常方式报告战斗结果时，路线说明也会及时推进**，不再等到你走到其他位置才更新。",
    ["**Several raids were missing appearances entirely.** Trash and shared boss drops across Siege of Orgrimmar, Naxxramas and Throne of Thunder never appeared in the browser, so they read as uncollectable however many times you cleared the raid. All of them now show."] = "**多个团队副本曾完全缺少外观。** 奥格瑞玛之围、纳克萨玛斯和雷电王座中的小怪掉落及首领共享掉落从未出现在浏览器中，因此无论通关多少次都显示为不可收集。现在这些外观都会显示。",
    ["**The Classic raids are in.** Molten Core, Blackwing Lair, Ruins of Ahn'Qiraj and Temple of Ahn'Qiraj each come with full routing, loot, tier sets and trash drops, so the addon now guides you from Classic through Dragonflight."] = "**经典旧世团队副本已加入。** 熔火之心、黑翼之巢、安其拉废墟和安其拉神殿均已提供完整路线、战利品、T套装和小怪掉落，因此插件现在可以从经典旧世一路引导到《巨龙时代》。",
    ["**The transmog browser now covers dungeons.** A new Type selector switches between Raids and Dungeons; every legacy dungeon from Classic through Dragonflight is browsable with its bosses, loot, mounts, pets and toys -- 123 dungeons in all. Appearances track per difficulty where the game varies them."] = "**幻化浏览器现在也涵盖地下城。** 新增“类型”选择器可在团队副本和地下城之间切换；从经典旧世到《巨龙时代》的所有旧地下城均可浏览，包括首领、战利品、坐骑、宠物和玩具 -- 共123个地下城。若游戏按难度区分外观，外观也会按难度分别追踪。",
    ["**The transmog browser reads more clearly.** Item names follow the same color key as their difficulty markers, tier is set apart from ordinary loot and always leads the list, legendaries sit in their own block, and gear only one class can wear says so."] = "**幻化浏览器现在更清晰。** 物品名称使用与难度标记相同的颜色规则，T套装与普通战利品分开并始终排在列表最前，传说物品单独成块，仅限一个职业穿戴的装备也会明确标注。",
    ["**Tier rows tell you more.** They show which specializations a piece can be handed to, the full upgrade chain where one exists, and any appearance a piece can be traded up to. The explanation beneath a tier list now folds away when you do not want it."] = "**T套装行现在会显示更多信息。** 它们会显示该部位可交给哪些专精、存在时的完整升级链，以及该部位可以继续兑换成的任何外观。不需要时，现在可以折叠套装列表下方的说明。",
    ["**Tokens now tell you where to take them.** Tier tokens that cannot simply be right-clicked, and the omnitokens some bosses drop in place of a fixed piece, show a hint under the boss that drops them: the NPC to visit, what the turn-in costs, and a travel button where one can be reached. Icecrown Citadel's map marker points at the quartermaster who serves your own class."] = "**徽记现在会告诉你该去哪里兑换。** 无法直接右键使用的套装徽记，以及部分首领用来替代固定部位掉落的万能徽记，会在掉落它们的首领下方显示提示：要拜访的NPC、兑换所需费用，以及在可到达时提供旅行按钮。冰冠堡垒的地图标记会指向负责你当前职业的军需官。",

    ["**Assorted browser display fixes.** Loot lines up in proper columns, tier lists no longer sit double-spaced, a boss's ordinary loot no longer sorts above its tier list, rows that looked identical are told apart, and gear several classes can wear names the one you are looking at."] = "**浏览器的多项显示问题修复。** 战利品现在会正确按列对齐，T套装列表不再出现双倍行距，首领的普通战利品不再排到T套装列表上方，看起来相同的行会被区分，多个职业都能穿戴的装备也会标明你当前查看的职业。",
    ["**Smaller fixes.** Travel buttons say \"Zone out first\" rather than placing a waypoint that cannot be routed to, loot toasts respond to clicks during combat and open the right class's page, the Encounter Journal no longer redraws over itself, and row dividers no longer vanish at some window scales."] = "**小的修复。** 旅行按钮会显示“请先离开副本”，而不是放置一个无法规划路线的路径点；战斗中也可以点击战利品提示，并会打开正确职业的页面；冒险指南不再自我重绘；行分隔线在某些窗口缩放下不再消失。",
    ["**The Classic raids are in, and that completes the roster.** Molten Core, Blackwing Lair, Ruins of Ahn'Qiraj and Temple of Ahn'Qiraj each come with full routing, loot, tier sets and trash drops. With them, every legacy raid in the game is now covered -- Classic through Dragonflight, all 51, every one of them walked and routed."] = "**经典旧世团队副本已加入，名单就此完整。** 熔火之心、黑翼之巢、安其拉废墟和安其拉神殿均已提供完整路线、战利品、T套装和小怪掉落。至此，游戏中的每一个旧团队副本都已覆盖 -- 从经典旧世到《巨龙时代》，全部51个，每一个都实地走过并规划了路线。",
    ["**The transmog browser now covers dungeons.** A new Type selector switches between Raids and Dungeons, and every legacy dungeon from Classic through Dragonflight is there to browse boss by boss -- 123 dungeons in all, with appearances tracked per difficulty where the game varies them. Dungeons are browsing only for now; full guided routing, like the raids have, is coming soon. Probably."] = "**幻化浏览器现在也涵盖地下城。** 新增“类型”选择器可在团队副本和地下城之间切换，从经典旧世到《巨龙时代》的所有旧地下城均可按首领逐个浏览 -- 共123个地下城；若游戏按难度区分外观，外观也会按难度分别追踪。目前地下城仅支持浏览，像团队副本那样的完整路线指引即将推出。大概吧。",

    -- Route content translations
    ["%s & %s"] = "%s & %s",
    ["%s Reputation"] = "%s声望",
    ["%s Tier %s"] = "%s T%s",
    ["(optional)"] = "（可选）",
    ["(skipped)"] = "（已跳过）",
    ["1. Kill Baltharus"] = "1. 击杀巴尔萨鲁斯",
    ["2. Kill Saviana"] = "2. 击杀塞维娅娜",
    ["3. Kill Zarithrian"] = "3. 击杀扎里斯里安",
    ["After defeating ^Al'ar^, take the northwest exit and follow the path to ^Void Reaver^."] = "击败 ^Al'ar^ 后，从西北出口离开，沿路前往 ^Void Reaver^。",
    ["After defeating ^Archavon^, backtrack south and take your first left to find ^Toravon the Ice Watcher^."] = "击败^Archavon^后，向南原路返回，在第一个路口左转即可找到^Toravon the Ice Watcher^。",
    ["After defeating ^Azgalor^, take another long road to the far east. Stop and talk to ^Tyrande Whisperwind^ and continue north to ^Archimonde^."] = "击败 ^Azgalor^ 后，沿另一条长路一路向最东边走。停下来与 ^Tyrande Whisperwind^ 交谈，然后继续向北前往 ^Archimonde^。",
    ["After defeating ^Baron Geddon^, continue east until you reach ^Sulfuron Harbinger^."] = "击败^Baron Geddon^后, 继续向东前进，直到到达^Sulfuron Harbinger^.",
    ["After defeating ^Blood Prince Council^, take the ramp up and out of this room."] = "击败^Blood Prince Council^后，沿坡道上行并离开这个房间。",
    ["After defeating ^Buru the Gorger^, travel south up the ramp and loop around to the left to find ^Ayamiss the Hunter^."] = "击败^Buru the Gorger^后，沿斜坡向南上行，再绕到左侧找到^Ayamiss the Hunter^。",
    ["After defeating ^Ebonroc^, go up the ramp behind him."] = "击败^Ebonroc^后，从他身后的斜坡上去。",
    ["After defeating ^Eredar Twins^, exit northwest and follow the path to the spiral ramp. Continue on the path until you reach ^M'uru^."] = "击败 ^Eredar Twins^ 后，从西北方向离开，沿路前往螺旋坡道。继续沿路前进，直到到达 ^M'uru^。",
    ["After defeating ^Fathom-Lord Karathress^, take the eastern path out of the room and follow the path to ^Morogrim Tidewalker^."] = "击败 ^Fathom-Lord Karathress^ 后，从房间东侧路线离开，沿路前往 ^Morogrim Tidewalker^。",
    ["After defeating ^Festergut^, click the ^Gas Release Valve^ on the left side of the exit door. Then follow the path around to ^Rotface^."] = "击败^Festergut^后，点击出口门左侧的^Gas Release Valve^，然后沿路前往^Rotface^。",
    ["After defeating ^Firemaw^, continue northwest until you reach ^Ebonroc^."] = "击败^Firemaw^后, 继续向西北前进，直到到达^Ebonroc^.",
    ["After defeating ^Flame Leviathan^, proceed forward and take your first left. Follow the path down to ^Ignis the Furnace Master^."] = "击败^Flame Leviathan^后，向前走并在第一个路口左转。沿路下行前往^Ignis the Furnace Master^。",
    ["After defeating ^Freya^, backtrack to the ring and take the path northwest towards the map exit labeled ^The Spark of Imagination^. Climb aboard the tram and click the console to ^Activate Tram^."] = "击败^Freya^后，返回环形区域，沿西北方向前往地图出口^The Spark of Imagination^。登上轨道车并点击控制台^Activate Tram^。",
    ["After defeating ^Gehennas^, continue south to ^Garr^."] = "击败^Gehennas^后, 继续向南前进，直到到达^Garr^.",
    ["After defeating ^General Rajaxx^, travel northwest until you reach ^Moam^."] = "击败^General Rajaxx^后, 向西北前进，直到到达^Moam^.",
    ["After defeating ^General Vezax^, continue behind him to reach ^Yogg-Saron^. Approach ^Sara^ to start the encounter. See special note for |cffF259C7Hard Mode|r."] = "击败^General Vezax^后，从他身后继续前进即可到达^Yogg-Saron^。靠近^Sara^以开始战斗。请查看|cffF259C7困难模式|r特别提示。",
    ["After defeating ^High King Maulgar^, continue up the path to ^Gruul the Dragonkiller^."] = "击败 ^High King Maulgar^ 后，继续沿路向上前往 ^Gruul the Dragonkiller^。",
    ["After defeating ^High Warlord Naj'entus^, make your way up and through a pipe on the west side of the room."] = "击败 ^High Warlord Naj'entus^ 后，向上走并穿过房间西侧的管道。",
    ["After defeating ^Hodir^, return to the ring and take the northeast path towards ^Thorim^. Kill the trash to start the fight. See special note for |cffF259C7Hard Mode|r."] = "击败^Hodir^后，返回环形区域并沿东北方向前往^Thorim^。清理敌人以开始战斗。请查看|cffF259C7困难模式|r特别提示。",
    ["After defeating ^Hydross the Unstable^, head north and jump down to the platform in the middle of the water. Cast ^Fishing^ in the water swirl until you fish up ^The Lurker Below^."] = "击败 ^Hydross the Unstable^ 后，向北走并跳到水中央的平台。对水中的漩涡使用 ^Fishing^，直到钓起 ^The Lurker Below^。",
    ["After defeating ^Kalecgos^, continue east and follow the path towards ^Brutallus^."] = "击败 ^Kalecgos^ 后，继续向东并沿路前往 ^Brutallus^。",
    ["After defeating ^Kologarn^, cross his bridge-like body and go down the stairs to reach ^The Inner Sanctum of Ulduar^."] = "击败^Kologarn^后，从他如同桥梁的身体上走过，再下楼前往^The Inner Sanctum of Ulduar^。",
    ["After defeating ^Koralon^, backtrack and head north all the way to ^Archavon the Stone Watcher^."] = "击败^Koralon^后，原路返回并一路向北前往^Archavon the Stone Watcher^。",
    ["After defeating ^Kurinnaxx^, continue south until you reach ^General Rajaxx^."] = "击败^Kurinnaxx^后, 继续向南前进，直到到达^General Rajaxx^.",
    ["After defeating ^Lady Deathwhisper^, an elevator will drop down. Ride this elevator up to the next area."] = "击败^Lady Deathwhisper^后，电梯会降下。乘坐电梯前往下一个区域。",
    ["After defeating ^Lord Jaraxxus^, talk to ^Barrett Ramsey^ again to start the next encounter vs. ^Champions of the Horde^."] = "击败^Lord Jaraxxus^后，再次与^Barrett Ramsey^交谈，开始下一场对阵^Champions of the Horde^的战斗。",
    ["After defeating ^Magmadar^, follow the path west until you reach ^Gehennas^."] = "击败^Magmadar^后, 沿路向西前进，直到到达^Gehennas^.",
    ["After defeating ^Maiden of Virtue^, follow the long, winding path until you reach ^Barnes^. Talk to him to start the ^Opera Hall^ encounter."] = "击败 ^Maiden of Virtue^ 后，沿着漫长蜿蜒的路线前进，直到到达 ^Barnes^。与他交谈以开始 ^Opera Hall^ 遭遇战。",
    ["After defeating ^Majordomo Executus^, jump down and make your way to the center of the instance. Talk to ^Majordomo^ to summon ^Ragnaros^."] = "击败^Majordomo Executus^后，跳下去前往副本中央。与^Majordomo^交谈以召唤^Ragnaros^。",
    ["After defeating ^Morogrim Tidewalker^, continue south, and work your way around the path to the east until you reach the ^Lady Vashj Bridge Console^. Click the console to open the bridge, then cross it to reach the final boss, ^Lady Vashj^."] = "击败 ^Morogrim Tidewalker^ 后，继续向南，再沿路线绕向东边，直到到达 ^Lady Vashj Bridge Console^。点击控制台打开桥梁，然后过桥前往最终首领 ^Lady Vashj^。",
    ["After defeating ^Mother Shahraz^, take the nearby exit to the south."] = "击败 ^Mother Shahraz^ 后，从附近的南侧出口离开。",
    ["After defeating ^Nightbane^, exit to the east (the way you came in). Back in ^The Broken Stair^, go up the ramp right above you and take a right when you reach the top."] = "击败 ^Nightbane^ 后，向东离开（沿来时的路）。回到 ^The Broken Stair^ 后，沿你正上方的坡道上去，到顶部后右转。",
    ["After defeating ^Opera Hall^, go up the ramp on the south side of the stage."] = "击败 ^Opera Hall^ 后，从舞台南侧的坡道上去。",
    ["After defeating ^Ouro^, travel northwest and stay to the right as you work your way up a long spiral."] = "击败^Ouro^后，向西北前进，并在沿长螺旋上行时靠右。",
    ["After defeating ^Professor Putricide^, backtrack to the main ring and take the northern path to reach ^Blood Prince Council^."] = "击败^Professor Putricide^后，返回主环形区域并沿北侧通道前往^Blood Prince Council^。",
    ["After defeating ^Rage Winterchill^, speak to ^Lady Jaina Proudmoore^ to begin the next encounter against ^Anetheron^."] = "击败 ^Rage Winterchill^ 后，与 ^Lady Jaina Proudmoore^ 交谈，开始下一场与 ^Anetheron^ 的遭遇战。",
    ["After defeating ^Razorgore^, proceed northwest into the next room. Talk to ^Vaelastrasz the Corrupt^ to start the encounter."] = "击败^Razorgore^后，向西北进入下一个房间。与^Vaelastrasz the Corrupt^交谈开始战斗。",
    ["After defeating ^Reliquary of Souls^, backtrack to the main concourse."] = "击败 ^Reliquary of Souls^ 后，原路返回主大厅。",
    ["After defeating ^Shade of Akama^, backtrack out of this room and go east towards ^Gorefiend's Vigil^. Follow the path up a couple sets of stairs."] = "击败 ^Shade of Akama^ 后，从这个房间原路返回，并向东前往 ^Gorefiend's Vigil^。沿路向上，经过几段楼梯。",
    ["After defeating ^Shade of Aran^, exit the library and take a left up the ramp."] = "击败 ^Shade of Aran^ 后，离开图书馆并左转上坡。",
    ["After defeating ^Silithid Royalty^, backtrack out of their room. Go slightly up the ramp and exit north to find your way to ^Battleguard Sartura^."] = "击败^Silithid Royalty^后，原路离开房间。沿斜坡稍微上行，从北侧出去前往^Battleguard Sartura^。",
    ["After defeating ^Supremus^, continue up the ramp behind him into the next area."] = "击败 ^Supremus^ 后，沿他身后的坡道上去进入下一区域。",
    ["After defeating ^Terestian Illhoof^, backtrack up the ramp and back through the bookcase."] = "击败 ^Terestian Illhoof^ 后，沿坡道原路返回，再次穿过书架。",
    ["After defeating ^The Assembly of Iron^, backtrack to ^The Antechamber^ and go up the stairs to reach ^Kologarn^."] = "击败^The Assembly of Iron^后，返回^The Antechamber^并上楼前往^Kologarn^。",
    ["After defeating ^The Northrend Beasts^, talk to ^Barrett Ramsey^ again to start the next encounter vs. ^Lord Jaraxxus^."] = "击败^The Northrend Beasts^后，再次与^Barrett Ramsey^交谈，开始下一场对阵^Lord Jaraxxus^的战斗。",
    ["After defeating ^The Twin Emperors^, exit the room to the southwest and follow the path until you reach ^Ouro^. You can spawn him by walking over the patch of rumbling rocks."] = "击败^The Twin Emperors^后，从西南离开房间并沿路前往^Ouro^。走过震动的岩石区域即可让他出现。",
    ["After defeating ^Thorim^, backtrack to the ring and take the northern path to reach ^Freya^. Note: You can mount up in here. See special note for |cffF259C7Hard Mode|r."] = "击败^Thorim^后，返回环形区域并沿北侧通道前往^Freya^。注意：这里可以骑乘坐骑。请查看|cffF259C7困难模式|r特别提示。",
    ["After defeating ^Toravon^, backtrack south and take the next left to reach ^Emalon the Storm Watcher^."] = "击败^Toravon^后，向南原路返回，在下一个路口左转前往^Emalon the Storm Watcher^。",
    ["After defeating ^Vaelastrasz^, take the northwest stairwell out of the room."] = "击败^Vaelastrasz^后，从西北楼梯离开房间。",
    ["After defeating ^Void Reaver^, backtrack out of the room and head north as you loop around to ^High Astromancer Solarian^."] = "击败 ^Void Reaver^ 后，原路离开房间并向北绕行前往 ^High Astromancer Solarian^。",
    ["After defeating ^XT-002 Deconstructor^, click the ^Ulduar Teleporter^ atop the stairs. Select ^Antechamber of Ulduar^."] = "击败^XT-002 Deconstructor^后，点击楼梯顶部的^Ulduar Teleporter^，选择^Antechamber of Ulduar^。",
    ["After defeating ^Yogg-Saron^, exit the room and take the ^Ulduar Teleporter^ to ^Antechamber of Ulduar^."] = "击败^Yogg-Saron^后，离开房间并使用^Ulduar Teleporter^前往^Antechamber of Ulduar^。",
    ["After defeating the ^Champions of the Horde^, talk to ^Barrett Ramsey^ again to start the next encounter vs. ^Twin Val'kyr^."] = "击败^Champions of the Horde^后，再次与^Barrett Ramsey^交谈，开始下一场对阵^Twin Val'kyr^的战斗。",
    ["After defeating the ^Chess Event^, leave the room up the stairs to the northeast, and follow the path to a spiral staircase."] = "完成 ^Chess Event^ 后，从房间东北侧楼梯离开，沿路前往螺旋楼梯。",
    ["After defeating the ^Icecrown Gunship Battle^, exit the ship."] = "击败^Icecrown Gunship Battle^后，离开飞艇。",
    ["After defeating the ^Twin Val'kyr^, talk to ^Barrett Ramsey^ again to start the final encounter vs. ^Anub'arak^."] = "击败^Twin Val'kyr^后，再次与^Barrett Ramsey^交谈，开始最终的^Anub'arak^战斗。",
    ["After defeating the ^Valithria Dreamwalker^ encounter, continue south and take the elevator down."] = "完成^Valithria Dreamwalker^战斗后，继续向南并乘电梯下行。",
    ["After killing ^Anetheron^, talk to ^Lady Jaina Proudmoore^ to continue and she will teleport out. Next, take the long road east until you reach the ^Horde Encampment^."] = "击杀 ^Anetheron^ 后，与 ^Lady Jaina Proudmoore^ 交谈继续，她随后会传送离开。接着沿长路向东，直到到达 ^Horde Encampment^。",
    ["After killing ^Attumen the Huntsman^, backtrack towards the entrance and take the stairs behind ^Berthold^."] = "击杀 ^Attumen the Huntsman^ 后，原路返回入口方向，并走 ^Berthold^ 身后的楼梯。",
    ["After killing ^Auriaya^, take the southeast exit towards ^The Halls of Winter^. Follow the path counter-clockwise to reach ^Hodir^. See special note for |cffF259C7Hard Mode|r."] = "击杀^Auriaya^后，从东南出口前往^The Halls of Winter^。沿逆时针方向前进即可到达^Hodir^。请查看|cffF259C7困难模式|r特别提示。",
    ["After killing ^Ayamiss^, head northwest up the stair path until you reach the final boss, ^Ossirian the Unscarred^."] = "击杀^Ayamiss^后，沿楼梯向西北上行，直到最终首领^Ossirian the Unscarred^。",
    ["After killing ^Battleguard Sartura^, continue north until you reach ^Fankriss the Unyielding^."] = "击杀^Battleguard Sartura^后, 继续向北前进，直到到达^Fankriss the Unyielding^.",
    ["After killing ^Blood-Queen Lana'thel^, jump in the hole just south of the boss room."] = "击杀^Blood-Queen Lana'thel^后，跳入首领房间正南方的洞中。",
    ["After killing ^Broodlord Lashlayer^, continue northwest to find ^Firemaw^ patrolling the path ahead."] = "击杀^Broodlord Lashlayer^后，继续向西北前进，在前方路上找到巡逻的^Firemaw^。",
    ["After killing ^Brutallus^, approach ^Felmyst^ nearby to start the next encounter."] = "击杀 ^Brutallus^ 后，靠近附近的 ^Felmyst^，开始下一场遭遇战。",
    ["After killing ^Chromaggus^, exit northeast and follow the path to the next room. Talk to ^Lord Victor Nefarius^ to begin the final encounter against ^Nefarian^."] = "击杀^Chromaggus^后，从东北离开并沿路进入下一个房间。与^Lord Victor Nefarius^交谈，开始与^Nefarian^的最终战斗。",
    ["After killing ^Deathbringer Saurfang^, enter the building behind him."] = "击杀^Deathbringer Saurfang^后，进入他身后的建筑。",
    ["After killing ^Fankriss^, continue southwest until you reach ^Princess Huhuran^."] = "击杀^Fankriss^后, 继续向西南前进，直到到达^Princess Huhuran^.",
    ["After killing ^Fankriss^, take the northeast tunnel out of the room. When you reach the clearing, climb the spiraling walkway to reach ^Viscidus^."] = "击杀^Fankriss^后，从东北隧道离开房间。到达空地后，沿螺旋通道上行前往^Viscidus^。",
    ["After killing ^Felmyst^, go up the northeast ramp and follow the looping path all the way to ^Eredar Twins^."] = "击杀 ^Felmyst^ 后，沿东北坡道上去，沿环形路线一直前往 ^Eredar Twins^。",
    ["After killing ^Flamegor^, continue southeast into the next room to find a lever. Pull it to release ^Chromaggus^."] = "击杀^Flamegor^后，向东南进入下一个房间并找到控制杆。拉动它释放^Chromaggus^。",
    ["After killing ^Garr^, head southeast to reach ^Shazzrah^."] = "击杀^Garr^后, 向东南前进，直到到达^Shazzrah^.",
    ["After killing ^Golemagg the Incinerator^, backtrack up the ramp to reach ^Majordomo Executus^."] = "击杀^Golemagg the Incinerator^后，沿斜坡原路返回上层前往^Majordomo Executus^。",
    ["After killing ^Gurtogg Bloodboil^, go up the stairs just east of his corpse. When you reach the top, go south until you reach ^Reliquary of Souls^."] = "击杀 ^Gurtogg Bloodboil^ 后，走他尸体正东边的楼梯。到顶部后向南走，直到到达 ^Reliquary of Souls^。",
    ["After killing ^High Astromancer Solarian^, backtrack out of the room and head north to find ^Kael'thas Sunstrider^."] = "击杀 ^High Astromancer Solarian^ 后，原路离开房间并向北寻找 ^Kael'thas Sunstrider^。",
    ["After killing ^Ignis^, mount up and backtrack up the path straight ahead to ^Razorscale^. Talk to ^Expedition Commander^ to begin the fight."] = "击杀^Ignis^后，骑上坐骑并沿正前方的道路原路返回^Razorscale^。与^Expedition Commander^交谈以开始战斗。",
    ["After killing ^Kaz'rogal^, talk to ^Thrall^ again to start the encounter against ^Azgalor^."] = "击杀 ^Kaz'rogal^ 后，再次与 ^Thrall^ 交谈，开始与 ^Azgalor^ 的遭遇战。",
    ["After killing ^Leotheras the Blind^, take the eastern exit from the room and follow the path around to find ^Fathom-Lord Karathress^."] = "击杀 ^Leotheras the Blind^ 后，从房间东侧出口离开，沿路绕行寻找 ^Fathom-Lord Karathress^。",
    ["After killing ^Lord Marrowgar^, go up the ramp behind him and follow the path to ^Lady Deathwhisper^."] = "击杀^Lord Marrowgar^后，沿他身后的坡道上行，再沿路前往^Lady Deathwhisper^。",
    ["After killing ^Lucifron^, continue north to reach ^Magmadar^."] = "击杀^Lucifron^后, 继续向北前进，直到到达^Magmadar^.",
    ["After killing ^M'uru^, proceed southwest down the ramp until you reach the Sunwell to face ^Kil'jaeden^. Clear the trash to start the encounter."] = "击杀 ^M'uru^ 后，沿坡道向西南下去，直到到达太阳之井并面对 ^Kil'jaeden^。清理小怪即可开始遭遇战。",
    ["After killing ^Mimiron^, backtrack south to the ^Ulduar Teleporter^. Select ^Conservatory of Life^."] = "击杀^Mimiron^后，向南原路返回^Ulduar Teleporter^，选择^Conservatory of Life^。",
    ["After killing ^Moam^, travel far southeast until you reach ^Buru the Gorger^."] = "击杀^Moam^后, 向东南前进，直到到达^Buru the Gorger^.",
    ["After killing ^Moroes^, backtrack to ^The Grand Ballroom^ and climb the stairwell on the north end of the room."] = "击杀 ^Moroes^ 后，原路返回 ^The Grand Ballroom^，并从房间北端的楼梯上去。",
    ["After killing ^Netherspite^, backtrack to the Ethereal room and take the ramp down this time. Open the ^Gamesman's Hall Door^ to reach the next area. There is a vendor NPC nearby if you need to clear bag space."] = "击杀 ^Netherspite^ 后，原路返回虚灵房间，这次沿坡道下去。打开 ^Gamesman's Hall Door^ 进入下一区域。如果需要清理背包空间，附近有一个商人 NPC。",
    ["After killing ^Princess Huhuran^, travel southeast until you reach ^The Twin Emperors^."] = "击杀^Princess Huhuran^后, 向东南前进，直到到达^The Twin Emperors^.",
    ["After killing ^Razorscale^, return to the main path and go north to reach ^XT-002 Deconstructor^. See special note for |cffF259C7Hard Mode|r."] = "击杀^Razorscale^后，返回主路并向北前往^XT-002 Deconstructor^。请查看|cffF259C7困难模式|r特别提示。",
    ["After killing ^Rotface^, click the ^Ooze Release Valve^ on the right side of the exit door. Then follow the path to ^Professor Putricide^."] = "击杀^Rotface^后，点击出口门右侧的^Ooze Release Valve^，然后沿路前往^Professor Putricide^。",
    ["After killing ^Shazzrah^, you will find ^Baron Geddon^ patrolling the northeast path."] = "击杀^Shazzrah^后，你会在东北路径上找到巡逻的^Baron Geddon^。",
    ["After killing ^Sindragosa^, backtrack slightly up the stairs and head up the western ramp to reach a ^Scourge Transporter^. Use it to teleport to ^Upper Spire^."] = "击杀^Sindragosa^后，沿楼梯稍微返回，再走上西侧坡道找到^Scourge Transporter^。使用它传送到^Upper Spire^。",
    ["After killing ^Sulfuron Harbinger^, go north and west to ^Golemagg the Incinerator^."] = "击杀^Sulfuron Harbinger^后，向北再向西前往^Golemagg the Incinerator^。",
    ["After killing ^Teron Gorefiend^, backtrack towards the main concourse."] = "击杀 ^Teron Gorefiend^ 后，原路返回主大厅。",
    ["After killing ^The Curator^, proceed past him and follow the ramps through the library."] = "击杀 ^The Curator^ 后，从他身边继续前进，沿坡道穿过图书馆。",
    ["After killing ^The Illidari Council^, talk to ^Akama^ and follow him up the ramp. After some dialog, he will open the door to the final area."] = "击杀 ^The Illidari Council^ 后，与 ^Akama^ 交谈并跟随他上坡。经过一段对话后，他会打开通往最终区域的门。",
    ["After killing ^The Lurker Below^, go up a nearby ramp and work your way up the path to ^Leotheras the Blind^."] = "击杀 ^The Lurker Below^ 后，沿附近的坡道上去，再沿路向上前往 ^Leotheras the Blind^。",
    ["After killing ^The Prophet Skeram^, climb the stairs behind him. After the fork, make your way down some stairs on your way underneath the platform you just walked across."] = "击杀^The Prophet Skeram^后，走他身后的楼梯。经过岔路后，下几级楼梯，从刚刚走过的平台下方通过。",
    ["After landing, follow the path east and then south to reach ^Valithria Dreamwalker^. As you approach, kill all trash to advance the NPCs."] = "落地后，沿路向东再向南前往^Valithria Dreamwalker^。靠近时清理所有敌人，让NPC继续推进。",
    ["After landing, follow the path east towards ^Valithria Dreamwalker^. As you approach her room, kill all trash to advance the NPCs. Walk around the outer edge to avoid pulling on the way to the elevator."] = "落地后，沿路向东前往^Valithria Dreamwalker^。接近她的房间时，清掉所有小怪以推进NPC。沿房间外圈前进，避免在前往电梯时引到怪。",
    ["After reaching the bottom of the elevator, proceed north into the next area. Kill waves of adds until the northern door opens, and continue ahead to reach ^Sindragosa^. Clear trash to pull the mini-bosses."] = "到达电梯底部后，向北进入下一个区域。击杀一波波敌人，直到北侧大门打开，再继续前往^Sindragosa^。清理敌人以引出小首领。",
    ["After reaching the top of the elevator, follow the path to the east until you arrive on the ship. Talk to ^High Overlord Saurfang^ to start the encounter."] = "到达电梯顶部后，沿东侧道路前往飞艇。与^High Overlord Saurfang^交谈以开始战斗。",
    ["After reaching the top of the elevator, follow the path to the west until you arrive on the ship. Talk to ^Muradin Bronzebeard^ to start the encounter."] = "到达电梯顶部后，沿西侧道路前往飞艇。与^Muradin Bronzebeard^交谈以开始战斗。",
    ["After teleporting, follow the path ahead and take a left before you reach the stairs. Continue down the path to reach ^The Assembly of Iron^. See special note for |cffF259C7Hard Mode|r."] = "传送后沿前方道路前进，在到达楼梯前左转。继续沿路前往^The Assembly of Iron^。请查看|cffF259C7困难模式|r特别提示。",
    ["After teleporting, go north and take a right before the stairs. Follow the path around until you reach a console called ^Celestial Planetarium Access^. Click it to open the door to ^Algalon the Observer^."] = "传送后向北走，在楼梯前右转。沿路前进，直到找到名为^Celestial Planetarium Access^的控制台。点击它打开通往^Algalon the Observer^的门。",
    ["After teleporting, proceed to the center of the ring and step on the teleporter."] = "传送后前往环形区域中央，站上传送器。",
    ["After teleporting, travel southwest to the ^Hall of Memories^."] = "传送后向西南前往^Hall of Memories^。",
    ["After the tram stops, exit north and follow the path straight ahead to reach ^Mimiron^. See special note for |cffF259C7Hard Mode|r."] = "轨道车停下后，从北侧下车并沿路直行前往^Mimiron^。请查看|cffF259C7困难模式|r特别提示。",
    ["After zoning in, beware the legendary elevator boss! Go down to reach the next area, then take the southern path to ^Hydross the Unstable^."] = "进入副本后，小心传说中的电梯首领！下到下一区域，然后沿南侧路线前往 ^Hydross the Unstable^。",
    ["After zoning in, beware the legendary elevator boss! Go down to reach the next area. Take a left when you reach ^Hydross the Unstable^ and follow the path all the way around until you reach the ^Lady Vashj Bridge Console^. Click the console to open the bridge, then cross it to reach the final boss, ^Lady Vashj^."] = "进入副本后，小心传说中的电梯首领！下到下一区域。到达 ^Hydross the Unstable^ 后左转，沿路绕一整圈直到到达 ^Lady Vashj Bridge Console^。点击控制台打开桥梁，然后过桥前往最终首领 ^Lady Vashj^。",
    ["After zoning in, follow the linear path all the way to ^Kalecgos^."] = "进入副本后，沿直线路线一直前往 ^Kalecgos^。",
    ["After zoning in, follow the linear path up the ramps until you reach ^High Warlord Naj'entus^."] = "进入副本后，沿直线路线上坡，直到到达 ^High Warlord Naj'entus^。",
    ["After zoning in, follow the path around and up some stairs to reach the first boss, ^The Prophet Skeram^."] = "进入副本后，沿路绕行并上几段楼梯，前往第一个首领^The Prophet Skeram^。",
    ["After zoning in, follow the path through ^Al'ar^'s room and continue north until you reach ^Kael'thas Sunstrider^."] = "进入副本后，沿路穿过 ^Al'ar^ 的房间并继续向北，直到到达 ^Kael'thas Sunstrider^。",
    ["After zoning in, follow the path to ^Lucifron^."] = "进入副本后，沿路前往^Lucifron^。",
    ["After zoning in, follow the southern path to reach ^Magtheridon^."] = "进入副本后，沿南侧路线前往 ^Magtheridon^。",
    ["After zoning in, move forward and take your first left to reach ^Koralon the Flame Watcher^."] = "进入副本后向前走，在第一个路口左转前往^Koralon the Flame Watcher^。",
    ["After zoning in, proceed ahead to ^Al'ar^. You may need to walk up a ramp to pull the boss."] = "进入副本后，向前前往 ^Al'ar^。你可能需要走上坡道才能开怪。",
    ["After zoning in, proceed ahead to ^High King Maulgar^."] = "进入副本后，向前前往 ^High King Maulgar^。",
    ["After zoning in, proceed straight ahead to ^Razorgore^. |cffF259C7CAUTION!|r Do not attack ^Razorgore^ directly. Review the note!"] = "进入副本后，直走前往^Razorgore^。|cffF259C7小心！|r 不要直接攻击^Razorgore^。请阅读提示！",
    ["After zoning in, proceed straight ahead until you reach ^Lord Marrowgar^."] = "进入副本后一直向前，直到到达^Lord Marrowgar^。",
    ["After zoning in, proceed up to the left and work your way through the ^Livery Stables^ until you reach ^Attumen the Huntsman^."] = "进入副本后，向左上方前进，穿过 ^Livery Stables^，直到到达 ^Attumen the Huntsman^。",
    ["After zoning in, take a right and follow the path to ^Kurinnaxx^."] = "进入副本后，右转并沿路前往^Kurinnaxx^。",
    ["After zoning in, talk to ^Barrett Ramsey^ and then approach the middle ring to start the battle against ^The Northrend Beasts^."] = "进入副本后，与^Barrett Ramsey^交谈，再靠近中央圆环，开始对阵^The Northrend Beasts^的战斗。",
    ["After zoning in, talk to ^Brann Bronzebeard^ to begin the encounter with ^Flame Leviathan^. See special note for |cffF259C7Hard Mode|r."] = "进入副本后，与^Brann Bronzebeard^交谈以开始^Flame Leviathan^战斗。请查看|cffF259C7困难模式|r特别提示。",
    ["After zoning into the landing area, take the left portal to zone into the raid."] = "进入着陆区域后，走左侧传送门进入团队副本。",
    ["Ahead and left to Koralon"] = "向前再左转前往科拉隆",
    ["Ahead to Al'ar"] = "直走前往 Al'ar",
    ["Ahead to Broodlord"] = "直走前往Broodlord",
    ["Ahead to High King Maulgar"] = "直走前往 High King Maulgar",
    ["Ahead to Marrowgar"] = "向前前往玛洛加尔领主",
    ["Ahead to Netherspite"] = "直走前往 Netherspite",
    ["Ahead to Prince"] = "直走前往王子",
    ["Al'Akir also drops {item}, an omnitoken that allows you to purchase any Tier 11 set piece of matching quality. Not tracked here."] = "Al'Akir还会掉落{item}，这是一种万能徽记，可购买任意同品质的T11套装部件。此处不追踪。",
    ["Alchemy Lab"] = "炼金实验室",
    ["Approach Felmyst to pull"] = "靠近 Felmyst 开怪",
    ["Armaments"] = "武器",
    ["As you work your way up, stay to the right and follow the path into a room where you will find ^C'Thun^!"] = "上行时靠右，沿路进入一个房间，你会在那里找到^C'Thun^！",
    ["Aspirant Forudir"] = "Aspirant Forudir",
    ["Aspirant Naradiel"] = "Aspirant Naradiel",
    ["Assembled from 30 Fragments of Val'anyr, which drop across Ulduar; the hammer is forged during the Yogg-Saron encounter."] = "由30个瓦兰奈尔的碎片组装而成，这些碎片会在奥杜尔各处掉落；锤子在与尤格-萨隆的战斗中铸成。",
    ["At bottom go west to Royalty"] = "到底后向西前往Royalty",
    ["At the top of the ramp, continue ahead until you reach ^Netherspite^."] = "到达坡道顶部后，继续向前直到到达 ^Netherspite^。",
    ["Awarded together at the end of a long Rogue chain that begins by pickpocketing Hagara the Stormbinder."] = "一条漫长的潜行者任务线最终会同时奖励这两件物品，任务从偷窃缚风者哈格拉开始。",
    ["Back in the library, continue up the ramps and open the ^Private Library Door^ to reach ^Shade of Aran^. Note: Killing this boss unlocks a teleport from the entrance NPC to this room, if you need to leave/logout and come back later."] = "回到图书馆后，继续沿坡道向上，并打开 ^Private Library Door^ 前往 ^Shade of Aran^。注意：击杀这个首领后，会解锁从入口 NPC 传送到这个房间的功能，方便你离开/下线后稍后回来。",
    ["Back in the main concourse, take the northern exit and go up some stairs."] = "回到主大厅后，从北侧出口离开并上几段楼梯。",
    ["Backtrack ahead to Razorscale"] = "原路返回前往锋鳞",
    ["Backtrack and take ramp down"] = "原路返回并下坡",
    ["Backtrack path to Sartura"] = "原路返回Sartura",
    ["Backtrack south then left to Emalon"] = "向南返回再左转前往埃玛尔隆",
    ["Backtrack then left to Toravon"] = "原路返回再左转前往图拉旺",
    ["Backtrack then north to Council"] = "原路返回再向北前往议会",
    ["Backtrack then upstairs"] = "原路返回后上楼",
    ["Backtrack through bookcase"] = "穿过书架原路返回",
    ["Backtrack to main concourse"] = "返回主大厅",
    ["backtrack to stairs for Kologarn"] = "返回楼梯前往科隆加恩",
    ["Backtrack up to Majordomo"] = "返回上层前往Majordomo",
    ["Baron Geddon patrolling northeast"] = "Baron Geddon在东北方向巡逻",
    ["Behind the bookshelf, proceed down the ramp until you reach ^Terestian Illhoof^."] = "在书架后面，沿坡道向下直到到达 ^Terestian Illhoof^。",
    ["Blackhand also drops Essence Tokens, which are omnitokens that you redeem for any Tier 17 set piece of matching quality. Not tracked here."] = "Blackhand还会掉落精华徽记，这是一种万能徽记，可兑换任意同品质的T17套装部件。此处不追踪。",
    ["Boots"] = "靴子",
    ["Buy base items and redeem tier tokens at:"] = "在此购买基础物品并兑换套装徽记：",
    ["Bypass Valithria on the outer edge"] = "沿外圈绕过Valithria",
    ["Cannot skip from here -- keep going until the route reaches the next boss."] = "此处无法跳过 -- 继续前进，直到路线到达下一个首领。",
    ["Caster Weapons"] = "法系武器",
    ["Chest"] = "胸部",
    ["Click Bookshelf"] = "点击书架",
    ["Click Lever"] = "点击控制杆",
    ["Click on Blackened Urn"] = "点击 Blackened Urn",
    ["Click the ^Disconcerting Bookshelf^ to open a secret passage."] = "点击 ^Disconcerting Bookshelf^ 打开一条秘密通道。",
    ["Click the nearby portal"] = "点击附近的传送门",
    ["Click the portal near The Frozen Throne to be teleported near the entrance"] = "点击冰封王座附近的传送门，传送到入口附近",
    ["Click Urn"] = "点击骨灰瓮",
    ["Click Valve then Professor"] = "点击阀门，再前往教授",
    ["Click Valve then Rotface"] = "点击阀门，再前往腐面",
    ["Click Valve"] = "点击阀门",
    ["Cloaks"] = "披风",
    ["Conquest sold for gold/silver"] = "征服可用金币/银币购买",
    ["Console then bridge to Vashj"] = "控制台后过桥到 Vashj",
    ["Continue along the path until you reach a room with Ethereal enemies, and take the ramp up."] = "继续沿路前进，直到到达有虚灵敌人的房间，然后沿坡道上去。",
    ["Continue backtracking to main concourse. When you reach it, cut through the platform and take the northeast path out of this room."] = "继续原路返回主大厅。到达后，穿过平台并从这个房间的东北路线离开。",
    ["Continue climbing"] = "继续向上",
    ["Continue climbing."] = "继续向上。",
    ["Continue north through the ^Opera Hall Balcony^ and climb the ramp at the end."] = "继续向北穿过 ^Opera Hall Balcony^，并在尽头沿坡道上去。",
    ["Continue south to the elevator and take it down."] = "继续向南前往电梯并乘坐向下。",
    ["Continue to Gruul"] = "继续前往 Gruul",
    ["Continue up the ramp/stairs"] = "沿坡道/楼梯继续向上",
    ["Continue up the spiral stairwell."] = "继续沿螺旋楼梯向上。",
    ["Continue up the stairs into ^The Grand Ballroom^. Take a left into ^The Banquet Hall^ and find ^Moroes^ up on a small platform."] = "继续上楼进入 ^The Grand Ballroom^。左转进入 ^The Banquet Hall^，在一个小平台上找到 ^Moroes^。",
    ["Continue up the stairs"] = "继续上楼",
    ["Continue up the stairs. When you reach the top, follow the path to ^Mother Shahraz^."] = "继续上楼。到达顶部后，沿路前往 ^Mother Shahraz^。",
    ["Continue working your way up the ramp and stairs."] = "继续沿坡道和楼梯向上。",
    ["Crafted from the Bindings of the Windseeker. Garr and Baron Geddon each drop one half."] = "由逐风者禁锢之颅制成。加尔和迦顿男爵各掉落一半。",
    ["Crafted from the Eye of Sulfuras, a rare drop from Ragnaros."] = "由萨弗拉斯之眼制成，这是拉格纳罗斯的稀有掉落。",
    ["Cross bridge, downstairs to Inner Sanctum"] = "过桥下楼前往内殿",
    ["Do not attack ^Razorgore^ directly or you will wipe. To start the encounter properly, kill the adds on the opposite platform. Immediately click the ^Orb of Domination^ to mind control the boss. As quickly as you can, destroy all eggs in the room. You can do this by walking to each one and pressing the action button for ^Destroy Egg^. After you've killed the last egg, the mind control will end and you can kill ^Razorgore^. If you run out of time, kill adds and click the orb again to finish off the remaining eggs."] = "不要直接攻击^Razorgore^，否则会灭团。要正确开始战斗，先击杀对面平台上的小怪。立即点击^Orb of Domination^精神控制首领。尽快摧毁房间里的所有龙蛋。走到每个龙蛋旁，按下^Destroy Egg^的动作按钮。摧毁最后一个龙蛋后，精神控制会结束，你就可以击杀^Razorgore^。如果时间不够，击杀小怪并再次点击宝珠，处理剩余龙蛋。",
    ["Down ramp to Illhoof"] = "下坡前往 Illhoof",
    ["Down to Kil'jaeden"] = "向下前往 Kil'jaeden",
    ["East path to Karathress"] = "东侧路线前往 Karathress",
    ["East then South to Valithria"] = "向东再向南前往踏梦者",
    ["East to Console then Algalon"] = "向东前往控制台，再前往奥尔加隆",
    ["East to Gorefiend's Vigil"] = "向东前往 Gorefiend's Vigil",
    ["East to Morogrim"] = "向东前往 Morogrim",
    ["East to spiral staircase"] = "向东前往螺旋楼梯",
    ["East to Sulfuron"] = "向东前往Sulfuron",
    ["East towards Brutallus"] = "向东前往 Brutallus",
    ["Enter building"] = "进入建筑",
    ["Essence Tokens"] = "精华徽记",
    ["Exit east, then up the ramp"] = "向东离开后上坡",
    ["Exit library then left"] = "离开图书馆后左转",
    ["Exit South"] = "南侧出口",
    ["Exit the ship"] = "离开飞艇",
    ["Exit tram to Mimiron"] = "下轨道车前往米米尔隆",
    ["Expedition Commander"] = "远征军指挥官",
    ["Feel free to return and kill any bosses you skipped!"] = "你可以随时返回并击杀之前跳过的首领！",
    ["Find Auriaya circling"] = "找到绕场巡逻的欧尔莉亚",
    ["Firestone Vendor"] = "火石商人",
    ["Fish up The Lurker Below"] = "钓起 The Lurker Below",
    ["Flamegor ahead"] = "直走前往Flamegor",
    ["Follow ^Akama^ into the next area. Talk to him to start the final battle against ^Illidan Stormrage^."] = "跟随 ^Akama^ 进入下一区域。与他交谈，开始与 ^Illidan Stormrage^ 的最终战斗。",
    ["Follow path to Lucifron"] = "沿路前往Lucifron",
    ["Follow the path south and continue on to ^The Illidari Council^."] = "沿路向南并继续前往 ^The Illidari Council^。",
    ["Follow the path through the next area until you reach ^Teron Gorefiend^."] = "沿路穿过下一区域，直到到达 ^Teron Gorefiend^。",
    ["Forward then left to Ignis"] = "向前再左转前往掌炉者",
    ["From the bottom of the stairs, take a hard left and descend into the tunnels."] = "到楼梯底部后大幅左转，向下进入隧道。",
    ["From the top of the stairs, take your first right. Travel east down the hallway until you reach ^Maiden of Virtue^."] = "从楼梯顶部第一个路口右转。沿走廊向东，直到到达 ^Maiden of Virtue^。",
    ["Garrosh also drops {tokens}, which are omnitokens that allow you to purchase any Tier 16 set piece of matching quality. Not tracked here."] = "Garrosh还会掉落{tokens}，这是一种万能徽记，可购买任意同品质的T16套装部件。此处不追踪。",
    ["Go down elevator"] = "乘电梯下去",
    ["Go up ramp"] = "上斜坡",
    ["Grand Ballroom north stairs"] = "Grand Ballroom 北侧楼梯",
    ["Halion in Middle"] = "哈里昂在中央",
    ["Head"] = "头部",
    ["Heal or bandage the boss to defeat this encounter. If you want to skip her, run along the outer edge of the room without pulling anything on your way to the elevator."] = "治疗首领或对其使用绷带以完成战斗。若要跳过她，沿房间外缘前往电梯，途中不要引到任何敌人。",
    ["Heal or bandage the boss to defeat this encounter. If you want to {skip} her, run along the outer edge of the room without pulling anything on your way to the elevator."] = "治疗或给首领打绷带即可完成这场战斗。如果想要{skip}她，就沿房间外圈跑向电梯，不要引到任何怪。",
    ["In Dalaran"] = "在达拉然",
    ["In Mount Hyjal"] = "在海加尔山",
    ["In the large outdoor area, make your way up the middle path to ^Supremus^."] = "在大型室外区域，沿中间路线向上前往 ^Supremus^。",
    ["In the next area, continue following the path until you reach ^Blood-Queen Lana'thel^."] = "在下一个区域继续沿路前进，直到到达^Blood-Queen Lana'thel^。",
    ["In the next area, head north then go down the stairs on your left. Follow this path until you reach ^Gurtogg Bloodboil^."] = "在下一区域，先向北走，再从左侧楼梯下去。沿这条路一直走到 ^Gurtogg Bloodboil^。",
    ["In the next area, take a right and travel south until you reach ^Akama^. Talk to him to begin the battle against ^Shade of Akama^."] = "在下一区域，右转并向南走，直到到达 ^Akama^。与他交谈，开始与 ^Shade of Akama^ 的战斗。",
    ["In the next area, work your way down the platforms and follow the path to ^General Vezax^. See special note for |cffF259C7Hard Mode|r."] = "在下一个区域逐层向下，通过平台并沿路前往^General Vezax^。请查看|cffF259C7困难模式|r特别提示。",
    ["In the next room, ^Flamegor^ will be flying around right in front of you."] = "下一个房间里，^Flamegor^会在你正前方飞行。",
    ["Inside Firelands"] = "火焰之地内部",
    ["Inside ICC"] = "冰冠堡垒内",
    ["Inside the building, take a series of lefts as you work your way around to ^Festergut^."] = "进入建筑后，连续左转，绕行前往^Festergut^。",
    ["Inside the raid, talk to ^Lady Jaina Proudmoore^ to start the encounter with ^Rage Winterchill^."] = "在团队副本内，与 ^Lady Jaina Proudmoore^ 交谈，开始与 ^Rage Winterchill^ 的遭遇战。",
    ["Jaina, then east to the encampment"] = "Jaina 后向东去营地",
    ["Jump in lava"] = "跳进熔岩",
    ["Kill (8) waves of trash and the boss will come.  Infernals will drop out of the sky all over the area."] = "击杀 (8) 波小怪后，首领就会出现。  地狱火会从天空落到整个区域。",
    ["Kill (8) waves of trash and the boss will come.  Some waves will include gargoyles in the back area."] = "击杀 (8) 波小怪后，首领就会出现。  部分波次会在后方区域出现石像鬼。",
    ["Kill (8) waves of trash and the boss will come."] = "击杀 (8) 波小怪后，首领就会出现。",
    ["Kill East Mini-boss"] = "击杀东侧小首领",
    ["Kill South Mini-boss"] = "击杀南侧小首领",
    ["Kill the ^Ashtongue Channelers^ and the boss will start slowly moving towards ^Akama^. When he reaches ^Akama^, you can kill him."] = "击杀 ^Ashtongue Channelers^ 后，首领会开始慢慢向 ^Akama^ 移动。等他到达 ^Akama^ 后，就可以击杀他。",
    ["Kill the enemy king before yours dies. The easy button: take control of your king and spam Heroism or Bloodlust until it's over. It takes a few minutes, but it works."] = "在你的国王死亡前击杀敌方国王。最简单的方法：控制你的国王，然后不停使用英勇或嗜血，直到结束。需要几分钟，但确实有效。",
    ["Kill trash until door opens"] = "清理敌人直到门打开",
    ["Kill trash until harpoons become active. Use an active harpoon (4) times to bring down the boss, then kill him."] = "清理敌人，直到鱼叉可用。使用可用的鱼叉（4）次把首领拉下来，然后将其击杀。",
    ["Kill West Mini-boss"] = "击杀西侧小首领",
    ["Left into tunnels"] = "左转进入隧道",
    ["Left portal to enter raid"] = "左侧传送门进入团队副本",
    ["Left to Huntsman"] = "向左前往 Huntsman",
    ["Legs"] = "腿部",
    ["Long path to Kalecgos"] = "长路前往 Kalecgos",
    ["Moroes in Banquet Hall"] = "Banquet Hall 内的 Moroes",
    ["Mount up and ride north to the boss area. Clear trash until the boss spawns. Vehicles optional.\n\n|cffF259C7HARD MODE:|r Talk to ^Lore Keeper of Norgannon^ at the Expedition Camp to activate the towers, and leave them active during the boss fight."] = "骑上坐骑向北前往首领区域。清理敌人，直到首领出现。载具可用可不用。\n\n|cffF259C7困难模式：|r在远征营地与^Lore Keeper of Norgannon^交谈以激活塔楼，并在首领战期间保持塔楼激活。",
    ["Next, kill ^General Zarithrian^ to the south."] = "接下来，击杀南侧的^General Zarithrian^。",
    ["Next, kill ^Saviana Ragefire^ to the west."] = "接下来，击杀西侧的^Saviana Ragefire^。",
    ["No token vendor data available."] = "暂无徽记商人数据。",
    ["North all the way to Kael"] = "一路向北前往 Kael",
    ["North and west to Golemagg"] = "向北再向西前往Golemagg",
    ["North to Archavon"] = "向北前往阿尔卡冯",
    ["North to Fankriss"] = "向北前往Fankriss",
    ["North to Freya"] = "向北前往弗蕾亚",
    ["North to Kael"] = "向北前往 Kael",
    ["North to Magmadar"] = "向北前往Magmadar",
    ["North to XT-002"] = "向北前往XT-002",
    ["Northeast from main concourse"] = "从主大厅向东北",
    ["Northeast to Nefarian"] = "向东北前往Nefarian",
    ["Northeast to Thorim"] = "向东北前往托里姆",
    ["Northeast to Viscidus"] = "向东北前往Viscidus",
    ["Northern exit, up stairs"] = "北侧出口，上楼",
    ["Northwest path to Leotheras"] = "西北路线前往 Leotheras",
    ["Northwest to Activate Tram"] = "向西北启动轨道车",
    ["Northwest to Ebonroc"] = "向西北前往Ebonroc",
    ["Northwest to Firemaw"] = "向西北前往Firemaw",
    ["Northwest to Moam"] = "向西北前往Moam",
    ["Northwest to Ossirian"] = "向西北前往Ossirian",
    ["Northwest to spiral"] = "向西北前往spiral",
    ["Northwest to Vaelastrasz"] = "向西北前往Vaelastrasz",
    ["Northwest to Void Reaver"] = "向西北前往 Void Reaver",
    ["Note: Routing will not be available on this lockout"] = "注意：本次副本锁定期间无法使用路线导航",
    ["Once it becomes available, click the Gunship Cannon and shoot at the enemy ship a few times to win the battle."] = "火炮可用后，点击飞艇火炮并向敌方飞艇射击数次即可获胜。",
    ["Once the fight begins, click the ^Lever^ to open the gate and make your way through the gauntlet, killing all trash along the way. In the final hallway approaching ^Thorim^, go AROUND the large circles on the ground to avoid lengthy stuns.\n\n|cffF259C7HARD MODE:|r Reach him within 3 minutes of starting the gauntlet."] = "战斗开始后，点击^Lever^打开大门，沿挑战路线前进并清理所有敌人。在接近^Thorim^的最后一段走廊中，绕开地面上的大圆圈，以免被长时间昏迷。\n\n|cffF259C7困难模式：|r在挑战开始后的3分钟内到达他身边。",
    ["Once you reach ^Master's Terrace^, loop around and click on the ^Blackened Urn^. After a short delay, ^Nightbane^ will fly in to be killed by you."] = "到达 ^Master's Terrace^ 后，绕一圈并点击 ^Blackened Urn^。稍等片刻后，^Nightbane^ 会飞来供你击杀。",
    ["Once you reach ^The Observation Ring^, you will find ^Auriaya^ slowly circling the room."] = "到达^The Observation Ring^后，你会看到^Auriaya^正在房间内缓慢巡逻。",
    ["Once you reach the top of the stairs, follow the path ahead to reach ^Prince Malchezaar^."] = "到达楼梯顶部后，沿前方路线继续前往 ^Prince Malchezaar^。",
    ["Path downstairs to Gurtogg"] = "下楼路线前往 Gurtogg",
    ["Path left to Assembly of Iron"] = "走左侧通道前往钢铁议会",
    ["Path north to Solarian"] = "北侧路线前往 Solarian",
    ["Path south to Council"] = "南侧路线前往 Council",
    ["Path to Barnes to start Opera"] = "前往 Barnes 开始 Opera",
