    ["Physical Weapons"] = "物理武器",
    ["Pickpocketing Hagara starts a long Rogue chain that eventually rewards {item1} and {item2}. Both are listed under Madness of Deathwing."] = "偷窃Hagara会开启一条漫长的潜行者任务线，最终奖励{item1}和{item2}。两者都列在Madness of Deathwing下。",
    ["Purchase ToC Tier 9 appearances:"] = "购买十字军的试炼T9外观：",
    ["Quest reward from Highlord Mograine's chain; requires 50 Shadowfrost Shards from 25-player Heroic bosses."] = "大领主莫格莱尼任务线的奖励；需要从25人英雄难度首领处获得50个影霜碎片。",
