    ["Travel along the ledge into the next room. Stick to one side of the room to avoid overlapping auras, and click ^Suppression Devices^ to temporarily disable them as you move through the room."] = "沿平台边缘进入下一个房间。贴着房间一侧前进以避免光环重叠，并点击^Suppression Devices^暂时关闭它们。",
    ["Triumph and Conquest appearances are shared, "] = "凯旋与征服外观共用， ",
