    ["Viscidus requires you to freeze him and then shatter him with physical/melee damage within a time limit. For most classes, soloing this will require gimmicky strategies involving special trinkets/toys. You can {skip} this boss if you don't have the kit or the patience for it."] = "Viscidus需要先被冻结，然后在限时内用物理/近战伤害将其击碎。对大多数职业来说，单刷需要借助特殊饰品/玩具等技巧。若没有合适的装备或耐心，可以{skip}这个首领。",
    ["Weapon Quest NPCs"] = "武器任务NPC",
    ["Weapons"] = "武器",
    ["West through pipe"] = "向西穿过管道",
    ["West to Gehennas"] = "向西前往Gehennas",
    ["When you reach the bottom of the tunnels, go west into the room and find ^Silithid Royalty^."] = "到达隧道底部后，向西进入房间并找到^Silithid Royalty^。",
    ["When you reach the top of the stairs, continue following the path to reach ^The Curator^."] = "到达楼梯顶部后，继续沿路前往 ^The Curator^。",
    ["With all (3) mini-bosses dead, approach the middle area to engage ^Halion^."] = "全部（3）个小首领死亡后，靠近中央区域与^Halion^交战。",
    ["Work your way down the long southeast path towards ^Master's Terrace^."] = "沿漫长的东南路线向下，前往 ^Master's Terrace^。",
    ["Wrap around to ramp"] = "绕到坡道",
    ["Yields: %s"] = "可获得：%s",
    ["You can jump in the lava to die, and you will respawn at the entrance."] = "你可以跳进熔岩自杀，然后会在入口处复活。",
    ["You must kill all 3 mini-bosses to spawn ^Halion^. Start with ^Baltharus the Warborn^ to the east."] = "必须击杀全部3个小首领才能召唤^Halion^。先击杀东侧的^Baltharus the Warborn^。",
    ["You will find ^Broodlord Lashlayer^ at the end of the next room."] = "你会在下一个房间尽头找到^Broodlord Lashlayer^。",
    ["Zone out first"] = "请先离开副本",
    ["{dot} = Base item, bought with gold\n"] = "{dot} = 基础物品，使用金币购买\n",
    ["{upArrow} = Trash drops can be upgraded to a Heroic appearance with {item}."] = "{upArrow} = 小怪掉落可使用{item}升级为英雄难度外观。",
    ["|cff888888        * |r%s"] = "|cff888888        * |r%s",
    ["|cff888888     * %s: |r|cffffffff%s|r"] = "|cff888888     * %s: |r|cffffffff%s|r",
    ["|cff888888     * %s: |r|cffffffff%s|r|cff888888 for |r%s"] = "|cff888888     * %s: |r|cffffffff%s|r|cff888888 用于 |r%s",
    ["|cff888888  -> Redeem tokens at |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r"] = "|cff888888  -> 在此兑换徽记 |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r",
    ["|cff888888  -> Redeem tokens at |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r|cff888888 (|r|cffffffff%s|r|cff888888)|r"] = "|cff888888  -> 在此兑换徽记 |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r|cff888888 (|r|cffffffff%s|r|cff888888)|r",
    ["|cff888888  -> |r|cffffffff%s|r|cff888888 -- |r|cffffffff%s|r"] = "|cff888888  -> |r|cffffffff%s|r|cff888888 -- |r|cffffffff%s|r",
    ["|cffF259C7HARD MODE:|r Allow (6) ^Saronite Vapors^ to spawn without killing them. This will spawn a ^Saronite Animus^ around the 3 minute mark. Defeat the Animus then defeat the boss."] = "|cffF259C7困难模式：|r让（6）个^Saronite Vapors^出现，但不要击杀。大约3分钟时会生成一个^Saronite Animus^。先击败畸体，再击败首领。",
    ["|cffF259C7HARD MODE:|r Click the Big Red Button before starting the boss fight."] = "|cffF259C7困难模式：|r在开始首领战前点击大红按钮。",
    ["|cffF259C7HARD MODE:|r Kill him in under 2 minutes."] = "|cffF259C7困难模式：|r在2分钟内将其击杀。",
    ["|cffF259C7HARD MODE:|r Kill Steelbreaker last."] = "|cffF259C7困难模式：|r最后击杀断钢者。",
    ["|cffF259C7HARD MODE:|r Leave the elders alive."] = "|cffF259C7困难模式：|r让长者保持存活。",
    ["|cffF259C7HARD MODE:|r Wait for an add phase and destroy the heart."] = "|cffF259C7困难模式：|r等待小怪阶段并摧毁心脏。",
    ["|cffF259C7Phase 1:|r Run through clouds to spawn Guardians. Kill them near Sara. |cffF259C7Phase 2:|r Kill adds until portals appear. Click one to go inside Yogg. |cffF259C7Phase 3:|r Kill all of the tentacles to open the path to Yogg's brain. Kill it to be returned to the outside where you can now attack Yogg directly.\n\n|cffF259C7HARD MODE:|r Kill the boss without accepting help from the keepers. Zero keepers is required for ^Mimiron's Head^."] = "|cffF259C7阶段1：|r穿过云雾召唤守护者，并在萨拉附近击杀。|cffF259C7阶段2：|r清理小怪直到传送门出现，点击一个进入尤格体内。|cffF259C7阶段3：|r击杀所有触须，打开通往尤格大脑的道路。摧毁大脑后会返回外部，此时可以直接攻击尤格。\n\n|cffF259C7困难模式：|r不要接受守护者帮助并击败首领。要获得^Mimiron's Head^，必须是零守护者。",
    -- End route content translations

